      // =========================
      // Debug summary UI
      // =========================
      function formatList(ids, max = 14){
        if (!ids.length) return "なし";
        const head = ids.slice(0, max).join(", ");
        const tail = ids.length > max ? ` …(+${ids.length - max})` : "";
        return head + tail;
      }

      function updateDataStatus(){
        const ok = (data.words.length === data.maxId) && data.missing.length === 0 && data.duplicates.length === 0 && data.parseErrors.length === 0;
        const parts = [];
        parts.push(ok ? `OK（${data.words.length}/${data.maxId}）` : `注意（${data.words.length}/${data.maxId}）`);
        if (data.missing.length) parts.push(`欠番: ${formatList(data.missing)}`);
        if (data.duplicates.length) parts.push(`重複: ${formatList(data.duplicates)}`);
        if (data.parseErrors.length) parts.push(`解析: ${formatList(data.parseErrors)}`);
        if (data.addedRawCheck?.missingAddedRange?.length) parts.push(`追加範囲欠番: ${formatList(data.addedRawCheck.missingAddedRange)}`);
        if (data.addedRawCheck?.duplicates?.length) parts.push(`追加範囲重複: ${formatList(data.addedRawCheck.duplicates)}`);
        if (data.addedRawCheck?.legacyCollisions?.length) parts.push(`1〜600衝突: ${formatList(data.addedRawCheck.legacyCollisions)}`);
        el.dataStatusText.textContent = parts.join(" / ");
      }

      function updateDebugBar(){
        if (!state.settings.debug){
          el.debugBar.textContent = "";
          return;
        }
        const lines = [];
        if (data.missing.length) lines.push(`欠番: ${formatList(data.missing)}`);
        if (data.duplicates.length) lines.push(`重複: ${formatList(data.duplicates)}`);
        if (data.parseErrors.length) lines.push(`解析エラー: ${formatList(data.parseErrors)}`);
        if (data.addedRawCheck?.missingAddedRange?.length) lines.push(`追加範囲欠番: ${formatList(data.addedRawCheck.missingAddedRange)}`);
        if (data.addedRawCheck?.duplicates?.length) lines.push(`追加範囲重複: ${formatList(data.addedRawCheck.duplicates)}`);
        if (data.addedRawCheck?.legacyCollisions?.length) lines.push(`1〜600衝突: ${formatList(data.addedRawCheck.legacyCollisions)}`);

        if (!lines.length){
          el.debugBar.textContent = "";
          return;
        }
        el.debugBar.innerHTML = `<strong>Data check</strong> — ${lines.join(" / ")}`;
      }

      // =========================
      // Deck
      // =========================
      function deckLabel(deckKey){
        if (deckKey === "A") return "0〜200";
        if (deckKey === "B") return "200〜400";
        if (deckKey === "C") return "400〜600";
        if (deckKey === "D") return "600〜800";
        if (deckKey === "E") return "800〜1000（801〜1000）";
        return "ALL";
      }

      function getDeckWords(deckKey){
        if (deckKey === "A") return data.words.filter(w => w.id >= 1 && w.id <= 200);
        if (deckKey === "B") return data.words.filter(w => w.id >= 201 && w.id <= 400);
        if (deckKey === "C") return data.words.filter(w => w.id >= 401 && w.id <= 600);
        if (deckKey === "D") return data.words.filter(w => w.id >= 601 && w.id <= 800);
        if (deckKey === "E") return data.words.filter(w => w.id >= 801 && w.id <= 1000);
        return data.words.slice();
      }

      function deckSize(deckKey){
        return getDeckWords(deckKey).length;
      }

      // =========================
      // Mode labels
      // =========================
      
      function modeLabel(){
        const qCount = Number(state?.settings?.questionCount || 100);
        const qLabel = [10,20,50,100].includes(qCount) ? qCount : 100;
        switch (state.mode){
          case "SEQ": return "順番";
          case "RND": return "ランダム（1周）";
          case "CHOICE": return `選択本番（4択・${qLabel}問）`;
          case "HAND": return `手書き本番（${qLabel}問）`;
          case "SWITCH": return "Switch Mode";
          case "REVIEW_WRONG": return "間違い復習";
          default: return "—";
        }
      }
      function _activeSubjectId(){
        const p = getPresetById(getActivePresetId());
        return _resolveSubjectId(p?.subjectId, { fallback: "sub:english", allowMissingCustom: true });
      }
      function _entrySubjectId(entry){
        const sid = String(entry?.subjectId || "").trim();
        if (sid) return _resolveSubjectId(sid, { fallback: "sub:english", allowMissingCustom: true });
        return _activeSubjectId();
      }
      function _entryFormats(entry){
        const sid = _entrySubjectId(entry);
        if (_isEnglishSubjectId(sid)){
          return { front: "text", back: "text", subjectId: sid };
        }
        const allowLatex = _isMathSubjectId(sid);
        return {
          front: _normalizeFormatMode(entry?.frontFormat, allowLatex),
          back: _normalizeFormatMode(entry?.backFormat, allowLatex),
          subjectId: sid
        };
      }
      function _renderFieldWithFormat(node, text, format, opts = {}){
        if (!node) return;
        const value = String(text ?? "");
        const fmt = String(format || "text").toLowerCase();
        if (fmt === "latex" && value){
          const holder = document.createElement("span");
          holder.className = "math-rendered";
          /* ★ 2026-08-17: KaTeX（CDN）から **自前配信の MathJax/SVG** へ替えた。
             CDN はオフラインで消え、印刷窓（about:blank）へは そもそも届かない。
             SVG なら 図として固まるので、どちらでも 出る。 */
          holder.textContent = value;
          node.replaceChildren(holder);
          try{
            if (window.VQM && VQM.svg) VQM.svg.描く(holder, value, !!opts.displayMode);
          }catch{}
          return;
        }
        node.textContent = value;
      }

      function isExamReverseEnabled(){
        return !!state.settings.reverseExamQA;
      }
      function isWriteReverseEnabled(){
        return !!state.settings.reverseWriteQA;
      }
      function _resolvePromptAnswerByMode(wordObj, modeOverride){
        const fm = _entryFormats(wordObj);
        const isEnglish = _isEnglishSubjectId(fm.subjectId);
        const frontText = String(wordObj?.word ?? "");
        const backText = String(wordObj?.meaning ?? "");
        const frontFormat = isEnglish ? "text" : fm.front;
        const backFormat = isEnglish ? "text" : fm.back;
        const mode = String(modeOverride || state.mode || "");

        if (mode === "HAND"){
          if (isEnglish){
            if (isWriteReverseEnabled()){
              return { prompt: frontText, answer: backText, promptFormat: "text", answerFormat: "text" };
            }
            return { prompt: backText, answer: frontText, promptFormat: "text", answerFormat: "text" };
          }
          if (isWriteReverseEnabled()){
            return { prompt: backText, answer: frontText, promptFormat: backFormat, answerFormat: frontFormat };
          }
          return { prompt: frontText, answer: backText, promptFormat: frontFormat, answerFormat: backFormat };
        }

        if (mode === "CHOICE"){
          if (isExamReverseEnabled()){
            return { prompt: backText, answer: frontText, promptFormat: backFormat, answerFormat: frontFormat };
          }
          if (isEnglish){
            return { prompt: frontText, answer: backText, promptFormat: "text", answerFormat: "text" };
          }
          return { prompt: frontText, answer: backText, promptFormat: frontFormat, answerFormat: backFormat };
        }

        if (!isEnglish){
          return { prompt: frontText, answer: backText, promptFormat: frontFormat, answerFormat: backFormat };
        }

        const isEnJa = state.settings.direction === "EN_JA";
        return {
          prompt: isEnJa ? frontText : backText,
          answer: isEnJa ? backText : frontText,
          promptFormat: "text",
          answerFormat: "text"
        };
      }
      function _resultDirectionText(mode, isEnglish){
        if (mode === "CHOICE"){
          if (!isEnglish){
            return isExamReverseEnabled() ? "答え→問題（4択）" : "問題→答え（4択）";
          }
          return isExamReverseEnabled() ? "日→英（4択）" : "英→日（4択）";
        }
        if (mode === "HAND"){
          if (!isEnglish){
            return isWriteReverseEnabled() ? "答え→問題" : "問題→答え";
          }
          return isWriteReverseEnabled() ? "英→日" : "日→英";
        }
        return "問題→答え";
      }
      function dirLabel(){
        const sid = _activeSubjectId();
        const isEnglish = _isEnglishSubjectId(sid);
        if (state.mode === "HAND"){
          if (!isEnglish){
            return isWriteReverseEnabled() ? "手書き：答え → 問題" : "手書き：問題 → 答え";
          }
          return isWriteReverseEnabled() ? "手書き：英 → 日（反転）" : "手書き：日 → 英（固定）";
        }
        if (state.mode === "CHOICE"){
          if (!isEnglish){
            return isExamReverseEnabled() ? "選択：答え → 問題（4択）" : "選択：問題 → 答え（4択）";
          }
          return isExamReverseEnabled() ? "選択：日 → 英（4択）" : "選択：英 → 日（4択）";
        }
        if (!isEnglish) return "問題 → 答え";
        return state.settings.direction === "EN_JA" ? "英 → 日" : "日 → 英";
      }
      function _quizCleanPromptText(text){
        return String(text ?? "").replace(/^【[^】]{1,120}】\s*/, "").trim();
      }
      function _quizEntryMeta(entry){
        const raw = String(entry?.word ?? entry?.front ?? "");
        const m = raw.match(/^【([^｜|】]+)[｜|]([^｜|】]+)(?:[｜|]([^】]+))?】/);
        const sid = _entrySubjectId(entry || {});
        const subject = subjectNameById(sid);
        const typeFallback = state.mode === "CHOICE"
          ? "選択本番"
          : state.mode === "HAND"
            ? "手書き"
            : "一問一答";
        let category = "";
        if (Array.isArray(entry?.tags) && entry.tags.length){
          category = String(entry.tags[0] || "").replace(/^#/, "");
        }
        return {
          subject,
          type: (m && m[1] ? m[1] : typeFallback).trim(),
          category: (m && m[2] ? m[2] : (category || subject)).trim(),
          difficulty: (m && m[3] ? m[3] : "").trim()
        };
      }
      function _quizEntryExplanation(entry){
        return String(entry?.explanation ?? entry?.note ?? "").trim();
      }
      function _renderExplanationPanel(entry){
        if (!el.explanationPanel || !el.explanationText) return;
        const explanation = _quizEntryExplanation(entry);
        const isRevealed = state.mode === "CHOICE"
          ? !!state.choice.locked
          : state.mode === "HAND"
            ? !!state.hand.checked
            : !!state.showAnswer;
        el.explanationText.textContent = isRevealed
          ? (explanation || "この問題には解説が登録されていません。")
          : "回答後に解説が表示されます。";
        if (el.explanationStateText){
          el.explanationStateText.textContent = isRevealed
            ? (explanation ? "表示中" : "解説なし")
            : "回答後に表示";
        }
        el.explanationPanel.open = !!isRevealed;
      }
      function _quizResultGrade(pct){
        const n = Number(pct) || 0;
        if (n >= 95) return "S";
        if (n >= 80) return "A";
        if (n >= 65) return "B";
        return "C";
      }
      function _quizLongestStreak(results){
        let best = 0;
        let cur = 0;
        for (const r of (Array.isArray(results) ? results : [])){
          if (r && r.correct){
            cur += 1;
            best = Math.max(best, cur);
          } else {
            cur = 0;
          }
        }
        return best;
      }
      function _quizCategoryBreakdown(results){
        const map = new Map();
        for (const r of (Array.isArray(results) ? results : [])){
          const entry = (data && data.byId instanceof Map) ? data.byId.get(r.id) : null;
          const meta = _quizEntryMeta(entry || {});
          const key = meta.category || meta.subject || "その他";
          const row = map.get(key) || { category: key, total: 0, correct: 0 };
          row.total += 1;
          if (r && r.correct) row.correct += 1;
          map.set(key, row);
        }
        return Array.from(map.values())
          .sort((a, b) => b.total - a.total || a.category.localeCompare(b.category, "ja"))
          .slice(0, 6);
      }
      function _quizHasProgress(){
        if (state.view !== "QUIZ") return false;
        if (state.mode === "CHOICE"){
          const answered = Array.isArray(state.choice?.results)
            ? state.choice.results.filter((x) => x === true || x === false).length
            : 0;
          return state.index > 0 || answered > 0 || !!state.choice?.locked;
        }
        if (state.mode === "HAND"){
          const judged = Array.isArray(state.hand?.results)
            ? state.hand.results.filter((x) => x === true || x === false).length
            : 0;
          const hasInput = String(state.hand?.input || "").trim().length > 0;
          return state.index > 0 || judged > 0 || !!state.hand?.checked || hasInput;
        }
        return state.index > 0 || !!state.showAnswer || !!state.done;
      }
      const _quizExitState = {
        pending: false,
        open: false
      };
      async function _quizExitOpenConfirm(){
        if (state.view !== "QUIZ") return;
        if (_quizExitState.pending) return;
        _quizExitState.pending = true;
        _quizExitState.open = true;
        try{
          const ok = await uiConfirm("進行中の結果は保存されません。プリセット一覧へ戻ります。", {
            title: "クイズを終了しますか？",
            okText: "終了して一覧へ",
            cancelText: "キャンセル"
          });
          if (ok && state.view === "QUIZ"){
            _quizReturnToLibrary();
          }
        } finally {
          _quizExitState.open = false;
          _quizExitState.pending = false;
        }
      }
      function _quizExitCloseConfirm(){
        _quizExitState.open = false;
      }
      function _quizShouldWarnBeforeUnload(){
        return state.view === "QUIZ" && _quizHasProgress();
      }
// =========================
      // View + render helpers
      // =========================
      function setView(next){
        state.view = next;

        if (el.viewStart) el.viewStart.classList.toggle("active", next === "START");
        el.viewTitle.classList.toggle("active", next === "TITLE");
        el.viewQuiz.classList.toggle("active", next === "QUIZ");
        el.viewResult.classList.toggle("active", next === "RESULT");
        if (el.viewSwitch) el.viewSwitch.classList.toggle("active", next === "SWITCH");

        const tabsVisible = (next === "TITLE");
        document.body.classList.toggle("app-tabs-visible", tabsVisible);
        const focusLayout = (next === "QUIZ");
        document.body.classList.toggle("quiz-focus", focusLayout);
        document.body.classList.toggle("result-focus", next === "RESULT");
        document.body.classList.toggle("switch-focus", next === "SWITCH");
        if (focusLayout || next === "RESULT" || next === "SWITCH"){
          try{ document.getElementById("mobBarTutorial")?.remove(); }catch{}
        }
        if (el.quizExitTopBtn) el.quizExitTopBtn.classList.toggle("hidden", !focusLayout);
        if (el.quizExitBtn) el.quizExitBtn.classList.toggle("hidden", !focusLayout);
        if (el.quizHomeBtn) el.quizHomeBtn.classList.toggle("hidden", !focusLayout);
        if (!focusLayout) _quizExitCloseConfirm();
        if (!tabsVisible){
          _appV2SetSidebarOpen(false);
          document.body.dataset.appTab = "home";
          _appSetTopTitleByTab("home");
        } else if (!document.body.dataset.appTab){
          document.body.dataset.appTab = "home";
        }
        _appV2SyncLayoutMetrics();

        el.backBtn.disabled = (next === "START" || next === "TITLE");

        // keep BGM synced to view (quiz only)
        syncBgmToView();
        if (typeof _vqOsSetActiveAppFromExistingContext === "function") _vqOsSetActiveAppFromExistingContext();
        if (typeof _vqOsRenderAll === "function") _vqOsRenderAll();
      }

      function animateCardSwap(fnRender){
        if (!state.settings.animations){
          fnRender();
          return;
        }
        el.card.classList.add("fade-out");
        window.setTimeout(() => {
          fnRender();
          el.card.classList.remove("fade-out");
          // Re-trigger card enter animation
          el.card.style.animation = "none";
          void el.card.offsetHeight; // force reflow
          el.card.style.animation = "";
          // Re-trigger choice button slide-in animations
          if (el.choices){
            const btns = el.choices.querySelectorAll(".choice-btn");
            btns.forEach((btn) => {
              btn.style.animation = "none";
              void btn.offsetHeight;
              btn.style.animation = "";
            });
          }
        }, 180);
      }

      function getCurrent(){
        if (!state.order.length) return null;
        return state.order[state.index] || null;
      }

      // =========================
      // Build order
      // =========================
      const EXAM_SET_KEY = () => `${EXAM_SET_KEY_PREFIX}:${state.deck}`;
      function getSavedPracticeQuestionCount(){
        const n = Number(state?.settings?.questionCount);
        return SETTINGS_QUESTION_COUNTS.has(n) ? n : defaultSettings.questionCount;
      }
      function getPracticeQuestionCount(){
        const startCount = Number(state?.startModeQuestionCount);
        if (START_MODE_QUESTION_COUNT_SET.has(startCount)) return startCount;
        return getSavedPracticeQuestionCount();
      }
      function getChoiceDefaultTimeLimitSec(){
        const n = Number(state?.settings?.choiceTimeLimitSec);
        return SETTINGS_EXAM_TIMES.has(n) ? n : defaultSettings.choiceTimeLimitSec;
      }
      function isAutoNextEnabled(){
        return state?.settings?.autoNext !== false;
      }

      function sampleIdsUnique(ids, n){
        return shuffle(ids).slice(0, Math.min(n, ids.length));
      }

      function loadExamSetIds(deckKey){
        try{
          const raw = window.localStorage.getItem(`${EXAM_SET_KEY_PREFIX}:${deckKey}`);
          if (!raw) return null;
          const obj = JSON.parse(raw);
          if (!obj || !Array.isArray(obj.ids)) return null;
          const ids = obj.ids.map(Number).filter(n => Number.isFinite(n));
          return ids.length ? ids : null;
        } catch {
          return null;
        }
      }

      function saveExamSetIds(deckKey, ids){
        const payload = { ids: ids.slice(), createdAt: Date.now() };
        window.localStorage.setItem(`${EXAM_SET_KEY_PREFIX}:${deckKey}`, JSON.stringify(payload));
      }

      function createExamSetIds(deckKey, forceNew = false){
        const scopedIdsRaw = Array.isArray(state._recommendScopeIds) ? state._recommendScopeIds : null;
        const scopedSet = (scopedIdsRaw && scopedIdsRaw.length)
          ? new Set(scopedIdsRaw.map(Number).filter(n => Number.isFinite(n)))
          : null;
        const deck = (scopedSet && scopedSet.size)
          ? data.words.filter(w => scopedSet.has(Number(w.id)))
          : getDeckWords(deckKey);
        const baseIds = deck.map(w => w.id);
        const want = Math.min(getPracticeQuestionCount(), baseIds.length);
        if (scopedSet && scopedSet.size){
          return sampleIdsUnique(baseIds, want);
        }
        const existing = loadExamSetIds(deckKey);
        if (!forceNew && existing && existing.length){
          const set = existing.filter(id => baseIds.includes(id));
          if (set.length >= want) return set.slice(0, want);
        }
        const ids = sampleIdsUnique(baseIds, want);
        saveExamSetIds(deckKey, ids);
        return ids;
      }

      
      const CHOICE_SET_KEY_PREFIX = "wordPractice400.choiceSet.v1";

      function loadChoiceSetIds(deckKey){
        try{
          const raw = window.localStorage.getItem(`${CHOICE_SET_KEY_PREFIX}:${deckKey}`);
          if (!raw) return null;
          const obj = JSON.parse(raw);
          if (!obj || !Array.isArray(obj.ids)) return null;
          const ids = obj.ids.map(Number).filter(n => Number.isFinite(n));
          return ids.length ? ids : null;
        } catch {
          return null;
        }
      }

      function saveChoiceSetIds(deckKey, ids){
        const payload = { ids: ids.slice(), createdAt: Date.now() };
        window.localStorage.setItem(`${CHOICE_SET_KEY_PREFIX}:${deckKey}`, JSON.stringify(payload));
      }

      function createChoiceSetIds(deckKey, forceNew = false){
        const scopedIdsRaw = Array.isArray(state._recommendScopeIds) ? state._recommendScopeIds : null;
        const scopedSet = (scopedIdsRaw && scopedIdsRaw.length)
          ? new Set(scopedIdsRaw.map(Number).filter(n => Number.isFinite(n)))
          : null;
        const deck = (scopedSet && scopedSet.size)
          ? data.words.filter(w => scopedSet.has(Number(w.id)))
          : getDeckWords(deckKey);
        const baseIds = deck.map(w => w.id);
        const want = Math.min(getPracticeQuestionCount(), baseIds.length);
        if (scopedSet && scopedSet.size){
          return sampleIdsUnique(baseIds, want);
        }
        const existing = loadChoiceSetIds(deckKey);
        if (!forceNew && existing && existing.length){
          const set = existing.filter(id => baseIds.includes(id));
          if (set.length >= want) return set.slice(0, want);
        }
        const ids = sampleIdsUnique(baseIds, want);
        saveChoiceSetIds(deckKey, ids);
        return ids;
      }

      function buildOrder(mode){
        const base = getDeckWords(state.deck);

        if (mode === "SEQ") return base.slice();
        if (mode === "RND") return shuffle(base);

        if (mode === "HAND"){
          const key = getSetKey(state.deck);
          const ids = createExamSetIds(key, false);
          const scopedIdsRaw = Array.isArray(state._recommendScopeIds) ? state._recommendScopeIds : null;
          const scopedSet = (scopedIdsRaw && scopedIdsRaw.length)
            ? new Set(scopedIdsRaw.map(Number).filter(n => Number.isFinite(n)))
            : null;
          const globalMap = (data && data.byId instanceof Map) ? data.byId : new Map();
          const activeMap = buildActiveById();
          const out = [];
          for (const id of ids){
            const w = (scopedSet && scopedSet.size)
              ? (globalMap.get(id) || activeMap.get(id))
              : activeMap.get(id);
            if (w) out.push(w);
          }
          return out;
        }

        if (mode === "CHOICE"){
          const key = getSetKey(state.deck);
          const ids = createChoiceSetIds(key, false);
          const scopedIdsRaw = Array.isArray(state._recommendScopeIds) ? state._recommendScopeIds : null;
          const scopedSet = (scopedIdsRaw && scopedIdsRaw.length)
            ? new Set(scopedIdsRaw.map(Number).filter(n => Number.isFinite(n)))
            : null;
          const globalMap = (data && data.byId instanceof Map) ? data.byId : new Map();
          const activeMap = buildActiveById();
          const out = [];
          for (const id of ids){
            const w = (scopedSet && scopedSet.size)
              ? (globalMap.get(id) || activeMap.get(id))
              : activeMap.get(id);
            if (w) out.push(w);
          }
          return out;
        }

        if (mode === "SWITCH"){
          return buildSwitchOrder(state.deck);
        }

        if (mode === "REVIEW_WRONG"){
          return state.wrongOrder.slice();
        }

        return base.slice();
      }
      // =========================
      // Prompt/Answer
      // =========================
      function displayPromptAnswer(wordObj){
        return _resolvePromptAnswerByMode(wordObj, state.mode);
      }
      function _switchTokenize(answer, rawTokens){
        const explicit = Array.isArray(rawTokens)
          ? rawTokens.map((v) => String(v || "").trim()).filter(Boolean).slice(0, 16)
          : [];
        if (explicit.length >= 2) return explicit;
        const text = String(answer || "").trim().replace(/\s+/g, " ");
        if (!text) return [];
        return text.split(" ").map((item) => item.trim()).filter(Boolean).slice(0, 16);
      }
      function _switchQuestionParts(entry){
        if (!entry) return null;
        const config = entry.switch && typeof entry.switch === "object" ? entry.switch : null;
        const front = String(entry.front ?? entry.word ?? "").trim();
        const back = String(entry.back ?? entry.meaning ?? "").trim();
        let prompt = String(config?.prompt || "").trim();
        let answer = String(config?.answer || "").trim();
        let tokenSource = Array.isArray(config?.tokens) ? config.tokens : null;
        if (!prompt || !answer){
          const frontTokens = _switchTokenize(front, tokenSource);
          const backTokens = _switchTokenize(back, tokenSource);
          if (!prompt) prompt = back || front;
          if (!answer){
            if (Array.isArray(tokenSource) && tokenSource.length >= 2) answer = tokenSource.join(" ");
            else if (frontTokens.length >= 2) answer = front;
            else if (backTokens.length >= 2){
              answer = back;
              if (!config?.prompt) prompt = front || back;
            } else {
              answer = front || back;
            }
          }
        }
        const tokens = _switchTokenize(answer, tokenSource);
        if (tokens.length < 2) return null;
        return {
          prompt,
          answer: tokens.join(" "),
          tokens,
          explanation: String(config?.explanation || entry.explanation || "").trim()
        };
      }
      function _switchEntryPlayable(entry){
        return !!_switchQuestionParts(entry);
      }
      function _switchPlayableCountForDeck(deckKey){
        return getDeckWords(deckKey).filter(_switchEntryPlayable).length;
      }
      function buildSwitchOrder(deckKey){
        const base = getDeckWords(deckKey || state.deck).filter(_switchEntryPlayable);
        const want = Math.min(getPracticeQuestionCount(), base.length);
        return shuffle(base).slice(0, want);
      }
      function resetSwitchSession(){
        state.switchMode.tokens = [];
        state.switchMode.placed = [];
        state.switchMode.bank = [];
        state.switchMode.checked = false;
        state.switchMode.hintCount = 0;
        state.switchMode.correctCount = 0;
        state.switchMode.results = [];
        state.switchMode.reviewIndex = 0;
        state.switchMode.summary = false;
      }
      function prepareSwitchQuestion(){
        const cur = getCurrent();
        const parts = _switchQuestionParts(cur);
        if (!parts){
          state.switchMode.tokens = [];
          state.switchMode.placed = [];
          state.switchMode.checked = false;
          return;
        }
        state.switchMode.tokens = parts.tokens.map((text, index) => ({
          id: `${index}-${text}`,
          text,
          correctIndex: index
        }));
        state.switchMode.placed = Array.from({ length: state.switchMode.tokens.length }, () => null);
        state.switchMode.bank = shuffle(state.switchMode.tokens.slice());
        state.switchMode.checked = false;
        state.switchMode.hintCount = 0;
        state.switchMode.summary = false;
      }
      function _switchPlacedTexts(){
        const tokenMap = new Map((state.switchMode.tokens || []).map((token) => [token.id, token]));
        return (state.switchMode.placed || []).map((id) => tokenMap.get(id)?.text || "");
      }
      function _switchChosenAnswer(){
        return _switchPlacedTexts().filter(Boolean).join(" ");
      }
      function renderSwitchQuestion(){
        if (!el.viewSwitch) return;
        if (state.switchMode.summary){
          renderSwitchSummary();
          return;
        }
        const total = state.order.length || 0;
        const qIndex = clamp(state.index + 1, 0, total);
        const pct = total > 0 ? Math.round((qIndex / total) * 100) : 0;
        const cur = getCurrent();
        const parts = _switchQuestionParts(cur);
        if (!parts){
          if (el.switchPromptText) el.switchPromptText.textContent = "Switch Modeで使える問題がありません。";
          return;
        }
        if (!state.switchMode.tokens.length) prepareSwitchQuestion();
        if (el.switchSubtitle) el.switchSubtitle.textContent = subjectNameById(_activeSubjectId());
        if (el.switchProgressText) el.switchProgressText.textContent = `Question ${qIndex} / ${total}`;
        if (el.switchProgressFill) el.switchProgressFill.style.width = `${pct}%`;
        if (el.switchQuestionPanel) el.switchQuestionPanel.classList.remove("hidden");
        if (el.switchResultPanel) el.switchResultPanel.classList.add("hidden");
        if (el.switchPromptText) el.switchPromptText.textContent = parts.prompt || "次の語句を正しい順に並べ替えてください。";

        const tokenMap = new Map((state.switchMode.tokens || []).map((token) => [token.id, token]));
        if (el.switchSlots){
          el.switchSlots.innerHTML = "";
          (state.switchMode.placed || []).forEach((tokenId, index) => {
            const token = tokenMap.get(tokenId);
            const btn = document.createElement("button");
            btn.type = "button";
            btn.className = `vq-switch-slot${token ? " is-filled" : ""}`;
            btn.dataset.slot = String(index);
            btn.setAttribute("aria-label", `${index + 1}番目の解答欄`);
            btn.innerHTML = token
              ? `<span class="vq-switch-order">${index + 1}</span><span>${escapeHtml(token.text)}</span>`
              : `<span class="vq-switch-order">${index + 1}</span><span>${index + 1}番</span>`;
            el.switchSlots.appendChild(btn);
          });
        }
        if (el.switchBank){
          const placedSet = new Set(state.switchMode.placed || []);
          const bank = (state.switchMode.bank || state.switchMode.tokens || []).filter((token) => !placedSet.has(token.id));
          el.switchBank.innerHTML = bank.length
            ? bank.map((token) => `
                <button class="vq-switch-token" type="button" draggable="true" data-token="${escapeHtml(token.id)}">
                  <span class="ms" aria-hidden="true">drag_indicator</span>
                  <span>${escapeHtml(token.text)}</span>
                </button>
              `).join("")
            : `<div class="vq-switch-bank-empty"><span class="ms" aria-hidden="true">auto_awesome</span>すべて配置済み</div>`;
        }
        renderSwitchFeedback();
      }
      function renderSwitchFeedback(){
        if (!el.switchFeedback) return;
        if (!state.switchMode.checked){
          el.switchFeedback.className = "vq-switch-feedback";
          el.switchFeedback.innerHTML = `<span class="ms" aria-hidden="true">drag_indicator</span>語句をドラッグ＆ドロップ、またはタップして解答欄に配置してください。`;
          return;
        }
        const latest = state.switchMode.results[state.switchMode.results.length - 1];
        const ok = !!latest?.correct;
        el.switchFeedback.className = `vq-switch-feedback ${ok ? "is-correct" : "is-wrong"}`;
        el.switchFeedback.innerHTML = `<span class="ms" aria-hidden="true">${ok ? "check_circle" : "cancel"}</span>${ok ? "正しい順序で並べられています！" : "順序を確認しましょう。"}`;
      }
      function switchPlaceToken(tokenId, slotIndex){
        if (state.view !== "SWITCH" || state.switchMode.checked) return;
        const id = String(tokenId || "");
        if (!id || !(state.switchMode.tokens || []).some((token) => token.id === id)) return;
        const placed = state.switchMode.placed || [];
        const current = placed.indexOf(id);
        if (current >= 0) placed[current] = null;
        let target = Number(slotIndex);
        if (!Number.isInteger(target) || target < 0 || target >= placed.length){
          target = placed.findIndex((v) => !v);
        }
        if (target < 0) return;
        placed[target] = id;
        state.switchMode.placed = placed;
        renderSwitchQuestion();
      }
      function switchRemoveSlot(slotIndex){
        if (state.view !== "SWITCH" || state.switchMode.checked) return;
        const index = Number(slotIndex);
        if (!Number.isInteger(index)) return;
        if (state.switchMode.placed[index]){
          state.switchMode.placed[index] = null;
          renderSwitchQuestion();
        }
      }
      function switchReset(){
        if (state.view !== "SWITCH") return;
        prepareSwitchQuestion();
        renderSwitchQuestion();
      }
      function switchHint(){
        if (state.view !== "SWITCH" || state.switchMode.checked) return;
        const tokens = state.switchMode.tokens || [];
        const placed = state.switchMode.placed || [];
        const index = placed.findIndex((tokenId, i) => tokenId !== tokens[i]?.id);
        if (index < 0) return;
        switchPlaceToken(tokens[index].id, index);
        state.switchMode.hintCount += 1;
      }
      function switchCheck(){
        if (state.view !== "SWITCH" || state.switchMode.checked) return;
        const cur = getCurrent();
        const parts = _switchQuestionParts(cur);
        const placed = state.switchMode.placed || [];
        if (!parts || placed.some((v) => !v)){
          uiToast("すべての語句を配置してください。");
          return;
        }
        const tokens = state.switchMode.tokens || [];
        const correct = placed.every((tokenId, index) => tokenId === tokens[index]?.id);
        const result = {
          id: cur?.id || state.index + 1,
          prompt: parts.prompt,
          answer: parts.answer,
          chosenAnswer: _switchChosenAnswer(),
          correct,
          explanation: parts.explanation || "正しい語順になるよう、文の主語・動詞・目的語・修飾語の流れを確認しましょう。"
        };
        state.switchMode.checked = true;
        state.switchMode.results.push(result);
        if (correct) state.switchMode.correctCount += 1;
        renderSwitchResult(result);
      }
      function renderSwitchResult(result){
        if (!el.switchResultPanel) return;
        const r = result || state.switchMode.results[state.switchMode.results.length - 1] || null;
        if (!r) return;
        const total = state.order.length || 0;
        const qIndex = clamp(state.index + 1, 0, total);
        const pct = total > 0 ? Math.round((qIndex / total) * 100) : 0;
        if (el.switchProgressText) el.switchProgressText.textContent = `Question ${qIndex} completed`;
        if (el.switchProgressFill) el.switchProgressFill.style.width = `${pct}%`;
        if (el.switchQuestionPanel) el.switchQuestionPanel.classList.add("hidden");
        el.switchResultPanel.classList.remove("hidden");
        el.switchResultPanel.className = `vq-switch-result ${r.correct ? "is-correct" : "is-wrong"}`;
        const icon = r.correct ? "check" : "close";
        if (el.switchScoreIcon) el.switchScoreIcon.innerHTML = `<span class="ms" aria-hidden="true">${icon}</span>`;
        if (el.switchScoreMain) el.switchScoreMain.textContent = `${r.correct ? 1 : 0} / 1 正解`;
        if (el.switchScoreRate) el.switchScoreRate.textContent = r.correct ? "100%" : "0%";
        if (el.switchScoreMessage) el.switchScoreMessage.textContent = r.correct ? "よくできました！この調子で進めましょう。" : "惜しいです。正しい順序を確認して次へ進みましょう。";
        if (el.switchReviewList){
          el.switchReviewList.innerHTML = `
            <div class="vq-switch-review">
              <span class="vq-switch-review-label">問題文</span>
              <p>${escapeHtml(r.prompt)}</p>
            </div>
            <div class="vq-switch-review ${r.correct ? "is-good" : "is-bad"}">
              <span class="vq-switch-review-label">あなたの答え</span>
              <p>${escapeHtml(r.chosenAnswer)}</p>
              <strong>${r.correct ? "正解" : "不正解"}</strong>
            </div>
            <div class="vq-switch-review is-answer">
              <span class="vq-switch-review-label">正解</span>
              <p>${escapeHtml(r.answer)}</p>
            </div>
            <div class="vq-switch-review">
              <span class="vq-switch-review-label">解説</span>
              <p>${escapeHtml(r.explanation || "解説はありません。")}</p>
            </div>
          `;
        }
        if (el.switchNextBtn) el.switchNextBtn.innerHTML = `${state.index >= total - 1 ? "結果を見る" : "次の問題へ"} <span class="ms" aria-hidden="true">arrow_forward</span>`;
      }
      function renderSwitchSummary(){
        const total = state.switchMode.results.length || state.order.length || 0;
        const correct = state.switchMode.correctCount || 0;
        const rate = total ? Math.round((correct / total) * 100) : 0;
        if (el.switchQuestionPanel) el.switchQuestionPanel.classList.add("hidden");
        if (el.switchResultPanel) el.switchResultPanel.classList.remove("hidden");
        if (el.switchProgressText) el.switchProgressText.textContent = `${total} / ${total}`;
        if (el.switchProgressFill) el.switchProgressFill.style.width = "100%";
        if (el.switchScoreIcon) el.switchScoreIcon.innerHTML = `<span class="ms" aria-hidden="true">${rate >= 80 ? "check" : "school"}</span>`;
        if (el.switchScoreMain) el.switchScoreMain.textContent = `${correct} / ${total} 正解`;
        if (el.switchScoreRate) el.switchScoreRate.textContent = `${rate}%`;
        if (el.switchScoreMessage) el.switchScoreMessage.textContent = rate >= 80 ? "よくできました！復習カードで仕上げましょう。" : "復習カードで語順の流れをもう一度確認しましょう。";
        if (el.switchReviewList){
          el.switchReviewList.innerHTML = (state.switchMode.results || []).map((r, index) => `
            <details class="vq-switch-summary-item${r.correct ? "" : " is-wrong"}" ${r.correct ? "" : "open"}>
              <summary>
                <span>No.${index + 1}</span>
                <strong>${escapeHtml(r.prompt)}</strong>
                <em>${r.correct ? "正解" : "不正解"}</em>
              </summary>
              <div class="vq-switch-summary-body">
                <p><b>あなたの答え</b>${escapeHtml(r.chosenAnswer)}</p>
                <p><b>正解</b>${escapeHtml(r.answer)}</p>
                <p><b>解説</b>${escapeHtml(r.explanation || "解説はありません。")}</p>
              </div>
            </details>
          `).join("");
        }
        if (el.switchNextBtn) el.switchNextBtn.innerHTML = `ホームへ戻る <span class="ms" aria-hidden="true">home</span>`;
      }
      function switchNext(){
        if (state.view !== "SWITCH") return;
        if (state.switchMode.summary){
          goTitle();
          return;
        }
        if (!state.switchMode.checked){
          switchCheck();
          return;
        }
        if (state.index >= state.order.length - 1){
          state.switchMode.summary = true;
          renderSwitchSummary();
          return;
        }
        state.index += 1;
        prepareSwitchQuestion();
        renderSwitchQuestion();
      }
      function _renderPromptDiagram(entry){
        if (!el.promptDiagramWrap || !el.promptDiagramImg){
          return;
        }
        const sid = _entrySubjectId(entry);
        const diagram = _normalizeCardDiagram(entry?.diagram);
        if (!_isMathSubjectId(sid) || !diagram || !diagram.url){
          el.promptDiagramWrap.classList.add("hidden");
          el.promptDiagramImg.removeAttribute("src");
          return;
        }
        el.promptDiagramImg.src = diagram.url;
        el.promptDiagramWrap.classList.remove("hidden");
      }
      function _quizQuestionImageSrc(entry){
        return String(entry?.selectedAiImage || entry?.imageUrl || "").trim();
      }
      function _quizQuestionAssetUrl(entry){
        return String(entry?.assetUrl || "").trim();
      }
      function _quizQuestionAssetName(entry){
        return String(entry?.assetName || "").trim();
      }
      function _quizIsImageSource(url){
        return /^data:image\//i.test(String(url || "").trim());
      }
      function _quizIsPdfSource(url){
        return /^data:application\/pdf/i.test(String(url || "").trim());
      }
      function _quizQuestionMediaHtml(entry){
        const imageSrc = _quizQuestionImageSrc(entry);
        const assetUrl = _quizQuestionAssetUrl(entry);
        const assetName = _quizQuestionAssetName(entry);
        const parts = [];
        if (imageSrc){
          parts.push(`
            <figure class="quiz-media-card is-image">
              <div class="quiz-media-card-head">
                <span>設問画像</span>
              </div>
              <img src="${escapeHtml(imageSrc)}" alt="${escapeHtml(String(entry?.front || entry?.word || "設問画像"))}" loading="lazy" />
              ${assetName ? `<figcaption>${escapeHtml(assetName)}</figcaption>` : ""}
            </figure>
          `);
        }
        if (assetName || assetUrl){
          if (_quizIsImageSource(assetUrl) && assetUrl !== imageSrc){
            parts.push(`
              <figure class="quiz-media-card is-asset-image">
                <div class="quiz-media-card-head">
                  <span>資料</span>
                </div>
                <img src="${escapeHtml(assetUrl)}" alt="${escapeHtml(assetName || "資料画像")}" loading="lazy" />
                <figcaption>${escapeHtml(assetName || "資料画像")}</figcaption>
              </figure>
            `);
          } else if (_quizIsPdfSource(assetUrl)){
            parts.push(`
              <figure class="quiz-media-card is-pdf">
                <div class="quiz-media-card-head">
                  <span>資料</span>
                </div>
                <object data="${escapeHtml(assetUrl)}" type="application/pdf" aria-label="${escapeHtml(assetName || "資料PDF")}">
                  <div class="quiz-media-file">
                    <div class="quiz-media-file-icon"><span class="ms" aria-hidden="true">picture_as_pdf</span></div>
                    <div class="quiz-media-file-copy">
                      <strong>${escapeHtml(assetName || "資料PDF")}</strong>
                      <span>この環境では埋め込み表示に対応していないため、資料を開いて確認してください。</span>
                    </div>
                    <a class="quiz-media-link" href="${escapeHtml(assetUrl)}" target="_blank" rel="noopener">開く</a>
                  </div>
                </object>
                <figcaption>${escapeHtml(assetName || "PDF資料")}</figcaption>
              </figure>
            `);
          } else if (assetName){
            parts.push(`
              <div class="quiz-media-card is-file">
                <div class="quiz-media-file">
                  <div class="quiz-media-file-icon"><span class="ms" aria-hidden="true">attach_file</span></div>
                  <div class="quiz-media-file-copy">
                    <strong>${escapeHtml(assetName)}</strong>
                    <span>この設問には補助資料が添付されています。</span>
                  </div>
                  ${assetUrl ? `<a class="quiz-media-link" href="${escapeHtml(assetUrl)}" target="_blank" rel="noopener">開く</a>` : ""}
                </div>
              </div>
            `);
          }
        }
        return parts.join("");
      }
      function _renderQuestionMedia(entry){
        if (!el.promptMediaWrap){
          return;
        }
        const html = _quizQuestionMediaHtml(entry);
        if (!html){
          el.promptMediaWrap.innerHTML = "";
          el.promptMediaWrap.classList.add("hidden");
          return;
        }
        el.promptMediaWrap.innerHTML = html;
        el.promptMediaWrap.classList.remove("hidden");
      }

      
      // =========================
      // Choice exam (4択) helpers
      // =========================
      function resetChoiceSession(timeLimitSec){
        state.choice.timeLimitSec = Number(timeLimitSec) || 0;
        state.choice.remainingMs = 0;
        state.choice.timerId = null;
        state.choice.endAt = 0;
        state.choice.locked = false;
        state.choice.options = [];
        state.choice.optionMedia = [];
        state.choice.correctIndex = -1;
        state.choice.lastCorrectIndex = -1;
        state.choice.correctCount = 0;
        state.choice.results = [];
      }

      function clearChoiceTimer(){
        if (state.choice.timerId){
          clearInterval(state.choice.timerId);
          state.choice.timerId = null;
        }
        state.choice.endAt = 0;
        state.choice.remainingMs = 0;
      }

      let _quizElapsedTimerId = null;
      function _formatQuizDuration(ms, opts = {}){
        const totalMs = Math.max(0, Number(ms) || 0);
        if (opts.compactSeconds){
          const sec = totalMs / 1000;
          return `${sec.toFixed(sec >= 10 ? 1 : 1)}秒`;
        }
        const totalSec = Math.floor(totalMs / 1000);
        const h = Math.floor(totalSec / 3600);
        const m = Math.floor((totalSec % 3600) / 60);
        const s = totalSec % 60;
        const pad = (n) => String(n).padStart(2, "0");
        return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
      }
      function _quizElapsedMs(){
        const start = Number(state.quizStartedAt || 0);
        if (!start) return 0;
        const end = Number(state.quizEndedAt || 0) || Date.now();
        return Math.max(0, end - start);
      }
      function _setTimerChipText(text, countdown = false){
        if (!el.timerPill) return;
        el.timerPill.classList.remove("hidden");
        el.timerPill.classList.toggle("is-countdown", !!countdown);
        const value = String(text || "00:00");
        if (el.timerText) el.timerText.textContent = value;
        else el.timerPill.textContent = value;
      }
      function _updateQuizElapsedTimer(){
        if (state.view !== "QUIZ"){
          if (el.timerPill) el.timerPill.classList.add("hidden");
          return;
        }
        _setTimerChipText(_formatQuizDuration(_quizElapsedMs()), false);
      }
      function _startQuizElapsedTicker(){
        if (_quizElapsedTimerId) clearInterval(_quizElapsedTimerId);
        _updateQuizElapsedTimer();
        _quizElapsedTimerId = window.setInterval(_updateQuizElapsedTimer, 1000);
      }
      function _stopQuizElapsedTicker(){
        if (_quizElapsedTimerId){
          clearInterval(_quizElapsedTimerId);
          _quizElapsedTimerId = null;
        }
      }
      function _startQuizSessionTimer(){
        state.quizStartedAt = Date.now();
        state.quizEndedAt = 0;
        _startQuizElapsedTicker();
      }
      function _finishQuizSessionTimer(){
        if (state.quizStartedAt && !state.quizEndedAt) state.quizEndedAt = Date.now();
        _stopQuizElapsedTicker();
      }

      function setTimerPill(sec){
        if (!el.timerPill) return;
        if (!sec || sec <= 0){
          _updateQuizElapsedTimer();
          return;
        }
        _setTimerChipText(`残り ${sec}秒`, true);
      }

      function startChoiceTimer(){
        clearChoiceTimer();
        const limit = state.choice.timeLimitSec || 0;
        if (!limit || limit <= 0){
          setTimerPill(0);
          return;
        }
        const now = Date.now();
        state.choice.endAt = now + (limit * 1000);
        state.choice.remainingMs = limit * 1000;
        setTimerPill(limit);

        state.choice.timerId = setInterval(() => {
          const ms = Math.max(0, state.choice.endAt - Date.now());
          state.choice.remainingMs = ms;
          const sec = Math.ceil(ms / 1000);
          setTimerPill(sec);

          if (ms <= 0){
            clearChoiceTimer();
            if (!state.choice.locked && state.view === "QUIZ" && state.mode === "CHOICE"){
              handleChoiceTimeout();
            }
          }
        }, 80);
      }

      function _choiceAnswerValue(wordObj, useWordSide){
        if (!wordObj) return "";
        const raw = useWordSide ? wordObj.word : wordObj.meaning;
        return String(raw ?? "").trim();
      }
      function _choiceSimilarity(a, b){
        // Score how similar two answer strings are (higher = more similar)
        let score = 0;
        const la = a.length, lb = b.length;
        // Length similarity (0-3): prefer similar length
        const lenRatio = Math.min(la, lb) / Math.max(la, lb, 1);
        score += lenRatio * 3;
        // Character overlap (0-3): shared characters
        const setA = new Set(a.toLowerCase());
        const setB = new Set(b.toLowerCase());
        let shared = 0;
        for (const c of setA){ if (setB.has(c)) shared++; }
        score += (shared / Math.max(setA.size, setB.size, 1)) * 3;
        // Same script type bonus (0-2): both Japanese or both English
        const jpA = /[\u3000-\u9fff]/.test(a);
        const jpB = /[\u3000-\u9fff]/.test(b);
        if (jpA === jpB) score += 2;
        // Same word count / structure (0-1)
        const wcA = a.split(/[\s,、]+/).length;
        const wcB = b.split(/[\s,、]+/).length;
        if (wcA === wcB) score += 1;
        return score;
      }
      function pickDummyChoiceAnswers(curId, correctAnswer, count, useWordSide){
        const deckPool = getDeckWords(state.deck)
          .filter(w => w.id !== curId)
          .map(w => _choiceAnswerValue(w, useWordSide))
          .filter(v => !!v && v !== correctAnswer);

        const sid = _activeSubjectId();
        const globalPool = _isEnglishSubjectId(sid)
          ? data.words
              .filter(w => w.id !== curId)
              .map(w => _choiceAnswerValue(w, useWordSide))
              .filter(v => !!v && v !== correctAnswer)
          : getActiveWords()
              .filter(w => w.id !== curId)
              .map(w => _choiceAnswerValue(w, useWordSide))
              .filter(v => !!v && v !== correctAnswer);

        // Deduplicate and score by similarity to correct answer
        const seen = new Set([correctAnswer]);
        const candidates = [];
        // Prefer deck pool first (same preset), then global
        for (const src of [deckPool, globalPool]){
          for (const m of src){
            if (seen.has(m)) continue;
            seen.add(m);
            candidates.push({ text: m, score: _choiceSimilarity(correctAnswer, m) });
          }
        }
        // Sort by similarity descending, then pick top candidates with some randomness
        candidates.sort((a, b) => b.score - a.score);
        // Take top ~3x pool of most similar, then shuffle to avoid always-same order
        const topPool = candidates.slice(0, Math.max(count * 3, 12));
        const shuffled = shuffle(topPool);
        return shuffled.slice(0, count).map(c => c.text);
      }


function shuffleWithNoConsecutiveSameCorrect(options, correctMeaning){
        let tries = 0;
        let out = options.slice();
        let correctIndex = -1;
        while (tries < 10){
          out = shuffle(out);
          correctIndex = out.indexOf(correctMeaning);
          if (correctIndex !== state.choice.lastCorrectIndex) break;
          tries++;
        }
        if (correctIndex === state.choice.lastCorrectIndex && out.length > 1){
          // rotate once to avoid consecutive same
          out = out.slice(1).concat(out.slice(0,1));
          correctIndex = out.indexOf(correctMeaning);
        }
        return { out, correctIndex };
      }

      function _choiceOptionText(option){
        if (option && typeof option === "object") return String(option.text || "").trim();
        return String(option ?? "").trim();
      }
      function _choiceOptionMediaByIndex(index){
        return /^data:image\//i.test(String(state.choice?.optionMedia?.[index] || "").trim())
          ? String(state.choice.optionMedia[index] || "").trim()
          : "";
      }

      function buildChoiceOptionsForCurrent(){
        const cur = getCurrent();
        if (!cur) return;
        const qa = displayPromptAnswer(cur);
        const useWordSide = isExamReverseEnabled();
        const correctAnswer = String(qa.answer ?? "");
        if (!correctAnswer){
          state.choice.options = [];
          state.choice.optionMedia = [];
          state.choice.correctIndex = -1;
          state.choice.locked = false;
          return;
        }

        // Base choices:
        // - If normal exam direction and cur has custom MCQ config, use it (up to 15).
        // - Otherwise, generate from active answer side (3 dummies).
        let base = null;
        let usedCustomChoices = false;
        const baseMediaMap = new Map();

        if (!useWordSide && cur.mcq && Array.isArray(cur.mcq.choices) && cur.mcq.choices.length){
          const raw = cur.mcq.choices.slice(0,15).map(v => String(v ?? "").trim()).filter(Boolean);
          const rawChoiceMedia = Array.isArray(cur.mcq.choiceMedia) ? cur.mcq.choiceMedia.slice(0, 15) : [];
          const seen = new Set();
          const cleaned = [];
          raw.forEach((s, idx) => {
            if (seen.has(s)) return;
            seen.add(s);
            cleaned.push(s);
            const media = /^data:image\//i.test(String(rawChoiceMedia[idx] || "").trim()) ? String(rawChoiceMedia[idx] || "").trim() : "";
            if (media) baseMediaMap.set(s, media);
          });
          if (cleaned.length){
            // Ensure exact correct answer is included (strict)
            if (!cleaned.includes(correctAnswer)){
              const idx = Number(cur.mcq.correctIndex);
              if (Number.isInteger(idx) && idx >= 0 && idx < cleaned.length){
                cleaned[idx] = correctAnswer;
              } else if (cleaned.length < 15){
                cleaned.unshift(correctAnswer);
              } else {
                cleaned[0] = correctAnswer;
              }
            }
            base = cleaned;
            usedCustomChoices = true;
          }
        }

        if (!base){
          base = [correctAnswer, ...pickDummyChoiceAnswers(cur.id, correctAnswer, 3, useWordSide)];
        }

        // Fill to 4 (avoid duplicates)
        const deckPool = getDeckWords(state.deck)
          .filter(w => w.id !== cur.id)
          .map(w => _choiceAnswerValue(w, useWordSide))
          .filter(v => !!v && v !== correctAnswer);

        const sid = _activeSubjectId();
        const globalPool = _isEnglishSubjectId(sid)
          ? data.words
              .filter(w => w.id !== cur.id)
              .map(w => _choiceAnswerValue(w, useWordSide))
              .filter(v => !!v && v !== correctAnswer)
          : getActiveWords()
              .filter(w => w.id !== cur.id)
              .map(w => _choiceAnswerValue(w, useWordSide))
              .filter(v => !!v && v !== correctAnswer);

        const pool = deckPool.concat(globalPool);

        const uniq = [];
        const seen = new Set();
        for (const s of base){
          const k = String(s ?? "").trim();
          if (!k) continue;
          if (seen.has(k)) continue;
          seen.add(k);
          uniq.push(k);
        }
        base = uniq;

        // Safety: ensure correct answer present
        if (!base.includes(correctAnswer)){
          if (base.length) base[0] = correctAnswer;
          else base = [correctAnswer];
        }

        const maxChoices = usedCustomChoices ? 15 : 4;
        if (base.length > maxChoices){
          // keep correct answer when trimming
          const hasCorrect = base.slice(0, maxChoices).includes(correctAnswer);
          base = base.slice(0, maxChoices);
          if (!hasCorrect){
            base[base.length - 1] = correctAnswer;
          }
        }

        if (!usedCustomChoices && base.length < 4){
          // Fallback to default generation
          const dummies = pickDummyChoiceAnswers(cur.id, correctAnswer, 3, useWordSide);
          base = [correctAnswer, ...dummies];
        }

        const { out, correctIndex } = shuffleWithNoConsecutiveSameCorrect(base, correctAnswer);
        state.choice.options = out;
        state.choice.optionMedia = out.map((item) => baseMediaMap.get(String(item || "").trim()) || "");
        state.choice.correctIndex = correctIndex;
        state.choice.locked = false;
      }

      function renderChoiceOptions(){
        if (!el.choices) return;
        const options = state.choice.options || [];
        const labels = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
        const cur = getCurrent();
        const qa = cur ? displayPromptAnswer(cur) : null;
        const optionFormat = qa?.answerFormat || "text";

        el.choices.innerHTML = "";
        for (let i = 0; i < options.length; i++){
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = "choice-btn";
          btn.dataset.idx = String(i);
          const key = document.createElement("span");
          key.className = "k";
          key.textContent = labels[i] || String(i + 1);
          btn.appendChild(key);
          const copy = document.createElement("span");
          copy.className = "choice-copy";
          const txt = document.createElement("span");
          txt.className = "choice-text";
          _renderFieldWithFormat(txt, _choiceOptionText(options[i]), optionFormat, { displayMode: false });
          copy.appendChild(txt);
          const mediaUrl = _choiceOptionMediaByIndex(i);
          if (mediaUrl){
            const media = document.createElement("span");
            media.className = "choice-media";
            media.innerHTML = `<img src="${escapeHtml(mediaUrl)}" alt="選択肢資料 ${i + 1}" loading="lazy" />`;
            copy.appendChild(media);
          }
          btn.appendChild(copy);
          const stateIcon = document.createElement("span");
          stateIcon.className = "choice-state";
          stateIcon.setAttribute("aria-hidden", "true");
          btn.appendChild(stateIcon);
          el.choices.appendChild(btn);
        }
      }

      function lockChoiceButtons(){
        const btns = el.choices ? el.choices.querySelectorAll("button.choice-btn") : [];
        btns.forEach(b => b.disabled = true);
      }

      function markChoiceButtons(selectedIndex, correctIndex){
        const btns = el.choices ? el.choices.querySelectorAll("button.choice-btn") : [];
        btns.forEach((b) => {
          const i = Number(b.dataset.idx);
          b.classList.remove("correct","wrong","is-selected");
          if (selectedIndex !== null && i === selectedIndex) b.classList.add("is-selected");
          if (i === correctIndex) b.classList.add("correct");
          if (selectedIndex !== null && i === selectedIndex && selectedIndex !== correctIndex) b.classList.add("wrong");
        });
      }

      function pushChoiceResult(cur, selectedIndex, timedOut){
        const qa = displayPromptAnswer(cur);
        const promptText = _quizCleanPromptText(String(qa.prompt ?? ""));
        const correctAnswer = String(qa.answer ?? "");
        const chosen = (selectedIndex === null) ? "" : _choiceOptionText(state.choice.options[selectedIndex]);
        const correct = (!timedOut) ? (selectedIndex === state.choice.correctIndex) : false;
        const chosenText = timedOut ? "(TIMEOUT)" : (chosen || "(NO SELECT)");

        state.choice.results.push({
          id: cur.id,
          word: promptText,
          promptText,
          correctMeaning: correctAnswer,
          correctAnswer,
          chosenMeaning: chosenText,
          chosenAnswer: chosenText,
          correct: correct,
          timedOut: !!timedOut
        });

        if (correct) state.choice.correctCount += 1;
        return correct;
      }

      function scheduleChoiceNext(){
        const delay = 720; // 0.6〜0.8 sec
        window.setTimeout(() => {
          if (state.mode !== "CHOICE" || state.view !== "QUIZ") return;

          if (state.index >= state.order.length - 1){
            goResult("CHOICE");
            return;
          }

          state.index += 1;
          state.showAnswer = false;
          state.done = false;

          // Prepare next question (prompt/options)
          buildChoiceOptionsForCurrent();

          // Render next question with a small fade
          animateCardSwap(() => {
            renderAll();
            startChoiceTimer();
          });
        }, delay);
      }

      function renderChoiceHeaderExtras(){
        // show/hide timer pill based on timeLimit and question state
        if (state.mode !== "CHOICE"){
          setTimerPill(0);
          return;
        }
        const limit = state.choice.timeLimitSec || 0;
        if (!limit || limit <= 0){
          setTimerPill(0);
        } else {
          const ms = state.choice.remainingMs || (limit * 1000);
          const sec = Math.ceil(ms / 1000);
          setTimerPill(sec);
        }
      }

      function handleChoiceSelect(selectedIndex){
        const cur = getCurrent();
        if (!cur) return;
        if (state.mode !== "CHOICE") return;
        if (state.choice.locked) return;

        state.choice.locked = true;
        clearChoiceTimer();
        lockChoiceButtons();

        const isCorrect = pushChoiceResult(cur, selectedIndex, false);

        markChoiceButtons(selectedIndex, state.choice.correctIndex);
        showMark(isCorrect);
        playSfx(isCorrect ? "ok" : "ng");

        // show correct answer briefly
        el.answerWrap.classList.remove("hidden");
        el.answerWrap.classList.remove("is-correct","is-wrong");
        el.answerWrap.classList.add(isCorrect ? "is-correct" : "is-wrong");
        const qa = displayPromptAnswer(cur);
        _renderFieldWithFormat(el.answerText, qa.answer, qa.answerFormat, { displayMode: true });
        _renderExplanationPanel(cur);

        if (isAutoNextEnabled()){
          scheduleChoiceNext();
        }else{
          el.nextBtn.classList.remove("hidden");
          el.nextBtn.textContent = (state.index >= state.order.length - 1) ? "結果へ" : "次へ";
        }
        renderHeaderOnly();
      }

      function handleChoiceTimeout(){
        const cur = getCurrent();
        if (!cur) return;
        if (state.mode !== "CHOICE") return;
        if (state.choice.locked) return;

        state.choice.locked = true;
        clearChoiceTimer();
        lockChoiceButtons();

        pushChoiceResult(cur, null, true);
        markChoiceButtons(null, state.choice.correctIndex);
        showMark(false);
        playSfx("ng");

        // show correct answer briefly
        el.answerWrap.classList.remove("hidden");
        el.answerWrap.classList.remove("is-correct","is-wrong");
        el.answerWrap.classList.add("is-wrong");
        const qa = displayPromptAnswer(cur);
        _renderFieldWithFormat(el.answerText, qa.answer, qa.answerFormat, { displayMode: true });
        _renderExplanationPanel(cur);

        if (isAutoNextEnabled()){
          scheduleChoiceNext();
        }else{
          el.nextBtn.classList.remove("hidden");
          el.nextBtn.textContent = (state.index >= state.order.length - 1) ? "結果へ" : "次へ";
        }
        renderHeaderOnly();
      }

      function openTimeSelect(){
        if (!el.timeOverlay) return;
        el.timeOverlay.classList.remove("hidden");
      }

      function closeTimeSelect(){
        if (!el.timeOverlay) return;
        el.timeOverlay.classList.add("hidden");
      }
// =========================
      // Handwriting helpers
      // =========================
      let canvasCtx = null;
      let drawing = false;

      function ensureCanvasReady(){
        if (!el.handCanvas) return;
        if (!canvasCtx){
          canvasCtx = el.handCanvas.getContext("2d", { alpha: false });
        }
        resizeCanvasToCSS();
        primeCanvasStyle();
      }

      function primeCanvasStyle(){
        if (!canvasCtx) return;
        canvasCtx.lineCap = "round";
        canvasCtx.lineJoin = "round";
        canvasCtx.strokeStyle = "#111214";
        canvasCtx.lineWidth = 3.2;
      }

      function resizeCanvasToCSS(){
        if (!el.handCanvas || !canvasCtx) return;
        const rect = el.handCanvas.getBoundingClientRect();
        const dpr = window.devicePixelRatio || 1;

        const w = Math.max(1, Math.round(rect.width * dpr));
        const h = Math.max(1, Math.round(rect.height * dpr));

        if (el.handCanvas.width !== w || el.handCanvas.height !== h){
          el.handCanvas.width = w;
          el.handCanvas.height = h;
          canvasCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
          clearCanvas();
          primeCanvasStyle();
        }
      }

      function clearCanvas(){
        if (!canvasCtx || !el.handCanvas) return;
        if (_canvasOCRTimer) { clearTimeout(_canvasOCRTimer); _canvasOCRTimer = null; }
        canvasCtx.save();
        canvasCtx.setTransform(1,0,0,1,0,0);
        canvasCtx.fillStyle = "#ffffff";
        canvasCtx.fillRect(0,0, el.handCanvas.width, el.handCanvas.height);
        canvasCtx.restore();
        primeCanvasStyle();
      }

      function canvasPointFromEvent(e){
        const r = el.handCanvas.getBoundingClientRect();
        return { x: e.clientX - r.left, y: e.clientY - r.top };
      }

      function bindCanvasEvents(){
        if (!el.handCanvas) return;

        el.handCanvas.addEventListener("pointerdown", (e) => {
          if (state.mode !== "HAND") return;
          ensureCanvasReady();
          drawing = true;
          el.handCanvas.setPointerCapture(e.pointerId);
          const p = canvasPointFromEvent(e);
          canvasCtx.beginPath();
          canvasCtx.moveTo(p.x, p.y);
        });

        el.handCanvas.addEventListener("pointermove", (e) => {
          if (state.mode !== "HAND") return;
          if (!drawing) return;
          const p = canvasPointFromEvent(e);
          canvasCtx.lineTo(p.x, p.y);
          canvasCtx.stroke();
        });

        const end = () => {
          if (drawing) {
            drawing = false;
            _scheduleCanvasOCR();
          }
        };
        el.handCanvas.addEventListener("pointerup", end);
        el.handCanvas.addEventListener("pointercancel", end);
        el.handCanvas.addEventListener("pointerleave", end);

        window.addEventListener("resize", () => {
          if (state.mode === "HAND"){
            ensureCanvasReady();
          }
        });
      }

      function normalizeCompare(s){
        return String(s || "")
          .toLowerCase()
          .trim()
          .replace(/\s+/g, " ");
      }

      function normalizeNoSpace(s){
        return normalizeCompare(s).replace(/\s+/g, "");
      }

      function computeCorrect(expected, given){
        const a = normalizeCompare(expected);
        const b = normalizeCompare(given);
        if (!a || !b) return false;
        if (a === b) return true;
        // allow ignoring spaces (helps recognition for phrases)
        return normalizeNoSpace(a) === normalizeNoSpace(b);
      }

      function resetHandPerQuestion(){
        state.hand.checked = false;
        state.hand.correct = null;
        state.hand.input = "";
        state.hand.busy = false;

        el.spellInput.value = "";
        el.spellInput.disabled = false;

        // judge badge
        el.judgeBadge.classList.add("hidden");
        el.judgeBadge.classList.remove("ok","ng");
        el.judgeBadge.textContent = "—";

        // answer area
        el.yourText.textContent = "";
        el.answerWrap.classList.remove("is-correct","is-wrong");

        // marks
        hideMark();

        // buttons
        el.primaryBtn.disabled = false;
        el.primaryBtn.textContent = "判定";

        ensureCanvasReady();
        clearCanvas();
      }

      function escapeHtml(s){
        return String(s ?? "")
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#039;");
      }

      // =========================
      // OCR (TextDetector) with preprocessing
      // =========================
      function hasTextDetector(){
        return ("TextDetector" in window);
      }

      function cleanOCRText(raw){
        // keep letters and spaces; normalize spaces
        return String(raw || "")
          .replace(/[^A-Za-z\s]/g, " ")
          .replace(/\s+/g, " ")
          .trim();
      }

      function levenshtein(a, b){
        a = normalizeNoSpace(a);
        b = normalizeNoSpace(b);
        const n = a.length;
        const m = b.length;
        if (n === 0) return m;
        if (m === 0) return n;
        const dp = new Array(m + 1);
        for (let j = 0; j <= m; j++) dp[j] = j;

        for (let i = 1; i <= n; i++){
          let prev = dp[0];
          dp[0] = i;
          for (let j = 1; j <= m; j++){
            const tmp = dp[j];
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            dp[j] = Math.min(
              dp[j] + 1,
              dp[j - 1] + 1,
              prev + cost
            );
            prev = tmp;
          }
        }
        return dp[m];
      }

      function cropAndScaleForOCR(srcCanvas){
        const w = srcCanvas.width;
        const h = srcCanvas.height;

        const tmp = document.createElement("canvas");
        tmp.width = w;
        tmp.height = h;
        const tctx = tmp.getContext("2d", { alpha: false });
        tctx.drawImage(srcCanvas, 0, 0);

        const img = tctx.getImageData(0, 0, w, h);
        const d = img.data;

        let minX = w, minY = h, maxX = 0, maxY = 0;
        let found = false;

        const step = 2;
        const thr = 235;
        for (let y = 0; y < h; y += step){
          for (let x = 0; x < w; x += step){
            const i = (y * w + x) * 4;
            const r = d[i], g = d[i+1], b = d[i+2];
            const lum = 0.2126*r + 0.7152*g + 0.0722*b;
            if (lum < thr){
              found = true;
              if (x < minX) minX = x;
              if (y < minY) minY = y;
              if (x > maxX) maxX = x;
              if (y > maxY) maxY = y;
            }
          }
        }

        if (!found){
          return srcCanvas;
        }

        const pad = Math.round(Math.min(w, h) * 0.05) + 14;
        const sx = clamp(minX - pad, 0, w - 1);
        const sy = clamp(minY - pad, 0, h - 1);
        const ex = clamp(maxX + pad, 0, w - 1);
        const ey = clamp(maxY + pad, 0, h - 1);
        const sw = Math.max(1, ex - sx);
        const sh = Math.max(1, ey - sy);

        const scale = 2.0;
        const out = document.createElement("canvas");
        out.width = Math.max(1, Math.round(sw * scale));
        out.height = Math.max(1, Math.round(sh * scale));
        const octx = out.getContext("2d", { alpha: false });

        octx.fillStyle = "#ffffff";
        octx.fillRect(0,0,out.width,out.height);
        octx.imageSmoothingEnabled = true;
        octx.drawImage(srcCanvas, sx, sy, sw, sh, 0, 0, out.width, out.height);

        const oimg = octx.getImageData(0,0,out.width,out.height);
        const od = oimg.data;
        let sum = 0;
        const count = out.width * out.height;
        for (let i = 0; i < od.length; i += 4){
          const lum = 0.2126*od[i] + 0.7152*od[i+1] + 0.0722*od[i+2];
          sum += lum;
        }
        const avg = sum / count;
        const th2 = clamp(avg - 18, 175, 238);

        for (let i = 0; i < od.length; i += 4){
          const lum = 0.2126*od[i] + 0.7152*od[i+1] + 0.0722*od[i+2];
          const v = lum < th2 ? 0 : 255;
          od[i] = od[i+1] = od[i+2] = v;
          od[i+3] = 255;
        }
        octx.putImageData(oimg, 0, 0);

        return out;
      }

      async function detectTextFromCanvasProcessed(){
        if (!hasTextDetector()) return null;
        try{
          const detector = new TextDetector();
          const processed = cropAndScaleForOCR(el.handCanvas);
          const results = await detector.detect(processed);
          const raw = results.map(r => r.rawValue).join(" ").trim();
          return raw || null;
        } catch {
          return null;
        }
      }

      function pickBestCandidate(raw, expected){
        const cleaned = cleanOCRText(raw);
        if (!cleaned) return null;

        const candidates = new Set();
        candidates.add(cleaned);

        const tokens = cleaned.split(" ").filter(Boolean);
        if (tokens.length) {
          candidates.add(tokens.join(" "));
          candidates.add(tokens.join(""));
        }
        if (tokens.length >= 1){
          candidates.add(tokens[0]);
          candidates.add(tokens[tokens.length - 1]);
        }

        let best = null;
        let bestDist = Infinity;
        for (const c of candidates){
          const dist = levenshtein(expected, c);
          if (dist < bestDist){
            bestDist = dist;
            best = c;
          }
        }
        return best || cleaned;
      }

      async function readCanvasIntoInput(expected){
        const raw = await detectTextFromCanvasProcessed();
        if (!raw) return null;
        const best = pickBestCandidate(raw, expected);
        if (!best) return null;
        el.spellInput.value = best;
        return best;
      }

      /* ── Auto canvas OCR (debounced) ── */
      let _canvasOCRTimer = null;
      let _canvasOCRBusy = false;
      function _scheduleCanvasOCR(){
        if (_canvasOCRTimer) clearTimeout(_canvasOCRTimer);
        _canvasOCRTimer = setTimeout(() => _runCanvasOCR(), 1200);
      }
      async function _runCanvasOCR(){
        if (_canvasOCRBusy) return;
        if (state.mode !== "HAND" || state.hand.checked) return;
        // Try local TextDetector first
        if (hasTextDetector()) {
          try {
            const cur = getCurrent();
            const expected = displayPromptAnswer(cur).answer;
            await readCanvasIntoInput(expected);
            if ((el.spellInput.value || "").trim()) return;
          } catch {}
        }
        // Fallback: server Vision AI OCR
        _canvasOCRBusy = true;
        const prevPlaceholder = el.spellInput.placeholder;
        el.spellInput.placeholder = "読み取り中…";
        try {
          const canvas = el.handCanvas;
          if (!canvas) return;
          const dataUrl = canvas.toDataURL("image/png");
          const base = (typeof API_BASE === "string" ? API_BASE : "").replace(/\/+$/, "");
          const resp = await fetch(base + "/api/ocr/handwriting", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ image: dataUrl })
          });
          if (resp.ok) {
            const data = await resp.json();
            const text = String(data?.text || "").trim();
            if (text && !state.hand.checked) {
              el.spellInput.value = text;
            }
          }
        } catch (e) {
          console.warn("[OCR] server fallback failed:", e);
        } finally {
          _canvasOCRBusy = false;
          el.spellInput.placeholder = prevPlaceholder;
        }
      }

      // =========================
      // Marks (maru/batsu)
      // =========================
      function hideMark(){
        el.markLayer.classList.add("hidden");
        el.markLayer.classList.remove("show","ok","ng");
        el.svgOk.classList.add("hidden");
        el.svgNg.classList.add("hidden");
      }

      function showMark(isCorrect){
        el.markLayer.classList.remove("ok","ng");
        el.markLayer.classList.remove("show");
        el.markLayer.classList.remove("hidden");

        el.svgOk.classList.toggle("hidden", !isCorrect);
        el.svgNg.classList.toggle("hidden", isCorrect);

        void el.markLayer.offsetWidth;

        el.markLayer.classList.add(isCorrect ? "ok" : "ng");
        el.markLayer.classList.add("show");

        window.setTimeout(() => {
          el.markLayer.classList.remove("show");
          window.setTimeout(() => {
            el.markLayer.classList.add("hidden");
          }, 220);
        }, 900);
      }

      // =========================
      // Check (hand mode)
      // =========================
      async function checkHand(){
        const cur = getCurrent();
        if (!cur) return;
        if (state.hand.checked) return;
        if (state.hand.busy) return;

        state.hand.busy = true;
        el.primaryBtn.disabled = true;
        const qa = displayPromptAnswer(cur);
        const expected = String(qa.answer || "");
        const promptText = String(qa.prompt || "");

        // If input empty and detector exists, try OCR automatically
        let given = (el.spellInput.value || "").trim();
        if (!given && hasTextDetector()){
          el.primaryBtn.textContent = "読み取り中…";
          await readCanvasIntoInput(expected);
          given = (el.spellInput.value || "").trim();
        }
        const correct = computeCorrect(expected, given);

        // sound (SFX only, never loop)
        playSfx(correct ? "ok" : "ng");

        state.hand.checked = true;
        state.hand.correct = correct;
        state.hand.input = given;

        state.hand.results.push({
          id: cur.id,
          expected,
          given: given,
          correct: correct,
          promptMeaning: _quizCleanPromptText(promptText),
          promptText: _quizCleanPromptText(promptText)
        });

        if (correct) state.hand.scoreCorrect += 1;

        // UI
        el.spellInput.disabled = true;

        el.judgeBadge.classList.remove("hidden");
        el.judgeBadge.classList.toggle("ok", correct);
        el.judgeBadge.classList.toggle("ng", !correct);
        el.judgeBadge.textContent = correct ? "Correct" : "Wrong";

        showMark(correct);

        el.answerWrap.classList.remove("hidden");
        el.answerWrap.classList.remove("is-correct","is-wrong");
        el.answerWrap.classList.add(correct ? "is-correct" : "is-wrong");
        _renderFieldWithFormat(el.answerText, expected, qa.answerFormat, { displayMode: true });
        el.yourText.textContent = given ? `あなた：${given}` : "あなた：（未入力）";
        _renderExplanationPanel(cur);

        el.primaryBtn.textContent = "判定済み";
        el.primaryBtn.disabled = true;

        state.hand.busy = false;

        renderHeaderOnly();
        if (isAutoNextEnabled()){
          window.setTimeout(() => {
            if (state.view !== "QUIZ") return;
            if (state.mode !== "HAND") return;
            if (!state.hand.checked) return;
            next();
          }, 720);
        }
      }

      // =========================
      // Render
      // =========================
      
      function renderTitleHeader(){
        const d = state.deck;
        el.deckABtn.classList.toggle("active", d === "A");
        el.deckABtn.setAttribute("aria-selected", String(d === "A"));
        el.deckBBtn.classList.toggle("active", d === "B");
        el.deckBBtn.setAttribute("aria-selected", String(d === "B"));
        if (el.deckCBtn){
          el.deckCBtn.classList.toggle("active", d === "C");
          el.deckCBtn.setAttribute("aria-selected", String(d === "C"));
        }
        if (el.deckDBtn){
          el.deckDBtn.classList.toggle("active", d === "D");
          el.deckDBtn.setAttribute("aria-selected", String(d === "D"));
        }
        if (el.deckEBtn){
          el.deckEBtn.classList.toggle("active", d === "E");
          el.deckEBtn.setAttribute("aria-selected", String(d === "E"));
        }
        el.deckAllBtn.classList.toggle("active", d === "ALL");
        el.deckAllBtn.setAttribute("aria-selected", String(d === "ALL"));

        const sizeA = deckSize("A");
        const sizeB = deckSize("B");
        const sizeC = deckSize("C");
        const sizeD = deckSize("D");
        const sizeE = deckSize("E");
        const sizeAll = deckSize("ALL");
        el.deckStatus.textContent = `0〜200: ${sizeA} | 200〜400: ${sizeB} | 400〜600: ${sizeC} | 600〜800: ${sizeD} | 800〜1000: ${sizeE} | ALL: ${sizeAll}`;

        const curSize = deckSize(state.deck);
        const practiceCount = getPracticeQuestionCount();
        el.practiceHint.textContent = `選択範囲：${deckLabel(state.deck)}（${curSize}語）`;

        el.badgeSeq.textContent = `${curSize}`;
        el.badgeRnd.textContent = `${curSize}`;
        el.badgeChoice.textContent = `${Math.min(practiceCount, curSize)}`;
        el.badgeHand.textContent = `${Math.min(practiceCount, curSize)}`;
        if (el.badgeSwitch){
          const switchCount = _switchPlayableCountForDeck(state.deck);
          el.badgeSwitch.textContent = `${Math.min(practiceCount, switchCount)}`;
        }

        const can = curSize > 0;
        const canSwitch = _switchPlayableCountForDeck(state.deck) > 0;
        el.startSeqBtn.disabled = !can;
        el.startRndBtn.disabled = !can;
        el.startChoiceBtn.disabled = !can;
        el.startHandBtn.disabled = !can;
        if (el.startSwitchBtn) el.startSwitchBtn.disabled = !canSwitch;
      
        syncPresetUI();
      }

      function renderHeaderOnly(){
        const total = state.order.length || 0;
        const qIndex = clamp(state.index + 1, 0, total);
        const pct = total > 0 ? Math.round((qIndex / total) * 100) : 0;
        const cur = getCurrent();
        const meta = _quizEntryMeta(cur || {});

        el.progressText.textContent = `${pct}%`;
        if (el.quizTopNoText) el.quizTopNoText.textContent = `No.${qIndex} / ${total}`;
        if (el.quizSubjectText) el.quizSubjectText.textContent = meta.subject || subjectNameById(_activeSubjectId());

        el.modePill.textContent = `${meta.type || modeLabel()} ・ ${deckLabel(state.deck)}`;
        el.dirLabel.textContent = meta.type || dirLabel();
        if (el.quizTopicLabel){
          const topic = [meta.category, meta.difficulty].filter(Boolean).join("・");
          el.quizTopicLabel.textContent = topic || dirLabel();
        }

        // Update progress bar strip
        el.viewQuiz.style.setProperty("--quiz-progress", pct + "%");

        if (state.mode !== "CHOICE") setTimerPill(0);
      }
function renderQuestion(){
        const cur = getCurrent();
        if (!cur){
          el.noText.textContent = "No.—";
          el.promptText.textContent = "データがありません";
          if (el.promptMediaWrap){
            el.promptMediaWrap.replaceChildren();
            el.promptMediaWrap.classList.add("hidden");
          }
          _renderPromptDiagram(null);
          el.answerText.textContent = "";
          el.answerWrap.classList.add("hidden");
          el.answerWrap.classList.remove("is-correct","is-wrong");
          el.spellWrap.classList.add("hidden");
          el.handWrap.classList.add("hidden");
          el.choiceWrap.classList.add("hidden");
          hideMark();
          setTimerPill(0);
          return;
        }

        renderHeaderOnly();
        el.noText.textContent = `No.${cur.id}`;
        if (el.quizTopNoText) el.quizTopNoText.textContent = `No.${state.index + 1} / ${state.order.length || 0}`;

        const isHand = (state.mode === "HAND");
        const isChoice = (state.mode === "CHOICE");
        _renderPromptDiagram(cur);
        _renderQuestionMedia(cur);
        el.answerWrap.classList.remove("is-correct","is-wrong");

        // prompt
        if (isChoice){
          const qa = displayPromptAnswer(cur);
          _renderFieldWithFormat(el.promptText, _quizCleanPromptText(qa.prompt), qa.promptFormat, { displayMode: true });
        } else {
          const { prompt, answer, promptFormat, answerFormat } = displayPromptAnswer(cur);
          _renderFieldWithFormat(el.promptText, _quizCleanPromptText(prompt), promptFormat, { displayMode: true });
          _renderFieldWithFormat(el.answerText, answer, answerFormat, { displayMode: true });
        }
        _renderExplanationPanel(cur);

        // Prev only for SEQ/REVIEW_WRONG
        const allowPrev = (state.mode === "SEQ" || state.mode === "REVIEW_WRONG");
        el.prevBtn.classList.toggle("hidden", !allowPrev);
        el.prevBtn.disabled = !allowPrev || state.index === 0;

        // next button visibility
        const showChoiceManualNext = isChoice && !isAutoNextEnabled() && !!state.choice.locked;
        el.nextBtn.classList.toggle("hidden", isChoice && !showChoiceManualNext);
        el.nextBtn.disabled = false;

        // new set button: hand only
        el.newSetBtn.classList.toggle("hidden", !(state.mode === "HAND"));

        // primary button: hidden for choice
        el.primaryBtn.classList.toggle("hidden", isChoice);

        // Hand UI
        el.spellWrap.classList.toggle("hidden", !isHand);
        el.handWrap.classList.toggle("hidden", !isHand);

        // Choice UI
        el.choiceWrap.classList.toggle("hidden", !isChoice);

        if (isChoice){
          // setup options/timer per question if not ready
          if (!Array.isArray(state.choice.options) || !state.choice.options.length){
            buildChoiceOptionsForCurrent();
          }
          renderChoiceOptions();
          renderChoiceHeaderExtras();

          // answer hidden until resolved
          el.answerWrap.classList.add("hidden");
          el.answerWrap.classList.remove("is-correct","is-wrong");
          el.answerText.textContent = "";
          el.yourText.textContent = "";
          el.judgeBadge.classList.add("hidden");
          el.judgeBadge.classList.remove("ok","ng");
          el.judgeBadge.textContent = "—";
          hideMark();

          // controls
          el.restartBtn.classList.remove("hidden");
        } else if (isHand){
          el.handMini.textContent = "";
          el.readCanvasBtn.classList.add("hidden");

          el.primaryBtn.textContent = state.hand.checked ? "判定済み" : (state.hand.busy ? "読み取り中…" : "判定");
          el.primaryBtn.disabled = state.hand.checked || state.hand.busy;

          if (!state.hand.checked){
            el.answerWrap.classList.add("hidden");
            el.answerWrap.classList.remove("is-correct","is-wrong");
            hideMark();
          } else {
            el.answerWrap.classList.remove("hidden");
            el.answerWrap.classList.add(state.hand.correct ? "is-correct" : "is-wrong");
          }

          if (!state.hand.checked){
            el.judgeBadge.classList.add("hidden");
            el.judgeBadge.classList.remove("ok","ng");
            el.judgeBadge.textContent = "—";
          }

          // timer off
          setTimerPill(0);

        } else {
          // Study modes
          setTimerPill(0);
          el.readCanvasBtn.classList.add("hidden");
          hideMark();

          el.primaryBtn.disabled = false;
          if (state.showAnswer){
            el.answerWrap.classList.remove("hidden");
            el.primaryBtn.textContent = "答えを隠す";
          } else {
            el.answerWrap.classList.add("hidden");
            el.primaryBtn.textContent = "答えを表示";
          }

          el.judgeBadge.classList.add("hidden");
          el.judgeBadge.classList.remove("ok","ng");
          el.judgeBadge.textContent = "—";
        }

        // next button text (non-choice)
        if (!isChoice){
          if (state.mode === "HAND"){
            el.nextBtn.textContent = (state.index >= state.order.length - 1) ? "結果へ" : "次へ";
          } else if (state.done){
            el.nextBtn.textContent = "終了";
          } else {
            el.nextBtn.textContent = (state.index >= state.order.length - 1) ? "完了" : "次へ";
          }
        } else if (showChoiceManualNext){
          el.nextBtn.textContent = (state.index >= state.order.length - 1) ? "結果へ" : "次へ";
        }
      }

      function renderResult(){
        const kind = state.resultKind || state.mode || "HAND";
        const activeSid = _activeSubjectId();
        const isEnglish = _isEnglishSubjectId(activeSid);

        let total = 0;
        let correct = 0;
        let wrongItems = [];
        let allResults = [];

        if (kind === "CHOICE"){
          allResults = state.choice.results;
          total = allResults.length;
          correct = state.choice.correctCount;
          wrongItems = allResults.filter(r => !r.correct);

        } else {
          allResults = state.hand.results;
          total = allResults.length;
          correct = state.hand.scoreCorrect;
          wrongItems = allResults.filter(r => !r.correct);
        }

        // Review button visibility (hide if no wrong)
        if (wrongItems.length === 0){
          el.resultReviewBtn.disabled = true;
          el.resultReviewBtn.style.opacity = "0.55";
        } else {
          el.resultReviewBtn.disabled = false;
          el.resultReviewBtn.style.opacity = "";
        }

        const pct = total ? Math.round((correct / total) * 100) : 0;
        const wrong = total - correct;
        const elapsedMs = _quizElapsedMs();
        const avgMs = total ? elapsedMs / total : 0;
        const grade = _quizResultGrade(pct);
        const streak = _quizLongestStreak(allResults);
        const firstEntry = allResults.length && data && data.byId instanceof Map ? data.byId.get(allResults[0].id) : getCurrent();
        const meta = _quizEntryMeta(firstEntry || {});
        const headingEl = document.getElementById("resultHeading");
        const statsEl = document.getElementById("resultScoreStats");

        if (headingEl) headingEl.textContent = "結果";
        el.resultSub.textContent = `${deckLabel(state.deck)} ・ ${kind === "CHOICE" ? "選択本番" : "手書き本番"}`;
        el.scoreBig.textContent = `${correct} / ${total}`;
        el.scoreSub.textContent = "";
        if (el.resultPctValue) el.resultPctValue.textContent = `${pct}%`;
        if (el.resultTimeValue) el.resultTimeValue.textContent = _formatQuizDuration(elapsedMs);
        if (el.resultGradeValue){
          el.resultGradeValue.textContent = grade;
          el.resultGradeValue.dataset.grade = grade;
        }
        if (el.resultMetaChips){
          const chips = [
            meta.subject,
            meta.type || (kind === "CHOICE" ? "選択本番" : "手書き"),
            [meta.category, meta.difficulty].filter(Boolean).join("・")
          ].filter(Boolean);
          el.resultMetaChips.innerHTML = chips.map((v) => `<span>${escapeHtml(v)}</span>`).join("");
        }
        if (el.wrongSummary) el.wrongSummary.textContent = `間違い（${wrongItems.length}）`;
        if (statsEl){
          statsEl.innerHTML = `
            <div class="result-stat-card is-correct">
              <span class="result-stat-icon ms" aria-hidden="true">check</span>
              <div><span>正解</span><strong>${correct}</strong></div>
            </div>
            <div class="result-stat-card is-wrong">
              <span class="result-stat-icon ms" aria-hidden="true">close</span>
              <div><span>不正解</span><strong>${wrong}</strong></div>
            </div>
            <div class="result-stat-card is-streak">
              <span class="result-stat-icon ms" aria-hidden="true">local_fire_department</span>
              <div><span>連続正解</span><strong>${streak}<small>問</small></strong></div>
            </div>
            <div class="result-stat-card is-time">
              <span class="result-stat-icon ms" aria-hidden="true">schedule</span>
              <div><span>平均解答時間</span><strong>${_formatQuizDuration(avgMs, { compactSeconds: true })}</strong></div>
            </div>
          `;
        }
        if (el.resultCategoryBreakdown){
          const rows = _quizCategoryBreakdown(allResults);
          if (!rows.length){
            el.resultCategoryBreakdown.innerHTML = `<div class="result-breakdown-empty">分野データがありません。</div>`;
          } else {
            el.resultCategoryBreakdown.innerHTML = rows.map((row) => {
              const rowPct = row.total ? Math.round((row.correct / row.total) * 100) : 0;
              return `
                <div class="result-breakdown-card">
                  <div class="result-breakdown-top">
                    <span class="ms" aria-hidden="true">bar_chart</span>
                    <strong>${escapeHtml(row.category)}</strong>
                    <b>${rowPct}%</b>
                  </div>
                  <div class="result-breakdown-track"><span style="width:${rowPct}%"></span></div>
                </div>
              `;
            }).join("");
          }
        }

        // ── Answer Review Section ──
        _renderResultReview(kind, allResults, isEnglish);
      }

      function _renderResultReview(kind, allResults, isEnglish){
        if (!el.resultReviewList) return;
        el.resultReviewList.innerHTML = "";

        if (!allResults || !allResults.length){
          el.resultReviewSection.style.display = "none";
          return;
        }
        el.resultReviewSection.style.display = "";

        const wrongCount = allResults.filter((r) => !r.correct).length;
        if (!wrongCount){
          el.resultReviewList.innerHTML = `
            <div class="result-review-empty">
              <span class="ms" aria-hidden="true">verified</span>
              <strong>全問正解です</strong>
              <span>今回復習が必要な問題はありません。</span>
            </div>
          `;
          return;
        }

        // Reset filter to wrong-only for the dashboard view.
        if (el.resultReviewFilter){
          el.resultReviewFilter.querySelectorAll(".result-review-filter-btn").forEach((b) => {
            b.classList.toggle("is-active", b.getAttribute("data-review-filter") === "wrong");
          });
        }

        const isChoice = (kind === "CHOICE");

        for (let i = 0; i < allResults.length; i++){
          const r = allResults[i];
          const isCorrect = !!r.correct;
          const isTimeout = isChoice && !!r.timedOut;

          // Extract display values
          let promptText, givenText, correctText;
          if (isChoice){
            promptText = String(r.promptText ?? r.word ?? "");
            givenText = String(r.chosenAnswer ?? r.chosenMeaning ?? "");
            correctText = String(r.correctAnswer ?? r.correctMeaning ?? "");
            if (isTimeout) givenText = "（時間切れ）";
            else if (!givenText.trim() || givenText === "(NO SELECT)") givenText = "（未選択）";
          } else {
            promptText = String(r.promptText ?? r.promptMeaning ?? "");
            givenText = String(r.given ?? "");
            correctText = String(r.expected ?? "");
            if (!givenText.trim()) givenText = "（未入力）";
          }

          promptText = _quizCleanPromptText(promptText);
          const promptShort = promptText.length > 42 ? promptText.slice(0, 42) + "…" : promptText;

          // Badge
          let badgeClass, badgeText;
          if (isTimeout){
            badgeClass = "is-timeout";
            badgeText = "時間切れ";
          } else if (isCorrect){
            badgeClass = "is-correct";
            badgeText = "正解";
          } else {
            badgeClass = "is-wrong";
            badgeText = "不正解";
          }

          const wordObj = (data && data.byId instanceof Map) ? data.byId.get(r.id) : null;
          const explanation = wordObj ? String(wordObj.explanation ?? wordObj.note ?? "").trim() : "";
          const bodyHtml = `
            <div class="result-review-answer-grid">
              <div class="result-review-answer is-user">
                <span>あなたの解答</span>
                <strong>${escapeHtml(givenText)}</strong>
              </div>
              <div class="result-review-answer is-correct-answer">
                <span>正解</span>
                <strong>${escapeHtml(correctText)}</strong>
              </div>
              <div class="result-review-explain-cell">
                <span>解説</span>
                <p>${escapeHtml(explanation || "この問題には解説が登録されていません。")}</p>
              </div>
            </div>
          `;

          const details = document.createElement("details");
          details.className = `result-review-item${isCorrect ? "" : " is-wrong"}`;
          details.dataset.correct = isCorrect ? "1" : "0";
          details.classList.toggle("review-hidden", isCorrect);
          details.innerHTML = `
            <summary>
              <span class="result-review-num">No.${escapeHtml(r.id)}</span>
              <span class="result-review-prompt">${escapeHtml(promptShort)}</span>
              <span class="result-review-badge ${badgeClass}">${badgeText}</span>
              <span class="ms result-review-chevron" aria-hidden="true">expand_more</span>
            </summary>
            <div class="result-review-body">${bodyHtml}</div>
          `;
          el.resultReviewList.appendChild(details);
        }
      }
      function renderAll(){
        updateDataStatus();
        updateDebugBar();
        _ensureBuiltinPresetTerminationPolicy();

        const isEnJa = state.settings.direction === "EN_JA";
        if (el.dirEnJaBtn){
          el.dirEnJaBtn.classList.toggle("active", isEnJa);
          el.dirEnJaBtn.setAttribute("aria-selected", String(isEnJa));
        }
        if (el.dirJaEnBtn){
          el.dirJaEnBtn.classList.toggle("active", !isEnJa);
          el.dirJaEnBtn.setAttribute("aria-selected", String(!isEnJa));
        }

        if (el.animToggle) el.animToggle.checked = state.settings.animations;
        if (el.sfxToggle) el.sfxToggle.checked = state.settings.sfx;
        if (el.bgmToggle) el.bgmToggle.checked = state.settings.bgm;
        // BGM volume buttons
        const bv = state.settings.bgmVolume || "DEFAULT";
        if (el.bgmVolLargeBtn){
          el.bgmVolLargeBtn.classList.toggle("active", bv === "LARGE");
          el.bgmVolLargeBtn.setAttribute("aria-selected", String(bv === "LARGE"));
        }
        if (el.bgmVolDefaultBtn){
          el.bgmVolDefaultBtn.classList.toggle("active", bv === "DEFAULT");
          el.bgmVolDefaultBtn.setAttribute("aria-selected", String(bv === "DEFAULT"));
        }
        if (el.bgmVolSmallBtn){
          el.bgmVolSmallBtn.classList.toggle("active", bv === "SMALL");
          el.bgmVolSmallBtn.setAttribute("aria-selected", String(bv === "SMALL"));
        }

        if (el.debugToggle) el.debugToggle.checked = state.settings.debug;
        _settingsSyncControls();
        if (el.settingsOverlay && !el.settingsOverlay.classList.contains("hidden")){
          _adminRenderUI();
        }

        if (state.view === "TITLE"){
          renderTitleHeader();
          _appRenderCurrentTab();
        } else if (state.view === "QUIZ"){
          renderQuestion();
        } else if (state.view === "SWITCH"){
          renderSwitchQuestion();
        } else if (state.view === "RESULT"){
          renderResult();
        }
        _customSelectEnhance(document);
        if (typeof _vqOsRenderAll === "function") _vqOsRenderAll();
      }

      // =========================
      // Navigation
      // =========================

      function _canStartCurrentPreset(){
        const pid = getActivePresetId();
        if (!pid){
          uiToast("プリセットが選択されていません。");
          return false;
        }
        const count = getActiveWords().length;
        if (!count){
          uiToast("選択中のプリセットに問題がありません。");
          return false;
        }
        return true;
      }
      
      function startMode(mode, jumpId){
        if (!_canStartCurrentPreset()) return;
        state.mode = mode;
        state.index = 0;
        state.showAnswer = false;
        state.done = false;

        clearChoiceTimer();

        if (mode === "HAND"){
          state.hand.checked = false;
          state.hand.correct = null;
          state.hand.input = "";
          state.hand.busy = false;
          state.hand.results = [];
          state.hand.scoreCorrect = 0;
        }

        state.order = buildOrder(mode);

        // optional: jump to a specific word id (used by Search)
        if (mode === "SEQ" && jumpId != null){
          const jid = Number(jumpId);
          const idx = state.order.findIndex(w => w && Number(w.id) === jid);
          if (idx >= 0) state.index = idx;
        }
        if (mode === "HAND"){
          _appSaveResume("HAND");
        }

        _startQuizSessionTimer();
        setView("QUIZ");
        if (mode === "HAND") resetHandPerQuestion();

        syncBgmToView();
        animateCardSwap(renderAll);
      }

      function startChoiceMode(timeLimitSec){
        if (!_canStartCurrentPreset()) return;
        closeTimeSelect();
        const resolvedLimit = (timeLimitSec === undefined || timeLimitSec === null)
          ? getChoiceDefaultTimeLimitSec()
          : (Number(timeLimitSec) || 0);

        state.mode = "CHOICE";
        state.index = 0;
        state.showAnswer = false;
        state.done = false;

        resetChoiceSession(resolvedLimit);

        // Always create a fresh random set for each start
        createChoiceSetIds(getSetKey(state.deck), true);

        state.order = buildOrder("CHOICE");
        _appSaveResume("CHOICE");
        void _appQreditStartExamSession();
        _startQuizSessionTimer();

        // prepare first question
        buildChoiceOptionsForCurrent();
        renderChoiceOptions();

        setView("QUIZ");
        syncBgmToView();
        startChoiceTimer();

        animateCardSwap(renderAll);
      }

      function startSwitchMode(){
        if (!_canStartCurrentPreset()) return;
        const playableCount = _switchPlayableCountForDeck(state.deck);
        if (!playableCount){
          uiToast("Switch Modeで使える問題がありません。英文や空白区切りの解答を含む問題を作成してください。");
          return;
        }
        state.mode = "SWITCH";
        state.index = 0;
        state.showAnswer = false;
        state.done = false;
        clearChoiceTimer();
        resetSwitchSession();
        state.order = buildOrder("SWITCH");
        if (!state.order.length){
          uiToast("Switch Modeで使える問題がありません。");
          return;
        }
        prepareSwitchQuestion();
        _startQuizSessionTimer();
        setView("SWITCH");
        syncBgmToView();
        renderAll();
      }

      let _startCountPicking = false;
      async function _pickStartQuestionCount(modeLabel){
        const fallback = START_MODE_QUESTION_COUNT_SET.has(Number(state.startModeQuestionCount))
          ? Number(state.startModeQuestionCount)
          : 100;
        let selected = fallback;
        const options = START_MODE_QUESTION_COUNTS.map((n) => `<option value="${n}">${n}問</option>`).join("");
        const htmlStr = `
          <div style="display:flex; flex-direction:column; gap:10px;">
            <div class="note">${modeLabel} の問題数を選択してください。</div>
            <label class="settings-row is-static" for="startQuestionCountSelect" style="margin:0;">
              <span class="label">問題数</span>
              <select id="startQuestionCountSelect" class="select settings-select">${options}</select>
            </label>
          </div>
        `;
        const p = uiConfirmHtml(htmlStr, {
          title: `${modeLabel} 開始`,
          okText: "開始",
          cancelText: "キャンセル"
        });
        _runIdle(() => {
          const sel = document.getElementById("startQuestionCountSelect");
          if (!sel) return;
          sel.value = String(fallback);
          selected = Number(sel.value) || fallback;
          _customSelectEnhance(sel);
          _customSelectRefresh(sel);
          sel.addEventListener("change", () => {
            const v = Number(sel.value);
            if (START_MODE_QUESTION_COUNT_SET.has(v)) selected = v;
          });
        });
        const ok = await p;
        if (!ok) return null;
        return START_MODE_QUESTION_COUNT_SET.has(selected) ? selected : fallback;
      }

      async function _startModeWithQuestionCountPick(kind){
        if (_startCountPicking) return;
        _startCountPicking = true;
        try{
          const isChoice = kind === "CHOICE";
          const modeLabel = isChoice ? "EXAM MODE" : "WRITE MODE";
          const picked = await _pickStartQuestionCount(modeLabel);
          if (!Number.isFinite(picked)) return;
          state.startModeQuestionCount = Number(picked);
          if (isChoice) startChoiceMode(getChoiceDefaultTimeLimitSec());
          else startMode("HAND");
        } finally {
          _startCountPicking = false;
        }
      }

function goTitle(){
        stopBgm(true);
        clearChoiceTimer();
        _stopQuizElapsedTicker();
        closeTimeSelect();
        _clearRecommendScope();
        _appQreditClearExamSession();
        state.mode = null;
        state.order = [];
        state.index = 0;
        state.showAnswer = false;
        state.done = false;
        setView("TITLE");
        renderAll();
      }
      function _quizReturnToLibrary(){
        goTitle();
        try{ _appSetTab(APP_TAB_KEY.LIBRARY); }catch{}
      }

      function goResult(kind){
        clearChoiceTimer();
        _finishQuizSessionTimer();
        if (String(kind || state.mode || "") === "CHOICE"){
          void _appQreditCompleteExamSession();
        } else {
          _appQreditClearExamSession();
        }
        state.resultKind = kind || state.mode || null;
        setView("RESULT");
        renderAll();
      }

      function next(){
        if (state.view !== "QUIZ") return;

        if (state.mode === "HAND"){
          // IMPORTANT: NO auto-judge here.
          if (!state.hand.checked) return;

          if (state.index >= state.order.length - 1){
            goResult("HAND");
            return;
          }

          state.index += 1;
          resetHandPerQuestion();
          animateCardSwap(renderAll);
          return;
        }
        if (state.mode === "CHOICE"){
          if (!state.choice.locked) return;
          if (state.index >= state.order.length - 1){
            goResult("CHOICE");
            return;
          }
          state.index += 1;
          state.showAnswer = false;
          state.done = false;
          state.choice.options = [];
          state.choice.correctIndex = -1;
          state.choice.locked = false;
          buildChoiceOptionsForCurrent();
          animateCardSwap(() => {
            renderAll();
            startChoiceTimer();
          });
          return;
        }

        if (state.done){
          goTitle();
          return;
        }

        if (state.index >= state.order.length - 1){
          state.done = true;
          state.showAnswer = true;
          animateCardSwap(renderAll);
          return;
        }

        state.index += 1;
        state.showAnswer = false;
        animateCardSwap(renderAll);
      }

      function prev(){
        if (state.view !== "QUIZ") return;

        const allowPrev = (state.mode === "SEQ" || state.mode === "REVIEW_WRONG");
        if (!allowPrev) return;
        if (state.index <= 0) return;

        state.index -= 1;
        state.showAnswer = false;

        animateCardSwap(renderAll);
      }

      function primaryAction(){
        if (state.view !== "QUIZ") return;

        if (state.mode === "HAND"){
          checkHand();
          return;
        }

        state.showAnswer = !state.showAnswer;
        animateCardSwap(renderAll);
      }

      
      function restart(){
        if (state.view !== "QUIZ") return;

        clearChoiceTimer();

        state.index = 0;
        state.done = false;
        state.showAnswer = false;

        if (state.mode === "RND"){
          state.order = buildOrder("RND");

        } else if (state.mode === "HAND"){
          state.hand.checked = false;
          state.hand.correct = null;
          state.hand.input = "";
          state.hand.busy = false;
          state.hand.results = [];
          state.hand.scoreCorrect = 0;
          state.order = buildOrder("HAND");
          resetHandPerQuestion();

        } else if (state.mode === "CHOICE"){
          // keep chosen timeLimitSec; reset score/results
          const t = state.choice.timeLimitSec || 0;
          resetChoiceSession(t);
          state.order = buildOrder("CHOICE");
          buildChoiceOptionsForCurrent();
          renderChoiceOptions();
          startChoiceTimer();

        } else if (state.mode === "SEQ"){
          state.order = buildOrder("SEQ");

        } else if (state.mode === "REVIEW_WRONG"){
          state.order = buildOrder("REVIEW_WRONG");
        }

        animateCardSwap(renderAll);
      }

