      /* ══════════════════════════════════════════════════════════
         テーマの「自動」＝ 時刻で切り替える

           18:00 〜 翌 5:59  … ダーク
           6:00 〜 17:59     … ライト

         端末の設定（prefers-color-scheme）ではなく **時計**で決める。
         端末を暗くしていなくても夕方以降は目が疲れるため。
         境目はどちらも「その時刻以降」。18:00:00 ちょうどはダーク、
         6:00:00 ちょうどはライト。

         ＊ここは以前、AUTO でも必ず "light" を返していた（自動ではなかった）。
         ══════════════════════════════════════════════════════════ */
      /* ★ const ではなく function にする。
         const は宣言行に来るまで触れない（巻き上がらない）ので、
         先に走る applyTheme() から参照すると
         "Cannot access 'AUTO_DARK_FROM' before initialization" で落ちる。
         実際にそれで data-theme-mode が付かなくなった。 */
      function AUTO_DARK_FROM(){ return 18; }   /* この時刻からダーク */
      function AUTO_LIGHT_FROM(){ return 6; }   /* この時刻からライト */
      function _autoThemeIsDark(now){
        const h = (now instanceof Date ? now : new Date()).getHours();
        return h >= AUTO_DARK_FROM() || h < AUTO_LIGHT_FROM();
      }
      function _resolveThemeMode(){
        const t = String(state.settings.theme || "AUTO");
        if (t === "LIGHT") return "light";
        if (t === "DARK") return "dark";
        return _autoThemeIsDark() ? "dark" : "light";
      }
      /* 次の境目（6:00 か 18:00）に、開いたままでも切り替える。
         起きるのは 1 日 2 回だけ。毎分見に行くようなことはしない。 */
      var _autoThemeTimer = null;   /* let だと同じ落とし穴を踏む（巻き上がらない） */
      function _scheduleAutoTheme(){
        if (_autoThemeTimer){ clearTimeout(_autoThemeTimer); _autoThemeTimer = null; }
        if (String(state.settings.theme || "AUTO") !== "AUTO") return;
        const now = new Date();
        const next = new Date(now);
        next.setMinutes(0, 1, 0);          /* 境目を 1 秒またいでから見る */
        const h = now.getHours();
        if (h < AUTO_LIGHT_FROM()) next.setHours(AUTO_LIGHT_FROM());
        else if (h < AUTO_DARK_FROM()) next.setHours(AUTO_DARK_FROM());
        else { next.setDate(next.getDate() + 1); next.setHours(AUTO_LIGHT_FROM()); }
        let wait = next.getTime() - now.getTime();
        /* 端末が寝ていた・時計がずれた等で過去になったら、すぐ見直す */
        if (!(wait > 0)) wait = 1000;
        /* setTimeout は 24.8 日を超えると溢れる。上限を置く（実際は最大 12 時間）。 */
        _autoThemeTimer = setTimeout(function(){ applyTheme(); }, Math.min(wait, 12 * 3600 * 1000));
      }
      function applyTheme(){
        const root = document.documentElement;
        if (!root) return;
        const mode = _resolveThemeMode();
        root.setAttribute("data-theme-mode", mode);
        const meta = document.querySelector('meta[name="color-scheme"]');
        if (meta){
          meta.setAttribute("content", mode === "dark" ? "dark light" : "light dark");
        }
        /* ★ 時計のある帯の色も 合わせる（2026-08-18）。
           アプリ側のテーマ（自動/ライト/ダーク）は 端末の設定と 食い違うことが
           あるので、**実際に適用した側**の地色を 両方の meta へ書く。
           そうしないと 端末がライトでアプリがダークのとき、上だけ白く残る。 */
        try {
          const 地色 = mode === "dark" ? "#131218" : "#F7F6FB";
          document.querySelectorAll('meta[name="theme-color"]').forEach(function(m){
            m.setAttribute("content", 地色);
          });
        } catch (e) {}
        _scheduleAutoTheme();
      }
      try { window._autoThemeIsDark = _autoThemeIsDark; } catch (e) {}
      /* 端末が寝て起きたときは、経過が読めないのでその場で見直す。 */
      try {
        document.addEventListener("visibilitychange", function(){
          if (!document.hidden) applyTheme();
        });
      } catch (e) {}
      function applyFontSize(){
        const root = document.documentElement;
        if (!root) return;
        const size = SETTINGS_LEVELS.has(String(state.settings.fontSize || "")) ? String(state.settings.fontSize) : "DEFAULT";
        const pct = size === "SMALL" ? 94 : (size === "LARGE" ? 108 : 100);
        root.setAttribute("data-font-size", size);
        root.style.webkitTextSizeAdjust = `${pct}%`;
        root.style.textSizeAdjust = `${pct}%`;
        if (document.body){
          document.body.style.webkitTextSizeAdjust = `${pct}%`;
          document.body.style.textSizeAdjust = `${pct}%`;
        }
      }
