      function _adminUserIsAdmin(user){
        const email = String(user?.email || "").trim().toLowerCase();
        if (email && (ADMIN_EMAILS.has(email) || email === String(ADMIN_EMAIL).trim().toLowerCase())) return true;
        const uidRaw = (user?.id ?? user?.userId ?? user?.uid ?? authState?.user?.id ?? authState?.user?.userId ?? 0);
        const uid = String(Math.max(0, Number(uidRaw || 0)) || "").trim();
        if (uid && ADMIN_USER_IDS.has(uid)) return true;
        const nickRaw = String(user?.nickname || authState?.user?.nickname || user?.displayName || "").trim();
        const nick = nickRaw.toLowerCase().replace(/\s+/g, "");
        if (nick && ADMIN_NICKNAMES.has(nick)) return true;
        return false;
      }
      async function _adminAuthHeaders(options = {}){
        const opts = (options && typeof options === "object") ? options : {};
        const headers = {};
        if (opts.includeContentType !== false) headers["Content-Type"] = "application/json";
        const includeFirebase = opts.includeFirebase !== false;
        const includeAppAuth = opts.includeAppAuth !== false;
        const includeAdminKey = !!opts.includeAdminKey;
        if (includeAppAuth){
          const authToken = (typeof _authGetToken === "function") ? String(_authGetToken() || "").trim() : "";
          if (authToken) headers.Authorization = `Bearer ${authToken}`;
        }
        if (includeFirebase){
          try{
            const auth = _adminGetAuth();
            const user = opts.user || _adminState.user || auth?.currentUser || null;
            if (user && typeof user.getIdToken === "function"){
              const token = String(await user.getIdToken()).trim();
              if (token) headers["x-firebase-id-token"] = token;
            }
          }catch{}
        }
        if (includeAdminKey){
          const adminKey = _maintenanceAdminToken();
          if (adminKey){
            headers["x-admin-token"] = adminKey;
            headers["x-admin-key"] = adminKey;
            headers["x-maintenance-token"] = adminKey;
            headers["x-maintenance-key"] = adminKey;
          }
        }
        return headers;
      }
      function _adminHasAuthHeaders(headers){
        const src = headers && typeof headers === "object" ? headers : {};
        return !!(
          String(src.Authorization || "").trim()
          || String(src["x-firebase-id-token"] || "").trim()
          || String(src["x-admin-token"] || "").trim()
          || String(src["x-admin-key"] || "").trim()
          || String(src["x-maintenance-token"] || "").trim()
          || String(src["x-maintenance-key"] || "").trim()
        );
      }
      async function _adminRefreshPrivilege(user, opts = {}){
        const target = user || null;
        if (!target){
          _adminState.isAdmin = false;
          return false;
        }
        try{
          const headers = await _adminAuthHeaders({
            includeContentType: false,
            includeAppAuth: false,
            includeAdminKey: false,
            user: target
          });
          if (String(headers["x-firebase-id-token"] || "").trim()){
            const body = await _appApiJson("/api/admin/access", {
              method: "GET",
              headers
            });
            const ok = !!body?.ok && !!body?.isAdmin;
            _adminState.isAdmin = ok;
            return ok;
          }
        }catch(err){
          if (!opts?.silent){
            _adminSetStatus(`権限確認に失敗しました: ${String(err?.message || err)}`, "error");
          }
        }
        const fallback = _adminUserIsAdmin(target);
        _adminState.isAdmin = fallback;
        return fallback;
      }
      function _maintenanceDefaultConfig(){
        return {
          enabled: false,
          mode: "manual",
          startAt: 0,
          endAt: 0,
          dailyStartHm: "01:00",
          dailyEndHm: "07:30",
          dailyDateJst: "",
          forceNow: false,
          active: false,
          title: "メンテナンス中",
          message: "現在メンテナンスを実施しています。しばらくお待ちください。",
          updatedAt: 0,
          updatedBy: ""
        };
      }
      function _maintenanceNormalizeHm(v, fallback = "01:00"){
        const s = String(v || "").trim();
        const m = s.match(/^(\d{1,2}):(\d{2})$/);
        if (!m) return fallback;
        const hh = Math.max(0, Math.min(23, Number(m[1] || 0)));
        const mm = Math.max(0, Math.min(59, Number(m[2] || 0)));
        return `${_fmt2(hh)}:${_fmt2(mm)}`;
      }
      function _maintenanceHmToMinutes(v){
        const s = _maintenanceNormalizeHm(v, "");
        if (!s) return -1;
        const m = s.match(/^(\d{2}):(\d{2})$/);
        if (!m) return -1;
        return (Number(m[1]) * 60) + Number(m[2]);
      }
      function _maintenanceJstParts(now = Date.now()){
        try{
          const d = new Intl.DateTimeFormat("en-CA", {
            timeZone: "Asia/Tokyo",
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hourCycle: "h23"
          }).formatToParts(new Date(now));
          const pick = (type) => Number((d.find((x) => x.type === type)?.value) || 0);
          return {
            year: pick("year"),
            month: pick("month"),
            day: pick("day"),
            hour: pick("hour"),
            minute: pick("minute")
          };
        }catch{
          const d = new Date(now);
          return {
            year: d.getFullYear(),
            month: d.getMonth() + 1,
            day: d.getDate(),
            hour: d.getHours(),
            minute: d.getMinutes()
          };
        }
      }
      function _maintenanceJstYmd(now = Date.now()){
        const p = _maintenanceJstParts(now);
        return `${Math.max(0, Number(p.year || 0))}-${_fmt2(Math.max(1, Number(p.month || 1)))}-${_fmt2(Math.max(1, Number(p.day || 1)))}`;
      }
      function _maintenanceTokyoLocalToUtcMs(year, month, day, hour, minute){
        return Date.UTC(year, Math.max(0, month - 1), day, hour - 9, minute, 0, 0);
      }
      function _maintenanceResolveWindow(config, nowMs){
        const cfg = _maintenanceNormalizeConfig(config);
        const now = Number(nowMs || Date.now());
        if (cfg.mode !== "daily"){
          return {
            startAt: Number(cfg.startAt || 0),
            endAt: Number(cfg.endAt || 0),
            active: !!(cfg.enabled && cfg.startAt > 0 && cfg.endAt > cfg.startAt && now >= cfg.startAt && now < cfg.endAt)
          };
        }
        const p = _maintenanceJstParts(now);
        const startMin = _maintenanceHmToMinutes(cfg.dailyStartHm);
        const endMin = _maintenanceHmToMinutes(cfg.dailyEndHm);
        const minuteOfDay = (Math.max(0, Number(p.hour || 0)) * 60) + Math.max(0, Number(p.minute || 0));
        const startAt = _maintenanceTokyoLocalToUtcMs(p.year, p.month, p.day, Math.floor(startMin / 60), startMin % 60);
        const endAtRaw = _maintenanceTokyoLocalToUtcMs(p.year, p.month, p.day, Math.floor(endMin / 60), endMin % 60);
        const dayMatch = !cfg.dailyDateJst || _maintenanceJstYmd(now) === String(cfg.dailyDateJst || "");
        if (!dayMatch && !cfg.forceNow){
          return { startAt, endAt: endAtRaw, active: false };
        }
        if (startMin < 0 || endMin < 0 || startMin === endMin){
          return { startAt, endAt: endAtRaw, active: !!cfg.forceNow };
        }
        if (endMin > startMin){
          return {
            startAt,
            endAt: endAtRaw,
            active: !!(cfg.enabled && (cfg.forceNow || (minuteOfDay >= startMin && minuteOfDay < endMin)))
          };
        }
        const active = minuteOfDay >= startMin || minuteOfDay < endMin;
        return {
          startAt: minuteOfDay < endMin ? (startAt - 86400000) : startAt,
          endAt: minuteOfDay < endMin ? endAtRaw : (endAtRaw + 86400000),
          active: !!(cfg.enabled && (cfg.forceNow || active))
        };
      }
      function _maintenanceNormalizeConfig(input){
        const d = _maintenanceDefaultConfig();
        const src = (input && typeof input === "object") ? input : {};
        const startAt = Number(src.startAt || 0);
        const endAt = Number(src.endAt || 0);
        const modeRaw = String(src.mode || src.timeMode || d.mode || "manual").trim().toLowerCase();
        const mode = modeRaw === "daily" ? "daily" : "manual";
        const dailyDateRaw = String(src.dailyDateJst || src.dateJst || "").trim();
        return {
          enabled: !!src.enabled,
          mode,
          startAt: Number.isFinite(startAt) ? startAt : 0,
          endAt: Number.isFinite(endAt) ? endAt : 0,
          dailyStartHm: _maintenanceNormalizeHm(src.dailyStartHm || src.dailyStart || d.dailyStartHm, d.dailyStartHm),
          dailyEndHm: _maintenanceNormalizeHm(src.dailyEndHm || src.dailyEnd || d.dailyEndHm, d.dailyEndHm),
          dailyDateJst: /^\d{4}-\d{2}-\d{2}$/.test(dailyDateRaw) ? dailyDateRaw : "",
          forceNow: !!src.forceNow,
          active: (typeof src.active === "boolean") ? src.active : false,
          title: String(src.title || d.title || "").trim() || d.title,
          message: String(src.message || d.message || "").trim() || d.message,
          updatedAt: Number(src.updatedAt || 0) || 0,
          updatedBy: String(src.updatedBy || "").trim()
        };
      }
      function _maintenanceIsActive(config, nowMs){
        const cfg = _maintenanceNormalizeConfig(config);
        const now = Number(nowMs || Date.now());
        if (!cfg.enabled) return false;
        const win = _maintenanceResolveWindow(cfg, now);
        return !!win.active;
      }
      function _maintenanceFmtDate(ms){
        const n = Number(ms) || 0;
        if (!n) return "—";
        return formatDateTime(n);
      }
      function _maintenanceFmtRemain(ms){
        const n = Math.max(0, Number(ms) || 0);
        if (!n) return "00:00";
        const sec = Math.floor(n / 1000);
        const h = Math.floor(sec / 3600);
        const m = Math.floor((sec % 3600) / 60);
        const s = sec % 60;
        if (h > 0){
          return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
        }
        return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
      }
      function _maintenanceCanBypass(){
        if (_adminState.isAdmin) return true;
        if (_adminUserIsAdmin(_adminState.user)) return true;
        if (_adminUserIsAdmin(authState.user)) return true;
        return false;
      }
