      function _maintenanceAdminToken(){
        const keyEl = document.getElementById("adminAiIngestKey");
        return String(keyEl?.value || "").trim();
      }
      async function _maintenanceSaveConfigToServer(payload){
        const bases = (typeof _authApiBaseCandidates === "function")
          ? _authApiBaseCandidates()
          : [String(AUTH_API_BASE || "").trim().replace(/\/+$/, "")].filter(Boolean);
        const headersBase = await _adminAuthHeaders({
          includeContentType: true,
          includeAppAuth: true,
          includeAdminKey: true
        });
        let lastErr = null;
        if (!_adminHasAuthHeaders(headersBase)){
          throw new Error("Adminログインまたは管理者キーが必要です。");
        }
        if (!bases.length){
          throw new Error("認証APIの接続先が未設定です。");
        }
        for (const base of bases){
          const ctrl = new AbortController();
          const timer = setTimeout(() => ctrl.abort(), 10000);
          try{
            const headers = { ...headersBase };
            const adminToken = String(headers["x-admin-token"] || headers["x-maintenance-token"] || "").trim();
            const reqBody = Object.assign({}, payload || {}, adminToken ? { adminToken } : {});
            const res = await fetch(_authApiUrl(base, MAINTENANCE_ADMIN_PATH), {
              method: "POST",
              headers,
              body: JSON.stringify(reqBody),
              signal: ctrl.signal
            });
            const txt = await res.text();
            let body = null;
            try{ body = txt ? JSON.parse(txt) : {}; }catch{ body = {}; }
            if (!res.ok){
              const msg = String(body?.message || `${res.status} ${res.statusText}`);
              const code = String(body?.code || `HTTP_${res.status}`);
              const err = new Error(`${msg}`);
              err.code = code;
              throw err;
            }
            const maintenance = body?.maintenance && typeof body.maintenance === "object"
              ? body.maintenance
              : (typeof body === "object" ? body : null);
            if (!maintenance){
              throw new Error("保存レスポンスが不正です。");
            }
            return maintenance;
          }catch(err){
            lastErr = err;
          }finally{
            clearTimeout(timer);
          }
        }
        throw lastErr || new Error("メンテナンス設定の保存に失敗しました。");
      }
      function _maintenanceUpdatedBy(){
        const uid = String(_adminState.user?.uid || "").trim();
        const email = String(_adminState.user?.email || "").trim();
        if (uid && email) return `${uid}:${email}`;
        if (email) return email;
        const aid = _authDisplayId(authState.user);
        return String(aid || "admin");
      }
      async function _maintenanceSaveFromAdmin(){
        if (!_adminState.isAdmin){
          _maintenanceSetAdminStatus("Adminログインが必要です。", "error");
          return;
        }
        let form;
        try{
          form = _maintenanceReadAdminForm();
        }catch(err){
          _maintenanceSetAdminStatus(String(err?.message || err), "error");
          return;
        }
        _maintenanceState.saving = true;
        _maintenanceSetAdminBusy(true);
        _maintenanceSetAdminStatus("保存中…");
        showLoading("メンテナンス設定を保存中…");
        try{
          const payload = {
            enabled: !!form.enabled,
            mode: String(form.mode || "manual"),
            startAt: Number(form.startAt || 0),
            endAt: Number(form.endAt || 0),
            dailyStartHm: String(form.dailyStartHm || "01:00"),
            dailyEndHm: String(form.dailyEndHm || "07:30"),
            dailyDateJst: String(form.dailyDateJst || ""),
            forceNow: !!form.forceNow,
            title: String(form.title || "メンテナンス中"),
            message: String(form.message || ""),
          };
          const maintenance = await _maintenanceSaveConfigToServer(payload);
          _maintenanceState.config = _maintenanceNormalizeConfig({
            ...maintenance,
            enabled: payload.enabled,
            mode: payload.mode,
            startAt: Number(payload.startAt || 0),
            endAt: Number(payload.endAt || 0),
            dailyStartHm: payload.dailyStartHm,
            dailyEndHm: payload.dailyEndHm,
            dailyDateJst: payload.dailyDateJst,
            forceNow: !!payload.forceNow,
            title: String(payload.title || ""),
            message: String(payload.message || "")
          });
          _maintenanceState.loaded = true;
          _maintenanceState.bypass = false;
          _maintenanceSetAdminStatus("保存しました。", "ok");
          uiToast("メンテナンス設定を保存しました");
          _maintenanceRenderAdminForm();
          _maintenanceRenderOverlay();
        }catch(err){
          const code = String(err?.code || "ERROR");
          const msg = String(err?.message || err);
          if (code === "FORBIDDEN" && /管理者権限/.test(msg)) {
            _maintenanceSetAdminStatus("保存失敗: 管理者としてログインしてから再度お試しください。", "error");
          } else {
            _maintenanceSetAdminStatus(`保存失敗: ${code} / ${msg}`, "error");
          }
        }finally{
          _maintenanceState.saving = false;
          _maintenanceSetAdminBusy(false);
          hideLoading();
        }
      }
      async function _maintenanceClearExpiredFlagFromAdmin(){
        if (!_adminState.isAdmin){
          _maintenanceSetAdminStatus("Adminログインが必要です。", "error");
          return;
        }
        const cfg = _maintenanceNormalizeConfig(_maintenanceState.config || _maintenanceDefaultConfig());
        if (cfg.mode === "daily"){
          _maintenanceSetAdminStatus("dailyモードでは「終了済みを無効化」は不要です。enabledをOFFにして保存してください。", "error");
          return;
        }
        if (!cfg.enabled){
          _maintenanceSetAdminStatus("enabled は既に false です。");
          return;
        }
        if ((Number(cfg.endAt) || 0) > Date.now()){
          _maintenanceSetAdminStatus("まだ期間中です。終了後に実行してください。", "error");
          return;
        }
        _maintenanceState.saving = true;
        _maintenanceSetAdminBusy(true);
        _maintenanceSetAdminStatus("無効化中…");
        showLoading("メンテナンスを無効化中…");
        try{
          const maintenance = await _maintenanceSaveConfigToServer({
            enabled: false
          });
          _maintenanceState.config = _maintenanceNormalizeConfig({
            ...cfg,
            ...maintenance,
            enabled: false
          });
          _maintenanceState.bypass = false;
          _maintenanceSetAdminStatus("enabled を false に更新しました。", "ok");
          uiToast("メンテナンスを無効化しました");
          _maintenanceRenderAdminForm();
          _maintenanceRenderOverlay();
        }catch(err){
          const code = String(err?.code || "ERROR");
          const msg = String(err?.message || err);
          if (code === "FORBIDDEN" && /管理者権限/.test(msg)) {
            _maintenanceSetAdminStatus("無効化失敗: 管理者としてログインしてから再度お試しください。", "error");
          } else {
            _maintenanceSetAdminStatus(`無効化失敗: ${code} / ${msg}`, "error");
          }
        }finally{
          _maintenanceState.saving = false;
          _maintenanceSetAdminBusy(false);
          hideLoading();
        }
      }
      async function _adminStartLoginFlow(loginBtn, statusFn){
        const setStatus = (typeof statusFn === "function") ? statusFn : _adminSetStatus;
        _adminEnsureAuthWatcher();
        const env = _adminCheckAuthEnvironment();
        if (!env.ok){
          setStatus(env.reason, "error");
          return false;
        }
        let auth;
        try{
          auth = _adminGetAuth();
        }catch(err){
          setStatus(`Firebase初期化エラー: ${String(err?.message || err)}`, "error");
          return false;
        }
        try{
          if (loginBtn) loginBtn.disabled = true;
          setStatus("Googleログインを開始しています…");
          const provider = new window.firebase.auth.GoogleAuthProvider();
          const result = await auth.signInWithPopup(provider);
          const user = (result && result.user) ? result.user : auth.currentUser;
          _adminState.user = user || null;
          _adminState.isAdmin = await _adminRefreshPrivilege(user, { silent: false });
          if (_adminState.isAdmin){
            setStatus("Adminログインしました。", "ok");
            _maintenanceSetOverlayStatus("管理者ログインを確認しました。", "ok");
            return true;
          }
          const signedEmail = String(user?.email || "").trim();
          setStatus(`管理者権限がありません: ${signedEmail || "メール不明"}`, "error");
          _maintenanceSetOverlayStatus("管理者アカウントでログインしてください。", "error");
          return false;
        }catch(err){
          const code = String(err?.code || "AUTH_ERROR");
          const msg = String(err?.message || "");
          const fallbackCodes = new Set([
            "auth/popup-blocked",
            "auth/web-storage-unsupported",
            "auth/operation-not-supported-in-this-environment"
          ]);
          if (fallbackCodes.has(code) && typeof auth.signInWithRedirect === "function"){
            try{
              setStatus(`ポップアップ不可のためリダイレクトで再試行します… (${code})`);
              const provider = new window.firebase.auth.GoogleAuthProvider();
              await auth.signInWithRedirect(provider);
              return true;
            }catch(err2){
              const code2 = String(err2?.code || "AUTH_ERROR");
              const msg2 = String(err2?.message || "");
              setStatus(`ログイン失敗: ${code2} / ${msg2}`, "error");
              return false;
            }
          }
          setStatus(`ログイン失敗: ${code} / ${msg}`, "error");
          return false;
        }finally{
          if (loginBtn) loginBtn.disabled = false;
          _adminRenderUI();
          _maintenanceRenderOverlay();
        }
      }
      function _adminGetDb(){
        if (_adminState.db) return _adminState.db;
        _adminState.db = _drawerShareGetDb();
        return _adminState.db;
      }
      function _adminGetAuth(){
        if (_adminState.auth) return _adminState.auth;
        if (!window.firebase || typeof window.firebase.auth !== "function"){
          throw new Error("Firebase Auth SDK が読み込まれていません。");
        }
        _adminGetDb(); // app初期化を保証
        _adminState.auth = window.firebase.auth();
        return _adminState.auth;
      }
      function _adminCheckAuthEnvironment(){
        const proto = String(location.protocol || "");
        if (!/^https?:$/.test(proto) && proto !== "chrome-extension:"){
          return {
            ok: false,
            reason: `この環境ではGoogleログインできません（protocol=${proto || "unknown"}）。httpsで開いてください。`
          };
        }
        try{
          const k = "__admin_auth_probe__";
          window.localStorage.setItem(k, "1");
          window.localStorage.removeItem(k);
        }catch{
          return {
            ok: false,
            reason: "ブラウザのWeb Storageが無効です。Cookie/サイトデータを有効にしてください。"
          };
        }
        return { ok: true, reason: "" };
      }
      async function _adminHandleRedirectResult(){
        let auth;
        try{
          auth = _adminGetAuth();
        }catch{
          return;
        }
        if (!auth || typeof auth.getRedirectResult !== "function") return;
        try{
          const result = await auth.getRedirectResult();
          if (result && result.user){
            _adminState.user = result.user;
            _adminState.isAdmin = await _adminRefreshPrivilege(result.user, { silent: false });
            if (_adminState.isAdmin){
              _adminSetStatus("Googleログインが完了しました。", "ok");
              _maintenanceSetOverlayStatus("管理者ログインを確認しました。", "ok");
            }else{
              const signedEmail = String(result.user?.email || "").trim();
              _adminSetStatus(`管理者権限がありません: ${signedEmail || "メール不明"}`, "error");
              _maintenanceSetOverlayStatus("管理者アカウントでログインしてください。", "error");
            }
            _adminRenderUI();
          }
        }catch(err){
          const code = String(err?.code || "AUTH_ERROR");
          const msg = String(err?.message || "");
          _adminSetStatus(`ログイン失敗: ${code} / ${msg}`, "error");
        }
      }
