          _appSaveSubscriptionNotifyMap(next);
          _appRenderSubscription();
          if (_appIsLoggedUser()){
            _appApiJson("/api/subscription/notify", {
              method: "POST",
              body: JSON.stringify({
                planId,
                notifyInApp: true,
                notifyWebPush: String(Notification?.permission || "") === "granted",
                installed: _appPushIsStandalone(),
                permission: String(Notification?.permission || "default"),
                platform: _appPushIsStandalone() ? "standalone" : "browser",
                source: "subscription_page"
              })
            }).catch((err) => {
              console.warn("[subscription.notify] save failed:", String(err?.message || err));
            });
          }
          _appPushBootstrap("subscription.notify").catch(() => {});
          uiAlert(`${name} の開始通知を予約しました。\n公開時にはアプリ内通知でお知らせします。\niPhoneでSafariからホーム画面に追加し、通知を許可している場合は Web プッシュ通知でも受け取れます。`, { title: "Subscription" });
          return;
