        const base = _appDefaultQodState();
        let stored = {};
        try{
          const raw = localStorage.getItem(key);
          if (raw) stored = JSON.parse(raw) || {};
        }catch{}
        const confirmChecks = (stored.confirmChecks && typeof stored.confirmChecks === "object") ? stored.confirmChecks : {};
        const form = (stored.qodFormData && typeof stored.qodFormData === "object") ? stored.qodFormData : {};
