      function _appQreditCardDisposeViewer(){
        const rt = _appQreditCardViewerRuntime;
        if (!rt) return;
        _appQreditCardViewerRuntime = null;
        try{ cancelAnimationFrame(rt.rafId || 0); }catch{}
        try{ rt.resizeObserver?.disconnect?.(); }catch{}
        try{ rt.frontTexture?.dispose?.(); }catch{}
        try{ rt.backTexture?.dispose?.(); }catch{}
        try{ rt.frontSheenTexture?.dispose?.(); }catch{}
        try{ rt.backSheenTexture?.dispose?.(); }catch{}
        try{ rt.frontMaterial?.dispose?.(); }catch{}
        try{ rt.backMaterial?.dispose?.(); }catch{}
        try{ rt.frontSheenMaterial?.dispose?.(); }catch{}
        try{ rt.backSheenMaterial?.dispose?.(); }catch{}
        try{ rt.sideMaterial?.dispose?.(); }catch{}
        try{ rt.hiddenMaterial?.dispose?.(); }catch{}
        try{ rt.frontGeometry?.dispose?.(); }catch{}
        try{ rt.sheenGeometry?.dispose?.(); }catch{}
        try{ rt.bodyGeometry?.dispose?.(); }catch{}
        try{ rt.renderer?.dispose?.(); }catch{}
        try{
          if (rt.renderer?.domElement?.parentNode){
            rt.renderer.domElement.parentNode.removeChild(rt.renderer.domElement);
          }
        }catch{}
      }
      function _appQreditCardNormalizeAngle(value){
        let angle = Number(value || 0);
        if (!Number.isFinite(angle)) return 0;
        angle %= 360;
        if (angle > 180) angle -= 360;
        if (angle < -180) angle += 360;
        return angle;
      }
      function _appQreditCardRoundRectPath(ctx, x, y, width, height, radius){
        const r = Math.max(0, Math.min(Number(radius || 0), width / 2, height / 2));
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + width - r, y);
        ctx.quadraticCurveTo(x + width, y, x + width, y + r);
        ctx.lineTo(x + width, y + height - r);
        ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
        ctx.lineTo(x + r, y + height);
        ctx.quadraticCurveTo(x, y + height, x, y + height - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
      }
      function _appQreditCardCanvasText(ctx, text, x, y, {
        font = '600 20px "SF Pro Display","Inter","Hiragino Sans","Noto Sans JP",sans-serif',
        fill = "#0f172a",
        align = "left",
        baseline = "alphabetic",
        letterSpacing = 0,
        maxWidth = 0
      } = {}){
        const raw = String(text ?? "");
        ctx.save();
        ctx.font = font;
        ctx.fillStyle = fill;
        ctx.textAlign = align;
        ctx.textBaseline = baseline;
        if (!raw){
          ctx.restore();
          return;
        }
        if (!letterSpacing && !maxWidth){
          ctx.fillText(raw, x, y);
          ctx.restore();
          return;
        }
        let content = raw;
        if (maxWidth > 0 && ctx.measureText(content).width > maxWidth){
          while (content.length > 1 && ctx.measureText(`${content}…`).width > maxWidth){
            content = content.slice(0, -1);
          }
          content = `${content}…`;
        }
        const chars = Array.from(content);
        let cursor = x;
        if (align === "center" || align === "right"){
          const width = chars.reduce((sum, char, index) => sum + ctx.measureText(char).width + (index ? letterSpacing : 0), 0);
          if (align === "center") cursor = x - (width / 2);
          if (align === "right") cursor = x - width;
        }
        chars.forEach((char, index) => {
          if (index) cursor += letterSpacing;
          ctx.fillText(char, cursor, y);
          cursor += ctx.measureText(char).width;
        });
        ctx.restore();
      }
