      function _appQreditCardSurfaceHtml({
        cardId,
        displayName,
        balance,
        rank = "Basic",
        themeId = APP_QREDIT_CARD_THEME_DEFAULT,
        registrationNumber = "",
        expiresAt = 0,
        secureCode = "",
        stageMode = "idle",
        helper = "",
        visualStyle = ""
      } = {}){
        const stageClass = stageMode === "interactive" ? " app-qredit-card-stage--interactive" : "";
        const visualClass = stageMode === "interactive"
          ? "app-qredit-card-visual app-qredit-card-visual--interactive"
          : "app-qredit-card-visual is-idle";
        const cardThemeId = _appQreditCardThemeId(themeId);
        const faceMode = "front";
        const cardMode = stageMode === "interactive" ? _appQreditCardPreviewMode() : "front";
        const effectiveVisualStyle = `${visualStyle || ""} ${_appQreditCardThemeStyle(cardThemeId)}`.trim();
        return `
          <div class="app-qredit-card-stage${stageClass}" id="appQreditCardStage">
            <div class="${visualClass}" id="appQreditCardVisual" data-card-theme="${_escapeHtml(cardThemeId)}" data-card-face="${_escapeHtml(faceMode)}" data-card-mode="${_escapeHtml(cardMode)}" data-stage-mode="${_escapeHtml(stageMode)}" data-card-id="${_escapeHtml(cardId)}" data-display-name="${_escapeHtml(displayName)}" data-card-balance="${_escapeHtml(String(Math.max(0, Number(balance || 0) || 0)))}" data-card-rank="${_escapeHtml(rank)}" data-card-registration-number="${_escapeHtml(registrationNumber)}" data-card-expires-at="${_escapeHtml(String(Math.max(0, Number(expiresAt || 0) || 0)))}" data-card-secure-code="${_escapeHtml(secureCode)}"${effectiveVisualStyle ? ` style="${_escapeHtml(effectiveVisualStyle)}"` : ""}>
              <div class="app-qredit-card-render-shell">
                <div class="app-qredit-card-renderer" id="appQreditCardRenderer" role="img" aria-label="Qredit Card の3D表示"></div>
                <div class="app-qredit-card-render-status" id="appQreditCardRenderStatus">3Dカードを読み込んでいます…</div>
              </div>
              <div class="app-qredit-card-shadow" aria-hidden="true"></div>
            </div>
            ${helper ? `<div class="app-qredit-card-stage-helper">${helper}</div>` : ""}
          </div>
        `;
      }
