              meta.className = "app-feed-side-notification-meta";
              meta.textContent = `${String(item?.category || "更新")} / ${_appInboxRelativeTime(Number(item?.ts || 0))}`;
              row.appendChild(title);
              row.appendChild(meta);
              frag.appendChild(row);
