      function _chatMessageId(prefix = "m"){
        return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      }
      function _chatEnsureConversationId(){
        if (_chatState.conversationId) return _chatState.conversationId;
        try{
          const saved = String(window.localStorage.getItem(CHAT_CONVERSATION_ID_KEY) || "").trim();
          if (saved){
            _chatState.conversationId = saved;
            return saved;
          }
        }catch{}
        const next = _chatMessageId("conv");
        _chatState.conversationId = next;
        try{ window.localStorage.setItem(CHAT_CONVERSATION_ID_KEY, next); }catch{}
        return next;
      }
      function _chatDebugPresetFlow(event, payload = {}){
        try{
          console.debug("[AI preset flow]", {
            event: String(event || "").trim() || "event",
            ...((payload && typeof payload === "object") ? payload : { detail: payload })
          });
        }catch{}
      }
      function _chatResetPresetFlowState(opts = {}){
        _chatState.presetFlow = {
          active: false,
          conversationId: _chatEnsureConversationId(),
          messageId: "",
          intent: null,
          attachments: [],
          confirmPayload: null,
          selectedSourceFile: null,
          extractedSubject: ""
        };
        _chatState.expandedProcessLogIds.delete("__preset_live__");
        if (!opts.keepProcessPanel){
          _chatClearProcessPanel();
        }
      }
      function _chatSetPresetFlowState(next = {}){
        const current = (_chatState.presetFlow && typeof _chatState.presetFlow === "object") ? _chatState.presetFlow : {};
        _chatState.presetFlow = {
          active: !!next.active,
          conversationId: String(next.conversationId || current.conversationId || _chatEnsureConversationId()).trim(),
          messageId: String(next.messageId || current.messageId || "").trim(),
          intent: next.intent || null,
          attachments: _chatCloneAttachmentMetaList(next.attachments || current.attachments || []),
          confirmPayload: (next.confirmPayload && typeof next.confirmPayload === "object") ? { ...next.confirmPayload } : null,
          selectedSourceFile: (next.selectedSourceFile && typeof next.selectedSourceFile === "object") ? { ...next.selectedSourceFile } : null,
          extractedSubject: String(next.extractedSubject || current.extractedSubject || "").trim()
        };
      }
      function _chatMarkPendingAttachmentsCarried(meta = {}){
        _chatState.pendingAttachmentCarry = {
          conversationId: String(meta.conversationId || _chatEnsureConversationId()).trim(),
          messageId: String(meta.messageId || "").trim(),
          flow: String(meta.flow || "").trim(),
          carriedAt: Date.now()
        };
      }
      function _chatClearPendingAttachments(reason = ""){
        _chatState.pendingAttachments = [];
        _chatState.pendingAttachmentCarry = null;
        if (reason){
          _chatDebugPresetFlow("clear_pending_attachments", { reason, conversationId: _chatEnsureConversationId() });
        }
        _chatRenderPendingAttachments();
      }
      function _chatIsSourceExpanded(id){
        return _chatState.expandedSourceIds.has(String(id || "").trim());
      }
      function _chatToggleSourceExpanded(id){
        const key = String(id || "").trim();
        if (!key) return false;
        if (_chatState.expandedSourceIds.has(key)) {
          _chatState.expandedSourceIds.delete(key);
          return false;
        }
        _chatState.expandedSourceIds.add(key);
        return true;
      }
      function _chatIsProcessLogExpanded(id){
        return _chatState.expandedProcessLogIds.has(String(id || "").trim());
      }
      function _chatToggleProcessLogExpanded(id){
        const key = String(id || "").trim();
        if (!key) return false;
        if (_chatState.expandedProcessLogIds.has(key)) {
          _chatState.expandedProcessLogIds.delete(key);
          return false;
        }
        _chatState.expandedProcessLogIds.add(key);
        return true;
      }
      function _chatFmtBytes(bytes){
        const value = Math.max(0, Number(bytes || 0));
        if (!Number.isFinite(value) || value <= 0) return "";
        if (value >= 1024 * 1024) return `${(value / (1024 * 1024)).toFixed(value >= 10 * 1024 * 1024 ? 0 : 1)}MB`;
        if (value >= 1024) return `${Math.round(value / 1024)}KB`;
        return `${Math.round(value)}B`;
      }
      function _chatSourceTypeFromMime(mimeRaw){
        const mime = String(mimeRaw || "").trim().toLowerCase();
        if (mime === "pdf") return "pdf";
        if (mime === "image") return "image";
        if (mime === "application/pdf") return "pdf";
        if (/^image\//.test(mime)) return "image";
        return "";
      }
      function _chatAttachmentLabelFromType(typeRaw){
        const type = String(typeRaw || "").trim().toLowerCase();
        if (type === "pdf") return "PDF";
        if (type === "image") return "画像";
        return "添付";
      }
      function _chatSanitizeAttachmentMeta(raw){
        const src = (raw && typeof raw === "object") ? raw : {};
        const name = String(src.name || "").trim().slice(0, 180);
        const mimeType = String(src.mimeType || src.mime || "").trim().toLowerCase().slice(0, 120);
        const sourceType = _chatSourceTypeFromMime(src.sourceType || mimeType);
        const size = Math.max(0, Number(src.size || 0));
        const preview = String(src.preview || "").trim();
        if (!name || !sourceType) return null;
        return {
          id: String(src.id || _chatMessageId("att")).trim().slice(0, 80) || _chatMessageId("att"),
          name,
          mimeType: mimeType || (sourceType === "pdf" ? "application/pdf" : "image/jpeg"),
          sourceType,
          size,
          preview: preview.slice(0, 400000),
          pageCount: Math.max(0, Number(src.pageCount || 0)) || 0
        };
      }
      function _chatCloneAttachmentMetaList(list){
        return (Array.isArray(list) ? list : []).map(_chatSanitizeAttachmentMeta).filter(Boolean).slice(0, 8);
      }
      function _chatSanitizeProcessLogEntry(raw){
        const src = (raw && typeof raw === "object") ? raw : {};
        const message = String(src.message || src.text || "").trim().slice(0, 220);
        const code = String(src.code || src.codeText || "").trim().slice(0, 4000);
        const statusRaw = String(src.status || "").trim().toLowerCase();
        const status = (statusRaw === "done" || statusRaw === "active" || statusRaw === "error") ? statusRaw : "done";
        if (!message && !code) return null;
        return { message, code, status };
      }
      function _chatSanitizeProcessLog(list){
        return (Array.isArray(list) ? list : []).map(_chatSanitizeProcessLogEntry).filter(Boolean).slice(0, CHAT_PRESET_PROCESS_LOG_MAX);
      }
