      function _chatSanitizePresetCard(raw){
        const src = (raw && typeof raw === "object") ? raw : {};
        const id = String(src.id || "").trim().slice(0, 120);
        const title = String(src.title || src.name || "").trim().slice(0, 140);
        const subjectId = String(src.subjectId || "").trim().slice(0, 80);
        const difficulty = String(src.difficulty || "").trim().slice(0, 40);
        const status = String(src.status || "").trim().slice(0, 40);
        const actions = Array.isArray(src.actions) ? src.actions.map(_chatSanitizeAction).filter(Boolean).slice(0, 4) : [];
        const questionCount = Math.max(0, Number(src.questionCount || src.wordCount || 0));
        const tagIds = Array.isArray(src.tagIds) ? src.tagIds.map((x) => String(x || "").trim()).filter(Boolean).slice(0, 8) : [];
        if (!id || !title) return null;
        return { id, title, subjectId, difficulty, status, questionCount, tagIds, actions };
      }
      async function _chatReadFileAsArrayBuffer(file){
        if (!file || typeof file.arrayBuffer !== "function"){
          throw new Error("FILE_READ_UNSUPPORTED");
        }
        return file.arrayBuffer();
      }
      async function _chatReadFileAsDataUrl(file){
        return new Promise((resolve, reject) => {
          if (!file){
            reject(new Error("FILE_REQUIRED"));
            return;
          }
          const reader = new FileReader();
          reader.onerror = () => reject(new Error("FILE_READ_FAILED"));
          reader.onload = () => resolve(String(reader.result || ""));
          try{
            reader.readAsDataURL(file);
          }catch(err){
            reject(err);
          }
        });
      }
      let _chatPdfjsLoadPromise = null;
      async function _chatGetPdfjs(){
        if (_chatPdfjsLoadPromise) return _chatPdfjsLoadPromise;
        _chatPdfjsLoadPromise = import(CHAT_PDFJS_MODULE_URL).then((mod) => {
          const pdfjs = mod?.default && typeof mod.default === "object" ? mod.default : mod;
          if (!pdfjs || typeof pdfjs.getDocument !== "function"){
            throw new Error("PDFJS_LOAD_FAILED");
          }
          if (pdfjs.GlobalWorkerOptions){
            pdfjs.GlobalWorkerOptions.workerSrc = CHAT_PDFJS_WORKER_URL;
          }
          return pdfjs;
        }).catch((err) => {
          _chatPdfjsLoadPromise = null;
          throw err;
        });
        return _chatPdfjsLoadPromise;
      }
      async function _chatBuildImagePreview(file){
        if (!file || !/^image\//i.test(String(file.type || ""))) return "";
        let decoder = null;
        try{
          decoder = await _scanDecodeImage(file);
          const srcW = Math.max(1, Number(decoder.width || 1));
          const srcH = Math.max(1, Number(decoder.height || 1));
          const maxDim = 220;
          const scale = Math.min(1, maxDim / Math.max(srcW, srcH));
          const w = Math.max(1, Math.round(srcW * scale));
          const h = Math.max(1, Math.round(srcH * scale));
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext("2d", { alpha: false });
          if (!ctx) return "";
          decoder.draw(ctx, w, h);
          const dataUrl = canvas.toDataURL("image/jpeg", 0.76);
          return String(dataUrl || "").slice(0, 280000);
        }catch{
          try{
            return String(await _chatReadFileAsDataUrl(file) || "").slice(0, 280000);
          }catch{
            return "";
          }
        }finally{
          try{ decoder?.close?.(); }catch{}
        }
      }
      async function _chatInspectPdfFile(file){
        const pdfjs = await _chatGetPdfjs();
        const arrayBuffer = await _chatReadFileAsArrayBuffer(file);
        const pdf = await pdfjs.getDocument({ data: arrayBuffer }).promise;
        try{
          return { pageCount: Math.max(0, Number(pdf?.numPages || 0)) || 0 };
        } finally {
          try{ pdf?.destroy?.(); }catch{}
        }
      }
      async function _chatBuildPendingAttachment(file){
        const sourceType = _chatSourceTypeFromMime(file?.type || "");
        if (!sourceType){
          const err = new Error("ATTACHMENT_UNSUPPORTED_TYPE");
          err.code = "ATTACHMENT_UNSUPPORTED_TYPE";
          throw err;
        }
        const base = {
          id: _chatMessageId("att"),
          name: String(file?.name || sourceType || "file").slice(0, 180),
          mimeType: String(file?.type || "").trim().toLowerCase(),
          sourceType,
          size: Math.max(0, Number(file?.size || 0)),
          preview: "",
          pageCount: 0,
          file
        };
        if (sourceType === "image"){
          base.preview = await _chatBuildImagePreview(file);
        } else if (sourceType === "pdf"){
          const inspected = await _chatInspectPdfFile(file);
          base.pageCount = Math.max(0, Number(inspected?.pageCount || 0)) || 0;
        }
        return base;
      }
      function _chatCloneRuntimeAttachments(list){
        return (Array.isArray(list) ? list : [])
          .map((item) => {
            const meta = _chatSanitizeAttachmentMeta(item);
            const file = item?.file instanceof File ? item.file : null;
            if (!meta || !file) return null;
            return {
              ...meta,
              file
            };
          })
          .filter(Boolean)
          .slice(0, CHAT_FILE_MAX_ATTACHMENTS);
      }
      function _chatPendingAttachmentErrorForList(list){
        const items = Array.isArray(list) ? list : [];
        if (items.length > CHAT_FILE_MAX_ATTACHMENTS){
          return `添付は最大 ${CHAT_FILE_MAX_ATTACHMENTS} 件までです。`;
        }
        const pdfs = items.filter((item) => item?.sourceType === "pdf");
        for (const pdf of pdfs){
          const size = Math.max(0, Number(pdf?.size || 0));
          if (size > CHAT_FILE_MAX_PDF_BYTES){
            return `PDF は最大 ${Math.round(CHAT_FILE_MAX_PDF_BYTES / (1024 * 1024))}MB までです。`;
          }
          const pageCount = Math.max(0, Number(pdf?.pageCount || 0));
          if (pageCount > CHAT_FILE_MAX_PDF_PAGES){
            return `PDF は最大 ${CHAT_FILE_MAX_PDF_PAGES} ページまでです。`;
          }
        }
        const images = items.filter((item) => item?.sourceType === "image");
        if (images.length > CHAT_FILE_MAX_IMAGES){
          return `画像は最大 ${CHAT_FILE_MAX_IMAGES} 枚までです。`;
        }
        const imageBytes = images.reduce((sum, item) => sum + Math.max(0, Number(item?.size || 0)), 0);
        if (imageBytes > CHAT_FILE_MAX_IMAGE_TOTAL_BYTES){
          return `画像の合計容量は最大 ${Math.round(CHAT_FILE_MAX_IMAGE_TOTAL_BYTES / (1024 * 1024))}MB までです。`;
        }
        return "";
      }
      function _chatAttachmentSubtitle(meta){
        const parts = [_chatAttachmentLabelFromType(meta?.sourceType || "")];
        if (Number(meta?.pageCount || 0) > 0){
          parts.push(`${Math.max(0, Number(meta.pageCount || 0))}p`);
        }
        const sizeText = _chatFmtBytes(meta?.size || 0);
        if (sizeText) parts.push(sizeText);
        return parts.join(" ・ ");
      }
      function _chatBuildAttachmentNode(raw, opts = {}){
        const meta = _chatSanitizeAttachmentMeta(raw);
        if (!meta) return null;
        const article = document.createElement("article");
        article.className = `app-chat-attachment ${opts.compact ? "is-compact" : ""}`.trim();
        article.setAttribute("data-chat-attachment-id", meta.id);
        const media = document.createElement("div");
        media.className = "app-chat-attachment-media";
        if (meta.sourceType === "image" && String(meta.preview || "").startsWith("data:image/")){
          const img = document.createElement("img");
          img.src = meta.preview;
          img.alt = meta.name;
          media.appendChild(img);
        } else {
          const icon = document.createElement("span");
          icon.className = "ms";
          icon.setAttribute("aria-hidden", "true");
          icon.textContent = meta.sourceType === "pdf" ? "picture_as_pdf" : "image";
          media.appendChild(icon);
        }
        const body = document.createElement("div");
        body.className = "app-chat-attachment-body";
        const title = document.createElement("strong");
        title.textContent = meta.name;
        const sub = document.createElement("span");
        sub.textContent = _chatAttachmentSubtitle(meta);
        body.appendChild(title);
        body.appendChild(sub);
        article.appendChild(media);
        article.appendChild(body);
        if (opts.removable){
          const removeBtn = document.createElement("button");
          removeBtn.type = "button";
          removeBtn.className = "app-chat-attachment-remove";
          removeBtn.setAttribute("data-chat-action", "removePendingAttachment");
          removeBtn.setAttribute("data-chat-prompt", meta.id);
          removeBtn.setAttribute("aria-label", `${meta.name} を添付一覧から外す`);
          removeBtn.innerHTML = '<span class="ms" aria-hidden="true">close</span>';
          article.appendChild(removeBtn);
        }
        return article;
      }
      function _chatRenderPendingAttachments(){
        const host = el.appChatPendingAttachments;
        if (!host) return;
        host.replaceChildren();
        const list = _chatCloneRuntimeAttachments(_chatState.pendingAttachments);
        if (!list.length){
          host.classList.add("hidden");
          return;
        }
        host.classList.remove("hidden");
        const label = document.createElement("div");
        label.className = "app-chat-pending-label";
        label.textContent = "添付中";
        host.appendChild(label);
        const wrap = document.createElement("div");
        wrap.className = "app-chat-attachment-list is-pending";
        for (const item of list){
          const node = _chatBuildAttachmentNode(item, { removable: true });
          if (node) wrap.appendChild(node);
        }
        host.appendChild(wrap);
      }
      function _chatFmtElapsed(ms){
        const value = Math.max(0, Number(ms || 0));
        return `${(value / 1000).toFixed(1)}秒`;
      }
      function _chatFriendlyGenerationError(message){
        const text = String(message || "").trim();
        if (!text) return "下書き生成を最後まで完了できませんでした。ページ範囲を絞るか、画像/PDF を見やすくして再試行してください。";
        return text;
      }
      function _chatUniquePresetName(baseName){
        const base = String(baseName || "AI 下書きプリセット").trim() || "AI 下書きプリセット";
        const existing = new Set(loadPresets().map((row) => String(row?.name || "").trim()).filter(Boolean));
        if (!existing.has(base)) return base;
        let idx = 2;
        while (existing.has(`${base} (${idx})`)) idx += 1;
        return `${base} (${idx})`;
      }
      function _chatLocalPresetFromDraft(rawDraft){
        const src = (rawDraft && typeof rawDraft === "object") ? rawDraft : {};
        const base = {
          id: newId(),
          builtin: false,
          name: _chatUniquePresetName(String(src.name || src.title || "AI 下書きプリセット")),
          subjectId: _resolveSubjectId(src.subjectId, { fallback: "sub:other", allowMissingCustom: false }),
          tagIds: _normalizeTagIds(src.tagIds, { allowUnknown: false }),
          words: _normalizeWordList(src.words),
          modes: (src.modes && typeof src.modes === "object") ? {
            SEQ: src.modes.SEQ !== false,
            RND: src.modes.RND !== false,
            HAND: src.modes.HAND !== false,
            CHOICE: src.modes.CHOICE !== false
          } : { SEQ: true, RND: true, HAND: false, CHOICE: true },
          difficulty: String(src.difficulty || "normal").trim().toLowerCase() || "normal",
          draft: true,
          visibility: "draft",
          createdVia: "professor_file_flow",
          sourceType: String(src.sourceType || "").trim().toLowerCase(),
          sourceName: String(src.sourceName || "").trim().slice(0, 180),
          questionCount: Math.max(0, Number(src.questionCount || 0)) || (Array.isArray(src.words) ? src.words.length : 0)
        };
        return _normalizePresetMeta(base, { allowUnknownTagIds: false, allowMissingCustomSubject: false });
      }
      function _chatBuildPresetCard(preset){
        const item = (preset && typeof preset === "object") ? preset : null;
        const id = String(item?.id || "").trim();
        if (!id) return null;
        return {
          id,
          title: String(item?.name || "AI 下書きプリセット").trim().slice(0, 140),
          subjectId: _resolveSubjectId(item?.subjectId, { fallback: "sub:other", allowMissingCustom: true }),
          difficulty: String(item?.difficulty || "normal").trim().slice(0, 40) || "normal",
          status: "下書き保存済み",
          questionCount: Math.max(0, Number(item?.questionCount || _presetEntryCount(item) || 0)),
          tagIds: _normalizeTagIds(item?.tagIds, { allowUnknown: true }),
          actions: [
            { type: "openPresetDraft", label: "開く", prompt: id },
            { type: "editPresetDraft", label: "編集する", prompt: id },
            { type: "viewPresetDraft", label: "下書きを確認", prompt: id }
          ]
        };
      }
      function _chatSavePresetDraftFromFlow(rawDraft){
        const preset = _chatLocalPresetFromDraft(rawDraft);
        const list = loadPresets();
        list.unshift(preset);
        savePresets(list);
        try{ refreshPresetList(); }catch{}
        return preset;
      }
      /* ══ VQ Preset Generator — Professor gate ══ */
      function _vqShowProfessorGate(){
        var existing = document.querySelector(".vq-pg-professor-gate");
        if (existing) existing.remove();
        var scroll = document.querySelector("#appAiChatShell .app-chat-scroll");
        if (!scroll) return;
        var gate = document.createElement("div");
        gate.className = "vq-pg-professor-gate";
        gate.innerHTML =
          '<div class="vq-pg-professor-gate-icon"><span class="ms" aria-hidden="true">school</span></div>' +
          '<div class="vq-pg-professor-gate-copy"><strong>Professorモードが必要です</strong><br>ファイルからプリセットを自動作成するには、Professorモードに切り替えてください。</div>' +
          '<button class="vq-pg-professor-gate-btn" type="button">切り替える</button>';
        var dock = document.getElementById("appChatBottomDock");
        if (dock) dock.parentNode.insertBefore(gate, dock);
        else scroll.appendChild(gate);
        gate.querySelector(".vq-pg-professor-gate-btn")?.addEventListener("click", function(){
          if (typeof _chatSetAiMode === "function") _chatSetAiMode("professor");
          if (typeof _chatRenderModelUi === "function") _chatRenderModelUi();
          gate.remove();
          uiToast("Professorモードに切り替えました。もう一度ファイルを選択してください。");
        });
        setTimeout(function(){ gate.scrollIntoView({ behavior:"smooth", block:"end" }); }, 100);
      }

      /* ══ VQ Preset Generator — inline question editor ══ */
      function _vqPgMakeEditable(qEl, idx){
        if (!qEl || qEl.querySelector(".vq-pg-edit")) return;
        var qText = qEl.querySelector(".vq-pg-q-text")?.textContent || "";
        var choices = qEl.querySelectorAll(".vq-pg-q-choice");
        var edit = document.createElement("div");
        edit.className = "vq-pg-edit";
        var html = '<div class="vq-pg-edit-label">Q' + (idx+1) + ' を編集中</div>' +
          '<input class="vq-pg-edit-input" data-vq-field="question" value="' + _escHtml(qText) + '" placeholder="問題文" />' +
          '<input class="vq-pg-edit-input" data-vq-field="answer" value="" placeholder="答え" />';
        if (choices.length){
          html += '<div class="vq-pg-edit-choices">';
          for (var ci = 0; ci < choices.length; ci++){
            var cText = choices[ci].textContent.replace(/^[A-F]\)\s*/, "").trim();
            var isCorrect = choices[ci].classList.contains("is-correct");
            html += '<div class="vq-pg-edit-choice">' +
              '<input type="radio" name="vq-pg-correct-' + idx + '" value="' + ci + '"' + (isCorrect ? ' checked' : '') + ' />' +
              '<input class="vq-pg-edit-input" data-vq-choice="' + ci + '" value="' + _escHtml(cText) + '" />' +
              '</div>';
          }
          html += '</div>';
        }
        html += '<div class="vq-pg-edit-actions">' +
          '<button class="vq-pg-card-action is-primary" type="button" data-chat-action="vqPgSaveQuestion"><span class="ms">check</span>保存</button>' +
          '<button class="vq-pg-card-action is-secondary" type="button" data-chat-action="vqPgCancelEdit"><span class="ms">close</span>キャンセル</button>' +
          '<button class="vq-pg-card-action is-secondary" type="button" data-chat-action="vqPgDeleteQuestion" style="margin-left:auto;color:#ef4444;"><span class="ms">delete</span>削除</button>' +
          '</div>';
        edit.innerHTML = html;
        qEl.appendChild(edit);
        edit.querySelector("input")?.focus();
      }

      async function _chatAddPendingFiles(fileList){
        const picked = Array.from(fileList || []).filter((file) => file instanceof File);
        if (!picked.length) return;
        /* ── Professor mode gate ── */
        if (_chatState.aiMode !== "professor"){
          _vqShowProfessorGate();
          return;
        }
        let next = _chatCloneRuntimeAttachments(_chatState.pendingAttachments);
        if (_chatState.pendingAttachmentCarry && next.length){
          _chatDebugPresetFlow("replace_carried_attachments", {
            conversationId: _chatEnsureConversationId(),
            carriedFromMessageId: String(_chatState.pendingAttachmentCarry?.messageId || "").trim(),
            replacingWithCount: picked.length
          });
          next = [];
          _chatState.pendingAttachmentCarry = null;
          _chatResetPresetFlowState({ keepProcessPanel: false });
        }
        for (const file of picked){
          try{
            const built = await _chatBuildPendingAttachment(file);
            next.push(built);
            const errText = _chatPendingAttachmentErrorForList(next);
            if (errText){
              next.pop();
              uiToast(errText);
            }
          }catch(err){
            uiToast(String(err?.message || "添付の読み取りに失敗しました。"));
          }
        }
        _chatState.pendingAttachments = next.slice(0, CHAT_FILE_MAX_ATTACHMENTS);
        _chatRenderPendingAttachments();
      }
      function _chatRemovePendingAttachmentById(id){
        const key = String(id || "").trim();
        if (!key) return;
        _chatState.pendingAttachments = _chatCloneRuntimeAttachments(_chatState.pendingAttachments)
          .filter((item) => String(item?.id || "").trim() !== key);
        if (!_chatState.pendingAttachments.length){
          _chatState.pendingAttachmentCarry = null;
        }
        _chatRenderPendingAttachments();
      }
      function _chatMaybePresetFileIntent(text, attachments){
        const body = String(text || "").trim().toLowerCase();
        const hasAttachments = Array.isArray(attachments) && attachments.length > 0;
        if (!body) {
          return { clear: false, ambiguous: false, requiresAttachment: false, route: "none", createTokens: [], fileTokens: [], vagueTokens: [] };
        }
        const createTokens = [
          "プリセットを作って",
          "下書きを作って",
          "プリセットを作成して",
          "下書きを作成して",
          "問題にして",
          "クイズ化して",
          "問題集にして",
          "作って",
          "作成して",
          "作成",
          "生成して",
          "生成",
          "下書き化して"
        ].filter((token) => body.includes(token));
        const vagueTokens = [
          "見て",
          "お願い",
          "いける",
          "使える",
          "読める",
          "できる"
        ].filter((token) => body.includes(token));
        const fileTokens = [
          "このpdf",
          "この画像",
          "このプリント",
          "このファイル",
          "pdf",
          "画像",
          "プリント",
          "ファイル",
          "添付",
          "これをもとに",
          "これで"
        ].filter((token) => body.includes(token));
        const fileScoped = fileTokens.length > 0;
        const createRequested = createTokens.length > 0;
        const requiresAttachment = !hasAttachments && createRequested && fileScoped;
        const clear = hasAttachments && createRequested && (fileScoped || /問題|クイズ|下書き/.test(body));
        const ambiguous = hasAttachments && !clear && (fileScoped || vagueTokens.length > 0);
        return {
          clear,
          ambiguous,
          requiresAttachment,
          route: clear ? "preset_create" : (requiresAttachment ? "attachment_required" : (ambiguous ? "clarify" : "none")),
          createTokens,
          fileTokens,
          vagueTokens
        };
      }
      async function _chatPrepareImageAttachmentForRequest(attachment){
        const runtime = (attachment && typeof attachment === "object") ? attachment : {};
        const file = runtime.file instanceof File ? runtime.file : null;
        if (!file) throw new Error("IMAGE_FILE_REQUIRED");
        const normalized = await _scanNormalizeImageFile(file);
        const finalFile = normalized?.file instanceof File ? normalized.file : file;
        return {
          meta: {
            id: String(runtime.id || _chatMessageId("att")).slice(0, 80),
            name: String(finalFile.name || runtime.name || "image").slice(0, 180),
            mimeType: String(finalFile.type || runtime.mimeType || "image/jpeg").trim().toLowerCase(),
            sourceType: "image",
            size: Math.max(0, Number(finalFile.size || runtime.size || 0)),
            preview: String(runtime.preview || "").slice(0, 280000)
          },
          file: finalFile
        };
      }
      async function _chatExtractPdfPagesForRequest(attachment){
        const runtime = (attachment && typeof attachment === "object") ? attachment : {};
        const file = runtime.file instanceof File ? runtime.file : null;
        if (!file) throw new Error("PDF_FILE_REQUIRED");
        if (Number(file.size || 0) > CHAT_FILE_MAX_PDF_BYTES){
          throw new Error(`PDF は最大 ${Math.round(CHAT_FILE_MAX_PDF_BYTES / (1024 * 1024))}MB までです。`);
        }
        const pdfjs = await _chatGetPdfjs();
        const arrayBuffer = await _chatReadFileAsArrayBuffer(file);
        const pdf = await pdfjs.getDocument({ data: arrayBuffer }).promise;
        try{
          const pageCount = Math.max(0, Number(pdf?.numPages || 0)) || 0;
          if (pageCount > CHAT_FILE_MAX_PDF_PAGES){
            throw new Error(`PDF は最大 ${CHAT_FILE_MAX_PDF_PAGES} ページまでです。`);
          }
          const pages = [];
          const fallbackFiles = [];
          for (let i = 1; i <= pageCount; i += 1){
            const page = await pdf.getPage(i);
            const textContent = await page.getTextContent();
            const text = Array.isArray(textContent?.items)
              ? textContent.items.map((item) => String(item?.str || "").trim()).filter(Boolean).join(" ").replace(/\s+/g, " ").trim()
              : "";
            const textSufficient = text.length >= CHAT_FILE_TEXT_SUFFICIENT_CHARS;
            const pageMeta = {
              pageNumber: i,
              text: text.slice(0, 4000),
              textSufficient
            };
            if (!textSufficient && fallbackFiles.length < CHAT_FILE_MAX_PDF_FALLBACK_IMAGES){
              const viewport = page.getViewport({ scale: 1.35 });
              const canvas = document.createElement("canvas");
              canvas.width = Math.max(1, Math.round(viewport.width));
              canvas.height = Math.max(1, Math.round(viewport.height));
              const ctx = canvas.getContext("2d", { alpha: false });
              if (ctx){
                await page.render({ canvasContext: ctx, viewport }).promise;
                const blob = await new Promise((resolve) => canvas.toBlob((value) => resolve(value || null), "image/jpeg", 0.82));
                if (blob){
                  const fallbackFile = new File([blob], `${String(file.name || "pdf").replace(/\.[A-Za-z0-9]+$/, "")}-p${i}.jpg`, {
                    type: "image/jpeg",
                    lastModified: Date.now()
                  });
                  const fallbackField = `pdf_page_${runtime.id || "att"}_${i}`;
                  fallbackFiles.push({ fieldName: fallbackField, file: fallbackFile });
                  pageMeta.fallbackField = fallbackField;
                }
              }
            }
            pages.push(pageMeta);
          }
          return {
            meta: {
              id: String(runtime.id || _chatMessageId("att")).slice(0, 80),
              name: String(file.name || runtime.name || "document.pdf").slice(0, 180),
              mimeType: "application/pdf",
              sourceType: "pdf",
              size: Math.max(0, Number(file.size || runtime.size || 0)),
              pageCount,
              preview: ""
            },
            pages,
            fallbackFiles
          };
        } finally {
          try{ pdf?.destroy?.(); }catch{}
        }
      }
      async function _chatBuildPresetDraftFormData(job){
        const attachments = _chatCloneRuntimeAttachments(job?.attachments);
        const formData = new FormData();
        const manifestAttachments = [];
        let imageCount = 0;
        let imageBytes = 0;
        for (let idx = 0; idx < attachments.length; idx += 1){
          const attachment = attachments[idx];
          if (attachment.sourceType === "pdf"){
            _chatPushProcessPanelLine(`まずPDF全体の構成を見ています (${attachment.name})`, "inspect_pdf()", "active");
            const prepared = await _chatExtractPdfPagesForRequest(attachment);
            manifestAttachments.push({
              ...prepared.meta,
              pages: prepared.pages
            });
            for (const fallback of prepared.fallbackFiles){
              formData.append(fallback.fieldName, fallback.file, fallback.file.name);
            }
            continue;
          }
          imageCount += 1;
          const preparedImage = await _chatPrepareImageAttachmentForRequest(attachment);
          imageBytes += Math.max(0, Number(preparedImage.meta.size || 0));
          const fieldName = `image_${idx + 1}`;
          manifestAttachments.push({
            ...preparedImage.meta,
            fieldName
          });
          formData.append(fieldName, preparedImage.file, preparedImage.file.name);
        }
        if (imageCount > CHAT_FILE_MAX_IMAGES){
          throw new Error(`画像は最大 ${CHAT_FILE_MAX_IMAGES} 枚までです。`);
        }
        if (imageBytes > CHAT_FILE_MAX_IMAGE_TOTAL_BYTES){
          throw new Error(`画像の合計容量は最大 ${Math.round(CHAT_FILE_MAX_IMAGE_TOTAL_BYTES / (1024 * 1024))}MB までです。`);
        }
        const manifest = {
          conversationId: String(job?.conversationId || _chatEnsureConversationId()).trim(),
          messageId: String(job?.messageId || "").trim(),
          mode: _chatNormalizeAiMode(job?.mode || _chatState.aiMode),
          text: String(job?.text || "").trim(),
          intent: (job?.fileIntent && typeof job.fileIntent === "object") ? {
            clear: !!job.fileIntent.clear,
            ambiguous: !!job.fileIntent.ambiguous,
            route: String(job.fileIntent.route || "").trim(),
            createTokens: Array.isArray(job.fileIntent.createTokens) ? job.fileIntent.createTokens.slice(0, 8) : [],
            fileTokens: Array.isArray(job.fileIntent.fileTokens) ? job.fileIntent.fileTokens.slice(0, 8) : [],
            vagueTokens: Array.isArray(job.fileIntent.vagueTokens) ? job.fileIntent.vagueTokens.slice(0, 8) : []
          } : null,
          attachments: manifestAttachments
        };
        formData.append("manifest", JSON.stringify(manifest));
        return { formData, manifest };
      }
      async function _chatRequestPresetDraft(job, abortSignal){
        const startedAt = Date.now();
        const conversationId = String(job?.conversationId || _chatEnsureConversationId()).trim();
        const messageId = String(job?.messageId || "").trim();
        _chatResetPresetFlowState({ keepProcessPanel: true });
        _chatSetPresetFlowState({
          active: true,
          conversationId,
          messageId,
          intent: job?.fileIntent || null,
          attachments: job?.attachments || []
        });
        _chatSetProcessPanelState({
          visible: true,
          title: "プリセット下書きを作成しています",
          meta: "添付を確認しています",
          lines: [{ message: "添付ファイルを確認しています", code: "validate_attachments()", status: "active" }],
          startedAt,
          done: false
        });
        _chatState.expandedProcessLogIds.add("__preset_live__");
        _appRenderChat();
        try{
          const { formData, manifest } = await _chatBuildPresetDraftFormData(job);
          _chatDebugPresetFlow("preset_route_request", {
            conversationId,
            messageId,
            attachedFiles: _chatCloneAttachmentMetaList(job?.attachments).map((item) => ({
              id: item.id,
              name: item.name,
              sourceType: item.sourceType,
              pageCount: item.pageCount || 0
            })),
            intent: manifest.intent || null
          });
          _chatSetProcessPanelState({
            ..._chatState.processPanel,
            visible: true,
            meta: "問題候補を生成しています",
            done: false
          });
          _chatPushProcessPanelLine("問題にしやすい範囲を探しています", "extract_topics()", "done");
          _chatPushProcessPanelLine("下書きとして保存できる形にまとめています", "save_preset_draft()", "active");
          _appRenderChat();
          const headers = {};
          if (__APP_IS_LOCAL_CLIENT_DEV__){
            headers["X-VQ-Client-Id"] = "local-html";
          }
          const authToken = (typeof _authGetToken === "function") ? String(_authGetToken() || "").trim() : "";
          if (authToken && _chatApiAllowsAuthHeader(CHAT_PRESET_DRAFT_API_URL)){
            headers.Authorization = `Bearer ${authToken}`;
          }
          const res = await fetch(CHAT_PRESET_DRAFT_API_URL, {
            method: "POST",
            headers,
            body: formData,
            signal: abortSignal || null
          });
          const raw = await res.text();
          let body = {};
          try{
            body = raw ? JSON.parse(raw) : {};
          }catch{
            body = {};
          }
          try{ _appApplyQreditPayload(body || {}); }catch{}
          const flow = String(body?.flow || "");
          const confirmPayload = (body?.confirmPayload && typeof body.confirmPayload === "object")
            ? { ...body.confirmPayload }
            : ((body?.meta?.confirmPayload && typeof body.meta.confirmPayload === "object") ? { ...body.meta.confirmPayload } : null);
          const aiMeta = body?.meta && typeof body.meta === "object" ? {
            ...body.meta,
            assistantName: CHAT_ASSISTANT_NAME
          } : null;
          _chatDebugPresetFlow("preset_route_response", {
            conversationId,
            messageId,
            flow,
            confirmPayload,
            model: String(aiMeta?.model || ""),
            attachedFiles: _chatCloneAttachmentMetaList(job?.attachments).map((item) => ({ id: item.id, name: item.name }))
          });
          const processLog = _chatSanitizeProcessLog(body?.processLog);
          const processElapsedMs = Math.max(0, Number(body?.processElapsedMs || Date.now() - startedAt)) || Math.max(0, Date.now() - startedAt);
          if (!res.ok && flow !== "generation_failed"){
            const err = new Error(String(body?.answer || body?.message || "下書き生成に失敗しました。"));
            err.code = String(body?.code || body?.error || `HTTP_${res.status}`);
            err.status = Number(res.status || 0);
            err.data = body || null;
            throw err;
          }
          if (flow === "professor_required"){
            _chatSetProcessPanelState({
              visible: true,
              title: "作成フロー待機中",
              meta: "professor モードが必要です",
              lines: processLog.length ? processLog : [{ message: "この機能は professor モードで利用できます", code: "professor_required()", status: "error" }],
              startedAt,
              done: true
            });
            _chatSetPresetFlowState({
              active: false,
              conversationId,
              messageId,
              confirmPayload: null,
              attachments: job?.attachments || []
            });
            return {
              text: String(body?.answer || "この機能は professor モードで利用できます。").trim(),
              actions: [],
              sources: [],
              charts: [],
              aiMeta,
              preserveAttachments: true
            };
          }
          if (flow === "clarify"){
            _chatSetProcessPanelState({
              visible: true,
              title: "確認待ち",
              meta: "生成前に確認が必要です",
              lines: processLog.length ? processLog : [{ message: "このファイルから下書きを作成するか確認しています", code: "clarify_request()", status: "done" }],
              startedAt,
              done: true
            });
            _chatSetPresetFlowState({
              active: true,
              conversationId,
              messageId,
              attachments: job?.attachments || [],
              confirmPayload,
              selectedSourceFile: confirmPayload ? {
                id: String(confirmPayload.fileId || "").trim(),
                name: String(confirmPayload.fileName || "").trim(),
                documentType: String(confirmPayload.documentType || "").trim(),
                pageCount: Math.max(0, Number(confirmPayload.pageCount || 0)) || 0
              } : null,
              extractedSubject: String(confirmPayload?.detectedSubject || "").trim()
            });
            return {
              text: String(body?.answer || "このファイルからプリセット下書きを作成しますか？").trim(),
              actions: [],
              sources: [],
              charts: [],
              aiMeta,
              preserveAttachments: true
            };
          }
          if (flow !== "preset_draft_result"){
            _chatSetProcessPanelState({
              visible: true,
              title: "下書き生成に失敗しました",
              meta: "再試行できます",
              lines: processLog.length ? processLog : [{ message: "下書き保存まで完了できませんでした", code: "generation_failed()", status: "error" }],
              startedAt,
              done: true
            });
            _chatSetPresetFlowState({
              active: false,
              conversationId,
              messageId,
              attachments: job?.attachments || [],
              confirmPayload,
              extractedSubject: String(confirmPayload?.detectedSubject || "").trim()
            });
            return {
              text: _chatFriendlyGenerationError(body?.answer || body?.message),
              actions: [],
              sources: [],
              charts: [],
              aiMeta,
              preserveAttachments: true
            };
          }
          const savedPreset = _chatSavePresetDraftFromFlow(body?.presetDraft || {});
          const presetCard = _chatBuildPresetCard(savedPreset);
          _chatSetProcessPanelState({
            visible: true,
            title: "下書き保存が完了しました",
            meta: "完了",
            lines: processLog.length ? processLog : [{ message: "下書きとして保存しました", code: "save_preset_draft()", status: "done" }],
            startedAt,
            done: true
          });
          _chatSetPresetFlowState({
            active: false,
            conversationId,
            messageId,
            attachments: job?.attachments || [],
            confirmPayload,
            extractedSubject: String(confirmPayload?.detectedSubject || "").trim()
          });
          return {
            text: String(body?.answer || "プリセット下書きを作成しました。").trim(),
            actions: [],
            sources: [],
            charts: [],
            aiMeta,
            uiKind: "preset_draft_result",
            presetCard,
            presetDraft: savedPreset,
            processLog: processLog.length ? processLog : [{ message: "下書きとして保存しました", code: "save_preset_draft()", status: "done" }],
            processElapsedMs,
            preserveAttachments: false
          };
        } catch (err){
          _chatSetProcessPanelState({
            visible: true,
            title: "下書き生成に失敗しました",
            meta: "再試行してください",
            lines: [{ message: _chatFriendlyGenerationError(err?.message || ""), code: "preset_draft_failed()", status: "error" }],
            startedAt,
            done: true
          });
          _chatSetPresetFlowState({
            active: false,
            conversationId,
            messageId,
            attachments: job?.attachments || []
          });
          return {
            text: _chatFriendlyGenerationError(err?.message || ""),
            actions: [],
            sources: [],
            charts: [],
            aiMeta: null,
            preserveAttachments: true
          };
        }
      }
      function _chatRand(min, max){
        const a = Number(min) || 0;
        const b = Number(max) || a;
        return Math.floor(Math.random() * (b - a + 1)) + a;
      }
      function _chatPick(arr, fallback = ""){
        if (!Array.isArray(arr) || !arr.length) return fallback;
        return arr[Math.floor(Math.random() * arr.length)] || fallback;
      }
      function _chatNormalize(text){
        return String(text || "").toLowerCase().trim();
      }
      function _chatNormalizeForSearch(text){
        return _chatNormalize(text)
          .replace(/[\u3000\s]+/g, " ")
          .replace(/[!"#$%&'()*+,./:;<=>?@[\\\]^_`{|}~-]/g, " ")
          .trim();
      }
      function _chatTokenize(text){
        const src = _chatNormalizeForSearch(text);
        if (!src) return [];
        const out = [];
        const seen = new Set();
        const re = /([a-z0-9_#.-]{2,}|[一-龯ぁ-んァ-ヶー]{2,})/g;
        let m;
        while ((m = re.exec(src))){
          const t = String(m[1] || "").trim();
          if (!t || seen.has(t)) continue;
          seen.add(t);
          out.push(t);
          if (out.length >= 40) break;
        }
        return out;
      }
      function _chatExtractTerms(text, max = 4){
        const stop = new Set(["こと","それ","これ","です","ます","して","する","ある","ない","よう","から","まで","について"]);
        const terms = [];
        for (const t of _chatTokenize(text)){
          if (stop.has(t)) continue;
          terms.push(t);
          if (terms.length >= max) break;
        }
        return terms;
      }
      function _chatCountKeywordHits(normalizedText, keywords){
        const src = String(normalizedText || "");
        if (!src || !Array.isArray(keywords)) return 0;
        let c = 0;
        for (const kw of keywords){
          const token = _chatNormalize(kw);
          if (!token) continue;
          if (src.includes(token)) c++;
        }
        return c;
      }
      function _chatReadLastIntent(){
        try{
          const v = String(window.localStorage.getItem(CHAT_LAST_INTENT_KEY) || "").trim();
          return CHAT_INTENT_BY_ID.has(v) ? v : "";
        }catch{
          return "";
        }
      }
      function _chatSaveLastIntent(intentId){
        const id = String(intentId || "").trim();
        if (!CHAT_INTENT_BY_ID.has(id)) return;
        _chatState.lastIntentId = id;
        try{
          window.localStorage.setItem(CHAT_LAST_INTENT_KEY, id);
        }catch{}
      }
      function _chatNormalizeAiMode(raw){
        const v = String(raw || "").trim().toLowerCase();
        if (v === CHAT_AI_MODE_SEED_PRO || v === "seed-pro" || v === "seed_pro") return CHAT_AI_MODE_SEED_PRO;
        if (v === CHAT_AI_MODE_SEED_THINKING || v === "deepthink" || v === "deep_think" || v === "seed-thinking" || v === "seed_thinking") return CHAT_AI_MODE_SEED_THINKING;
        if (v === "code" || v === "sede") return "code";
        return (v === CHAT_AI_MODE_REASON || v === "reason" || v === "reasoning" || v === "deep" || v === "precision")
          ? CHAT_AI_MODE_REASON
          : CHAT_AI_MODE_NORMAL;
      }
      function _chatModeLabelShort(mode){
        return _chatNormalizeAiMode(mode) === CHAT_AI_MODE_REASON ? "professor" : "standard";
      }
      function _chatModeLabelFull(mode){
        return `${CHAT_ASSISTANT_NAME} ${_chatModeLabelShort(mode)}`;
      }
      function _chatPrettyModelName(modelRaw){
        const raw = String(modelRaw || "").trim();
        if (!raw) return "Meta Llama";
        if (/kimi-k2\.6/i.test(raw) || /kimi-k2/i.test(raw)) return "Kimi K2.6 (Code)";
        if (/gpt-oss-120b/i.test(raw)) return "GPT-OSS 120B (Seed Pro)";
        if (/deepseek-r1/i.test(raw)) return "DeepSeek R1 (Deepthink)";
        if (/llama-4-scout/i.test(raw)) return "Meta Llama 4 Scout";
        if (/llama-3\.3-70b/i.test(raw)) return "Meta Llama 3.3 70B";
        if (/llama-3\.1/i.test(raw)) return "Meta Llama 3.1";
        return raw.replace(/^@cf\/(?:meta|moonshotai|deepseek-ai)\//i, "").replace(/-/g, " ");
      }
      function _chatReadUpgradeNoticeSeen(){
        try{
          return String(window.localStorage.getItem(CHAT_UPGRADE_NOTICE_KEY) || "").trim() === "1";
        }catch{
          return false;
        }
      }
      function _chatWriteUpgradeNoticeSeen(){
        try{ window.localStorage.setItem(CHAT_UPGRADE_NOTICE_KEY, "1"); }catch{}
      }
      function _chatIsAiPaneActive(){
        return document.body?.dataset?.appTab === "chat"
          && _appCollabNormalizePane(_appCollabState?.pane || "choose") === "ai";
      }
      function _chatBuildWelcomeMessage(){
        return {
          id: "chat-welcome-ui",
          ts: Date.now(),
          role: "ai",
          text: CHAT_WELCOME_MESSAGE,
          uiKind: "welcome",
          actions: [
            { type: "askPrompt", label: "日本史のプリセットを作って", prompt: "日本史のプリセットを作って" },
            { type: "askPrompt", label: "最近の苦手を教えて", prompt: "最近の苦手を教えて" },
            { type: "askPrompt", label: "復習の進め方を相談する", prompt: "間違えた問題の復習方法を教えて" }
          ],
          aiMeta: null
        };
      }
      function _chatSetSidebarOpen(open){
        /* Desktop: respect collapsed state, don't force expand */
        if (window.innerWidth > 960){
          _chatState.sidebarOpen = true;
          el.appAiChatShell?.setAttribute("data-sidebar-open", "1");
          /* Do NOT touch sidebar-collapsed — user controls that via collapse button */
          return;
        }
        const on = !!open;
        _chatState.sidebarOpen = on;
        el.appAiChatShell?.setAttribute("data-sidebar-open", on ? "1" : "0");
        el.appChatSidebarToggleBtn?.setAttribute("aria-expanded", on ? "true" : "false");
        document.body.classList.toggle("chat-sidebar-open", on);
      }
      function _chatSetPromptShelfOpen(open){
        const on = !!open;
        _chatState.promptShelfOpen = on;
        el.appAiChatShell?.setAttribute("data-prompt-shelf-open", on ? "1" : "0");
        el.appChatPromptShelf?.classList.toggle("hidden", !on);
        el.appChatPromptToggleBtn?.setAttribute("aria-expanded", on ? "true" : "false");
      }
      function _chatSidebarItems(){
        const rows = [];
        for (const item of (_chatState.history || []).slice().reverse()){
          if (!item || item.role !== "user") continue;
          const text = String(item.text || "").trim();
          if (!text) continue;
          rows.push({
            id: String(item.id || ""),
            title: text.replace(/\s+/g, " ").slice(0, 38),
            preview: text.replace(/\s+/g, " ").slice(0, 74),
            time: _chatFmtDate(item.ts)
          });
          if (rows.length >= 18) break;
        }
        return rows;
      }
      function _chatRenderSidebar(){
        const listEl = document.getElementById("appChatSessionList");
        const emptyEl = document.getElementById("appChatSidebarEmpty");
        if (!listEl) return;
        const sessions = _chatState.sessions || [];
        listEl.replaceChildren();
        if (!sessions.length){
          if (emptyEl) emptyEl.classList.remove("hidden");
          return;
        }
        if (emptyEl) emptyEl.classList.add("hidden");
        const ul = document.createElement("ul");
        ul.className = "app-chat-session-ul";
        for (const ses of sessions){
          const li = document.createElement("li");
          li.className = "app-chat-session-item";
          if (ses.id === _chatState.activeSessionId) li.classList.add("is-active");
          li.setAttribute("data-chat-action", "switchSession");
          li.setAttribute("data-chat-ids", ses.id);
          li.setAttribute("role", "button");
          li.setAttribute("tabindex", "0");
          const title = ses.title || "新しいチャット";
          li.innerHTML = '<span class="app-chat-session-title">' + escapeHtml(title) + '</span>'
            + '<span class="app-chat-session-actions">'
            + '<span class="app-chat-session-options-btn" data-chat-action="sessionOptions" data-chat-ids="' + ses.id + '" role="button" tabindex="0" aria-label="Options"><span class="ms">more_horiz</span></span>'
            + '</span>';
          ul.appendChild(li);
        }
        listEl.appendChild(ul);
        _chatRenderModelUi();
      }
      /* ── Session options dropdown ── */
      function _chatCloseSessionOptions(){
        var dd = document.getElementById("appChatSessionDropdown");
        if (dd) dd.remove();
      }
      function _chatSessionDropdownOutside(e){
        var dd = document.getElementById("appChatSessionDropdown");
        if (dd && !dd.contains(e.target) && !e.target.closest(".app-chat-session-options-btn")){
          _chatCloseSessionOptions();
          document.removeEventListener("click", _chatSessionDropdownOutside, true);
        }
      }
      function _chatOpenSessionOptions(targetId, anchorEl){
        _chatCloseSessionOptions();
        var dropdown = document.createElement("div");
        dropdown.className = "xselect-menu app-chat-session-dropdown";
        dropdown.id = "appChatSessionDropdown";
        dropdown.style.cssText = "position:fixed;z-index:9999;min-width:180px;";
        dropdown.innerHTML =
          '<div class="xselect-option" role="button" data-chat-action="renameSession" data-chat-ids="' + targetId + '"><span class="ms" style="font-size:18px;margin-right:6px;" aria-hidden="true">edit</span>名前を変更</div>'
          + '<div class="xselect-option" role="button" data-chat-action="addToProject" data-chat-ids="' + targetId + '"><span class="ms" style="font-size:18px;margin-right:6px;" aria-hidden="true">drive_file_move</span>プロジェクトに追加</div>'
          + '<div class="xselect-option" role="button" data-chat-action="confirmDeleteSession" data-chat-ids="' + targetId + '" style="color:var(--melta-danger, #ef4444);"><span class="ms" style="font-size:18px;margin-right:6px;color:var(--melta-danger, #ef4444);" aria-hidden="true">delete</span>削除</div>';
        document.body.appendChild(dropdown);
        var rect = anchorEl.getBoundingClientRect();
        var dropW = 200;
        var left = rect.right - dropW;
        if (left < 4) left = 4;
        var top = rect.bottom + 4;
        if (top + 160 > window.innerHeight) top = rect.top - 160;
        dropdown.style.left = left + "px";
        dropdown.style.top = top + "px";
        setTimeout(function(){ document.addEventListener("click", _chatSessionDropdownOutside, true); }, 0);
      }
      function _chatRenameSessionInline(targetId){
        _chatCloseSessionOptions();
        var li = document.querySelector('.app-chat-session-item[data-chat-ids="' + targetId + '"]');
        if (!li) return;
        var titleEl = li.querySelector(".app-chat-session-title");
        if (!titleEl) return;
        var currentTitle = titleEl.textContent.trim();
        var input = document.createElement("input");
        input.type = "text";
        input.className = "app-chat-session-rename-input";
        input.value = currentTitle;
        titleEl.replaceWith(input);
        input.focus();
        input.select();
        function commit(){
          var newTitle = input.value.trim() || currentTitle;
          var ses = (_chatState.sessions || []).find(function(s){ return s.id === targetId; });
          if (ses){ ses.title = newTitle.slice(0, 60); _chatSaveSessions(); }
          _chatRenderSidebar();
        }
        input.addEventListener("blur", commit, { once: true });
        input.addEventListener("keydown", function(e){
          if (e.key === "Enter"){ e.preventDefault(); input.blur(); }
          if (e.key === "Escape"){ input.value = currentTitle; input.blur(); }
        });
      }
      async function _chatConfirmDeleteSession(targetId){
        _chatCloseSessionOptions();
        var ok = await uiConfirm("このチャットを削除しますか？\nこの操作は取り消せません。", {
          title: "チャットを削除",
          okText: "削除する",
          cancelText: "キャンセル",
          danger: true
        });
        if (ok && typeof _chatDeleteSession === "function") _chatDeleteSession(targetId);
      }
      function _chatToggleSidebarCollapse(){
        var shell = document.getElementById("appAiChatShell");
        if (!shell) return;
        shell.classList.toggle("sidebar-collapsed");
        var btn = shell.querySelector(".app-chat-sidebar-collapse-btn .ms");
        if (btn) btn.textContent = shell.classList.contains("sidebar-collapsed") ? "left_panel_open" : "left_panel_close";
      }

      /* ── Chat Sidebar Profile ── */
      function _chatUpdateSidebarProfile(){
        try{
          const identity = (typeof _appV2Identity === "function") ? _appV2Identity() : { name:"User", meta:"" };
          const profile = (_appSocialState?.profile && typeof _appSocialState.profile === "object") ? _appSocialState.profile : null;
          const name = String(profile?.displayName || identity.name || "User");
          const avatarEl = document.getElementById("appChatSidebarAvatar");
          const nameEl = document.getElementById("appChatSidebarUserName");
          const planEl = document.getElementById("appChatSidebarUserPlan");
          if (nameEl) nameEl.textContent = name;
          if (avatarEl && typeof _appApplyAvatarVisual === "function"){
            _appApplyAvatarVisual(avatarEl, String(profile?.avatarUrl || ""), (typeof _appAvatarFallbackText === "function") ? _appAvatarFallbackText(name, profile?.nickname || authState?.user?.nickname || "") : name.slice(0,2).toUpperCase());
          }
          const sub = (_appQreditState?.subscription && typeof _appQreditState.subscription === "object") ? _appQreditState.subscription : {};
          const planLabel = sub.isActive ? String(sub.label || "PRE") : "Free";
          if (planEl) planEl.textContent = planLabel;
          /* Lock Sede nav for FREE users */
          const sedeNav = document.getElementById("appChatNavSede");
          if (sedeNav){
            const isPaid = !!(sub.isActive && sub.planId && sub.planId !== "free");
            sedeNav.classList.toggle("is-locked", !isPaid);
          }
        }catch(e){ console.warn("[chatProfile]", e); }
      }

      /* ── Profile Dropdown Menu ── */
      var _chatProfileDropdown = null;
      function _chatCloseProfileMenu(){
        if (_chatProfileDropdown){ _chatProfileDropdown.remove(); _chatProfileDropdown = null; }
        document.removeEventListener("click", _chatProfileMenuOutside, true);
      }
      function _chatProfileMenuOutside(e){
        if (_chatProfileDropdown && !_chatProfileDropdown.contains(e.target)){
          _chatCloseProfileMenu();
        }
      }
      var _chatProfileLangOpen = false;
      function _chatOpenProfileMenu(){
        _chatCloseProfileMenu();
        _chatProfileLangOpen = false;
        var sub = (_appQreditState?.subscription && typeof _appQreditState.subscription === "object") ? _appQreditState.subscription : {};
        var balance = _appQreditState?.balance || 0;
        var symbol = _appQreditState?.symbol || "Q";
        var planLabel = sub.isActive ? String(sub.label || "PRE") : "Free";
        var isActive = !!sub.isActive;
        var fmtBal = (typeof _appQreditFormatNumber === "function") ? _appQreditFormatNumber(balance) : String(balance);
        var currentLang = String(localStorage.getItem("app.chat.lang") || "ja");

        var dd = document.createElement("div");
        dd.className = "xselect-menu app-chat-profile-dropdown";
        dd.style.cssText = "position:fixed;z-index:9999;min-width:240px;";

        var html = '';
        html += '<div class="xselect-option" style="pointer-events:none;opacity:1;"><span class="ms" style="font-size:18px;margin-right:8px;">bolt</span><span style="flex:1;">' + symbol + ' ' + fmtBal + '</span></div>';
        html += '<div class="xselect-option" style="pointer-events:none;opacity:1;"><span class="ms" style="font-size:18px;margin-right:8px;">workspace_premium</span><span style="flex:1;">' + planLabel + ' プラン</span></div>';
        if (!isActive){
          html += '<div class="xselect-option" role="button" data-prof-action="subscription" style="color:var(--melta-primary-500, #6366f1);font-weight:500;"><span class="ms" style="font-size:18px;margin-right:8px;color:var(--melta-primary-500, #6366f1);">upgrade</span>EDU PRE にアップグレード</div>';
        }
        html += '<div style="border-top:1px solid rgba(0,0,0,.06);margin:4px 0;"></div>';
        html += '<div class="xselect-option" role="button" data-prof-action="settings"><span class="ms" style="font-size:18px;margin-right:8px;">settings</span>設定</div>';
        html += '<div class="xselect-option" role="button" data-prof-action="langToggle" style="position:relative;"><span class="ms" style="font-size:18px;margin-right:8px;">language</span><span style="flex:1;">言語</span><span class="ms" style="font-size:16px;color:#94a3b8;">chevron_right</span></div>';
        html += '<div class="app-chat-profile-lang-sub" style="display:none;padding:0 4px 4px;">';
        html += '<div class="xselect-option' + (currentLang==="ja" ? " is-selected" : "") + '" role="button" data-prof-action="setLang" data-lang="ja" style="padding-left:38px;font-size:13.5px;">🇯🇵 日本語' + (currentLang==="ja" ? ' <span class="ms" style="font-size:16px;margin-left:auto;">check</span>' : '') + '</div>';
        html += '<div class="xselect-option' + (currentLang==="en" ? " is-selected" : "") + '" role="button" data-prof-action="setLang" data-lang="en" style="padding-left:38px;font-size:13.5px;">🇺🇸 English' + (currentLang==="en" ? ' <span class="ms" style="font-size:16px;margin-left:auto;">check</span>' : '') + '</div>';
        html += '</div>';

        dd.innerHTML = html;
        document.body.appendChild(dd);
        _chatProfileDropdown = dd;

        var btn = document.querySelector(".app-chat-sidebar-user-btn");
        if (btn){
          var rect = btn.getBoundingClientRect();
          dd.style.left = (rect.left + 4) + "px";
          dd.style.bottom = (window.innerHeight - rect.top + 4) + "px";
          dd.style.top = "auto";
        }

        dd.addEventListener("click", function(e){
          var opt = e.target.closest("[data-prof-action]");
          if (!opt) return;
          var act = opt.getAttribute("data-prof-action");
          if (act === "subscription"){
            _chatCloseProfileMenu();
            var subTab = document.querySelector('[data-app-tab="subscription"]');
            if (subTab) subTab.click();
          } else if (act === "settings"){
            _chatCloseProfileMenu();
            if (typeof _chatSettingsOpen === "function") _chatSettingsOpen();
          } else if (act === "langToggle"){
            var langSub = dd.querySelector(".app-chat-profile-lang-sub");
            if (langSub) langSub.style.display = langSub.style.display === "none" ? "block" : "none";
          } else if (act === "setLang"){
            var lang = opt.getAttribute("data-lang") || "ja";
            try{ localStorage.setItem("app.chat.lang", lang); }catch{}
            _chatCloseProfileMenu();
          }
        });

        setTimeout(function(){ document.addEventListener("click", _chatProfileMenuOutside, true); }, 0);
      }

      /* ── Chat Search Popup ── */
      /* ── Project Manager Overlay ── */
      /* ══════════════════════════════════════════════════════
         SEDE — Session management, UI, Search, Files, Terminal
         ══════════════════════════════════════════════════════ */
      var SEDE_SESSIONS_KEY = "app.sede.sessions.v1";
      var SEDE_ACTIVE_KEY = "app.sede.active.v1";
      var SEDE_FILES_PREFIX = "app.sede.files.";
      /* FIX: expose _sedeState + helpers to window so the Sede inline IIFE can access them */
      var _sedeState = window._sedeState = { sessions:[], activeId:"", loaded:false };

      function _sedeLangClass(lang){
        var l = String(lang||"").toLowerCase();
        if (/^(js|javascript)$/.test(l)) return "is-js";
        if (/^(py|python)$/.test(l)) return "is-py";
        if (/^(ts|typescript)$/.test(l)) return "is-ts";
        if (/^(html)$/.test(l)) return "is-html";
        if (/^(css|scss|less)$/.test(l)) return "is-css";
        if (/^(rust|rs)$/.test(l)) return "is-rust";
        if (/^(go|golang)$/.test(l)) return "is-go";
        return "is-other";
      }
      function _sedeLangLabel(lang){
        var l = String(lang||"").toLowerCase();
        if (/^(js|javascript)$/.test(l)) return "JS";
        if (/^(py|python)$/.test(l)) return "PY";
        if (/^(ts|typescript)$/.test(l)) return "TS";
        if (/^(html)$/.test(l)) return "HTML";
        if (/^(css|scss|less)$/.test(l)) return "CSS";
        if (/^(rust|rs)$/.test(l)) return "RS";
        if (/^(go|golang)$/.test(l)) return "GO";
        return String(lang||"").toUpperCase().slice(0,4) || "";
      }

      function _sedeLoadSessions(){
        try{
          var raw = localStorage.getItem(SEDE_SESSIONS_KEY);
          _sedeState.sessions = raw ? JSON.parse(raw).filter(Boolean).sort(function(a,b){ return (b.updatedAt||0)-(a.updatedAt||0); }) : [];
        }catch{ _sedeState.sessions = []; }
        /* 別キーからコード本体を復元 */
        (_sedeState.sessions||[]).forEach(function(s){
          if (s.currentCode && s.currentCode._ref && s.id) {
            try {
              var code = localStorage.getItem("app.sede.code." + s.id);
              if (code) s.currentCode = { lang: s._codeLang || s.currentCode.lang || "html", filename: s._codeFname || s.currentCode.filename || "app.html", code: code };
            } catch(e) {}
          }
        });
        try{ _sedeState.activeId = String(localStorage.getItem(SEDE_ACTIVE_KEY)||"").trim(); }catch{}
        _sedeState.loaded = true;
        _sedeRemoteLoad();
      }
      function _sedeSaveSessions(){
        try{
          /* コードは別キーに保存（容量分散） */
          (_sedeState.sessions||[]).forEach(function(s){
            if (s.currentCode && s.currentCode.code && !s.currentCode._ref) {
              try {
                localStorage.setItem("app.sede.code." + s.id, s.currentCode.code);
                /* メタデータだけセッションに残す */
                var _lang = s.currentCode.lang || "html";
                var _fname = s.currentCode.filename || "app.html";
                s._hasCode = true;
                s._codeLang = _lang;
                s._codeFname = _fname;
                s._codeLen = s.currentCode.code.length;
                s.currentCode = { lang: _lang, filename: _fname, _ref: true };
              } catch(e3) { /* 個別コード保存失敗は無視 */ }
            }
            /* メッセージを大幅に軽量化 — user/aiのみ保持、log系は全削除 */
            if (s.messages && s.messages.length > 10) {
              s.messages = s.messages.filter(function(m){ return m.role === "user" || m.role === "ai" || m.role === "steer"; }).slice(-20);
            }
          });
          /* 古いセッション（100件超）を自動削除 — コードは別キー + D1バックアップなので余裕 */
          if (_sedeState.sessions.length > 100) {
            var _removed = _sedeState.sessions.splice(100);
            _removed.forEach(function(rs){ try{ localStorage.removeItem("app.sede.code." + rs.id); }catch{} });
          }
          var json = JSON.stringify(_sedeState.sessions||[]);
          localStorage.setItem(SEDE_SESSIONS_KEY, json);
        } catch(e){
          console.warn("[Sede] localStorage save failed, trimming:", e);
          try {
            (_sedeState.sessions||[]).forEach(function(s){
              if (s.messages && s.messages.length > 20) s.messages = s.messages.slice(-20);
            });
            localStorage.setItem(SEDE_SESSIONS_KEY, JSON.stringify(_sedeState.sessions||[]));
          } catch(e2){ console.error("[Sede] localStorage still full:", e2); }
        }
        /* Queue D1 remote save (debounced) */
        _sedeRemoteQueueSave();
      }

      /* ── Sede D1 Remote Sync ── */
      var _sedeRemoteSaveTimer = 0;
      var _sedeRemoteLoaded = false;
      function _sedeRemoteApiUrl(path){
        var base = "";
        try { base = (typeof AUTH_API_BASE !== "undefined") ? String(AUTH_API_BASE).trim().replace(/\/+$/, "") : ""; } catch(e){}
        if (!base) base = "https://vocabuquiz-api.rintyblog.workers.dev";
        return base + path;
      }
      function _sedeRemoteHeaders(){
        var h = { "Content-Type": "application/json" };
        try {
          var t = (typeof _authGetToken === "function") ? _authGetToken() : null;
          if (!t) t = String(localStorage.getItem("app.auth.token.v1") || "").trim();
          if (t) h.Authorization = "Bearer " + t;
        } catch(e){}
        return h;
      }
      function _sedeRemoteQueueSave(){
        if (_sedeRemoteSaveTimer) clearTimeout(_sedeRemoteSaveTimer);
        _sedeRemoteSaveTimer = setTimeout(function(){ _sedeRemoteSave(); }, 1200);
      }
      /* ページ閉じる/リロード時に即保存 */
      window.addEventListener("beforeunload", function(){
        try{ localStorage.setItem(SEDE_SESSIONS_KEY, JSON.stringify(_sedeState.sessions||[])); }catch{}
        if (_sedeRemoteSaveTimer){ clearTimeout(_sedeRemoteSaveTimer); _sedeRemoteSave(); }
      });
      async function _sedeRemoteSave(){
        _sedeRemoteSaveTimer = 0;
        var h = _sedeRemoteHeaders();
        if (!h.Authorization) return; /* Not logged in */
        try {
          /* コード本体をセッションに含めて送信（D1は容量大きい） */
          var sessionsWithCode = (_sedeState.sessions || []).map(function(s){
            var copy = Object.assign({}, s);
            if (copy.currentCode && copy.currentCode._ref && copy.id) {
              try {
                var code = localStorage.getItem("app.sede.code." + copy.id);
                if (code) copy.currentCode = { lang: copy._codeLang || "html", filename: copy._codeFname || "app.html", code: code };
              } catch(e){}
            }
            return copy;
          });
          await fetch(_sedeRemoteApiUrl("/api/sede/sessions"), {
            method: "POST", headers: h,
            body: JSON.stringify({
              sessions: sessionsWithCode,
              activeId: _sedeState.activeId || "",
              updatedAtMs: Date.now()
            })
          });
        } catch(e){ console.warn("[Sede] remote save error:", e); }
      }
      async function _sedeRemoteLoad(){
        if (_sedeRemoteLoaded) return;
        var h = _sedeRemoteHeaders();
        if (!h.Authorization) return;
        try {
          var res = await fetch(_sedeRemoteApiUrl("/api/sede/sessions"), { method: "GET", headers: h });
          if (!res.ok) return;
          var data = await res.json();
          var remoteSessions = Array.isArray(data?.sessions) ? data.sessions : [];
          var remoteTs = Number(data?.updatedAtMs || 0);
          /* Merge: ローカルを優先。リモートにしかないセッションだけ追加 */
          var localMap = {};
          (_sedeState.sessions || []).forEach(function(s){ localMap[s.id] = s; });
          var merged = false;
          remoteSessions.forEach(function(rs){
            if (!localMap[rs.id]) {
              _sedeState.sessions.push(rs);
              merged = true;
            }
          });
          if (merged) {
            _sedeState.sessions.sort(function(a,b){ return (b.updatedAt||0)-(a.updatedAt||0); });
            try{ localStorage.setItem(SEDE_SESSIONS_KEY, JSON.stringify(_sedeState.sessions)); }catch{}
            if (typeof _sedeRenderSidebar === "function") _sedeRenderSidebar();
          }
          if (!_sedeState.sessions.length && remoteSessions.length){
            /* Local is empty, use remote */
            _sedeState.sessions = remoteSessions;
            if (data.activeId) _sedeState.activeId = data.activeId;
            /* リモートからコード本体をlocalStorageに復元 */
            remoteSessions.forEach(function(rs){
              if (rs.currentCode && rs.currentCode.code && rs.id) {
                try { localStorage.setItem("app.sede.code." + rs.id, rs.currentCode.code); } catch(e){}
              }
            });
            try{ localStorage.setItem(SEDE_SESSIONS_KEY, JSON.stringify(_sedeState.sessions)); }catch{}
            try{ localStorage.setItem(SEDE_ACTIVE_KEY, _sedeState.activeId); }catch{}
            if (typeof _sedeRenderSidebar === "function") _sedeRenderSidebar();
          }
          /* マージ時もコード復元 */
          if (merged) {
            remoteSessions.forEach(function(rs){
              if (rs.currentCode && rs.currentCode.code && rs.id && !localMap[rs.id]) {
                try { localStorage.setItem("app.sede.code." + rs.id, rs.currentCode.code); } catch(e){}
              }
            });
          }
          _sedeRemoteLoaded = true;
        } catch(e){ console.warn("[Sede] remote load error:", e); }
      }
      function _sedeCreateSession(lang){
        var id = "sede_" + Date.now() + "_" + Math.random().toString(36).slice(2,8);
        var ses = { id:id, title:"新規セッション", lang:String(lang||""), createdAt:Date.now(), updatedAt:Date.now(), messages:[], commands:[] };
        _sedeState.sessions.unshift(ses);
        _sedeState.activeId = id;
        _sedeSaveSessions();
        try{ localStorage.setItem(SEDE_ACTIVE_KEY, id); }catch{}
        _sedeRenderSidebar();
        /* Re-render inline chat for new session (welcome screen) */
        if (typeof _sedeInlineRender === "function") _sedeInlineRender();
        if (typeof _sedeInlineUpdateView === "function") _sedeInlineUpdateView();
        if (typeof _sedeInlineInitWelcome === "function") _sedeInlineInitWelcome();
        return ses;
      }
      function _sedeDeleteSession(id){
        _sedeState.sessions = _sedeState.sessions.filter(function(s){ return s.id !== id; });
        if (_sedeState.activeId === id){
          _sedeState.activeId = _sedeState.sessions.length ? _sedeState.sessions[0].id : "";
          try{ localStorage.setItem(SEDE_ACTIVE_KEY, _sedeState.activeId); }catch{}
        }
        _sedeSaveSessions();
        try{ localStorage.removeItem(SEDE_FILES_PREFIX + id); }catch{}
        _sedeRenderSidebar();
      }
      function _sedeRenameSession(id, name){
        var s = _sedeState.sessions.find(function(x){ return x.id === id; });
        if (s){ s.title = String(name||"").slice(0,80); s.updatedAt = Date.now(); _sedeSaveSessions(); }
      }
      function _sedeSwitchSession(id){
        /* Block switch if AI generation is in progress — prevents DOM wipe */
        if (window._sede && window._sede.processing) {
          /* Same session click → just ignore; different session → show notice */
          if (id !== _sedeState.activeId) {
            try {
              var _notice = document.createElement("div");
              _notice.className = "sede-log-chat";
              _notice.style.cssText = "color:#f59e0b;font-size:13px;padding:6px 12px;";
              _notice.textContent = "生成中はセッション切り替えできません。完了までお待ちください。";
              var _cl = document.getElementById("sedeChatList");
              if (_cl) { _cl.appendChild(_notice); _cl.scrollTop = _cl.scrollHeight; }
              setTimeout(function(){ if (_notice.parentNode) _notice.parentNode.removeChild(_notice); }, 3000);
            } catch(e){}
          }
          return;
        }
        _sedeState.activeId = id;
        try{ localStorage.setItem(SEDE_ACTIVE_KEY, id); }catch{}
        _sedeRenderSidebar();
        /* Re-render inline chat for new session */
        if (typeof _sedeInlineRender === "function") _sedeInlineRender();
        if (typeof _sedeInlineUpdateView === "function") _sedeInlineUpdateView();
      }
      function _sedeGetFiles(id){
        try{ var r = localStorage.getItem(SEDE_FILES_PREFIX + id); return r ? JSON.parse(r) : []; }catch{ return []; }
      }
      function _sedeSaveFiles(id, files){
        try{ localStorage.setItem(SEDE_FILES_PREFIX + id, JSON.stringify(files||[])); }catch{}
      }

      /* ── Sede Sidebar Render ── */
      function _sedeRenderSidebar(){
        if (!_sedeState.loaded) _sedeLoadSessions();
        var listEl = document.getElementById("appSedeSessionList");
        var emptyEl = document.getElementById("appSedeEmpty");
        if (!listEl) return;
        var sessions = _sedeState.sessions || [];
        if (!sessions.length){
          listEl.innerHTML = "";
          if (emptyEl) emptyEl.classList.remove("hidden");
          return;
        }
        if (emptyEl) emptyEl.classList.add("hidden");
        function esc(s){ var d=document.createElement("div"); d.textContent=s; return d.innerHTML; }
        var ul = document.createElement("ul");
        ul.className = "app-sede-session-ul";
        sessions.forEach(function(ses){
          var li = document.createElement("li");
          li.className = "app-sede-session-item" + (ses.id === _sedeState.activeId ? " is-active" : "");
          li.setAttribute("data-sede-action", "switchSession");
          li.setAttribute("data-sede-id", ses.id);
          var badge = ses.lang ? '<span class="app-sede-lang-badge ' + _sedeLangClass(ses.lang) + '">' + esc(_sedeLangLabel(ses.lang)) + '</span>' : '';
          li.innerHTML = '<span class="app-sede-session-title">' + esc(ses.title||"無題") + '</span>'
            + badge
            + '<span class="app-sede-session-actions"><span class="app-sede-session-opts-btn" data-sede-action="sessionOptions" data-sede-id="' + ses.id + '"><span class="ms">more_horiz</span></span></span>';
          ul.appendChild(li);
        });
        listEl.innerHTML = "";
        listEl.appendChild(ul);
      }

      /* Expose sede helpers to window for IIFE access */
      window._sedeSaveSessions = _sedeSaveSessions;
      window._sedeCreateSession = _sedeCreateSession;
      window._sedeRenderSidebar = _sedeRenderSidebar;
      window._sedeLoadSessions = _sedeLoadSessions;
      window._sedeSwitchSession = _sedeSwitchSession;

      /* ── Mode switching ── */
      var _chatPreSedeMode = null;
      function _chatSwitchToSede(){
        /* Sede Redesign v2: Shadow DOM表示 + 元のSede初期化も実行 */
        var _rv2 = document.getElementById("sedeRedesignV2");
        if (_rv2) {
          _rv2.style.display = "flex";
          document.body.style.overflow = "hidden";
          /* 生成中なら Shadow DOM UI を再接続 */
          if(window._sede && (window._sede.agentRunning || window._sede.processing)){
            try{
              var _s2 = _rv2.shadowRoot;
              if(_s2){
                /* 現セッションの既存ログを復元 */
                var _curSes = window._sedeState && window._sedeState.sessions.find(function(x){ return x.id === window._sedeState.activeId; });
                if(_curSes && _curSes.messages){
                  var _cl2 = _s2.getElementById("sedeChatList");
                  var _ls2 = _s2.getElementById("sedeLogsScroll");
                  if(_cl2) _cl2.innerHTML = "";
                  if(_ls2) _ls2.innerHTML = "";
                  _curSes.messages.forEach(function(m){
                    var r = m.role || "ai";
                    if(r === "user" || r === "ai"){
                      var _d = document.createElement("div"); _d.className = "chat-msg"+(r==="user"?" is-user":"");
                      _d.innerHTML = '<div class="chat-role">'+(r==="user"?"You":"Sede")+'</div><div class="'+(r==="user"?"chat-bubble-user":"chat-bubble-ai")+'">'+m.text+'</div>';
                      if(_cl2) _cl2.appendChild(_d);
                    } else if(r === "log" && _ls2){
                      var _l = document.createElement("div"); _l.className = "log-tool"; _l.innerHTML = '<span class="ms">'+(m.icon||"info")+'</span> '+m.text;
                      _ls2.appendChild(_l);
                    } else if(r === "log-ok" && _ls2){
                      var _l2 = document.createElement("div"); _l2.className = "log-tool"; _l2.innerHTML = '<span class="ms is-ok">'+(m.icon||"check_circle")+'</span> <span style="color:var(--success);font-weight:600;">'+m.text+'</span>';
                      _ls2.appendChild(_l2);
                    } else if(r === "chat-log" && _ls2){
                      var _l3 = document.createElement("div"); _l3.className = "log-ai"; _l3.innerHTML = '<div class="log-ai-header"><span class="ms">chat</span> Sede</div><div class="log-ai-body">'+m.text+'</div>';
                      _ls2.appendChild(_l3);
                    }
                  });
                }
              }
            }catch(e){}
          }
        }
        var shell = document.getElementById("appAiChatShell");
        if (!shell) return;
        /* _chatPreSedeMode is set in _chatSetAiMode before aiMode changes */
        /* Set sede mode on shell — CSS hides Quick Chat elements, shows Sede elements */
        shell.setAttribute("data-chat-mode", "sede");
        /* Clear Quick Chat's visible messages so they don't bleed through */
        if (el.appChatList) el.appChatList.innerHTML = "";
        /* Load Sede sessions and render sidebar */
        if (!_sedeState.loaded) _sedeLoadSessions();
        _sedeRenderSidebar();
        /* Auto-select latest session or show welcome */
        if (_sedeState.sessions.length && _sedeState.activeId) {
          _sedeSwitchSession(_sedeState.activeId);
        }
        /* Render inline Sede chat */
        if (typeof _sedeInlineRender === "function") _sedeInlineRender();
        if (typeof _sedeInlineUpdateView === "function") _sedeInlineUpdateView();
        if (typeof _sedeInlineInitWelcome === "function") _sedeInlineInitWelcome();
        /* Start usage bar polling */
        if (typeof _sedeStartUsagePolling === "function") _sedeStartUsagePolling();
      }
      function _chatSwitchToQuickChat(){
        var shell = document.getElementById("appAiChatShell");
        if (!shell) return;
        shell.removeAttribute("data-chat-mode");
        /* Restore pre-Sede model */
        var restoreMode = _chatPreSedeMode || "standard";
        _chatPreSedeMode = null;
        if (restoreMode !== "code") {
          _chatSaveAiMode(restoreMode);
          if (typeof _chatRenderModeUi === "function") _chatRenderModeUi();
        }
        /* Close 2-pane if open */
        if (typeof _sedeInlineCloseTwoPane === "function") _sedeInlineCloseTwoPane();
        /* Re-render Quick Chat with its own history */
        _chatState.followBottom = true;
        _appRenderChat({ forceScroll: true });
      }

      /* ── Sede Search Modal ── */
      function _sedeOpenSearch(){
        var existing = document.querySelector(".app-chat-search-overlay.is-sede");
        if (existing) existing.remove();
        var sessions = _sedeState.sessions || [];
        var overlay = document.createElement("div");
        overlay.className = "app-chat-search-overlay is-sede";
        function esc(s){ var d=document.createElement("div"); d.textContent=s; return d.innerHTML; }
        function highlight(text, query){
          if (!query) return esc(text);
          var re = new RegExp("(" + query.replace(/[.*+?^${}()|[\]\\]/g,"\\$&") + ")", "gi");
          return esc(text).replace(re, '<span class="app-sede-search-highlight">$1</span>');
        }
        function renderList(query){
          var body = overlay.querySelector(".app-chat-search-body");
          if (!body) return;
          var q = (query||"").trim().toLowerCase();
          var filtered = q ? sessions.filter(function(s){
            return (s.title||"").toLowerCase().indexOf(q) !== -1
              || (s.lang||"").toLowerCase().indexOf(q) !== -1
              || (s.messages||[]).some(function(m){ return (m.text||"").toLowerCase().indexOf(q) !== -1; });
          }) : sessions;
          var html = '';
          if (!filtered.length){
            html = '<div class="app-chat-search-empty">お探しのセッションは見つかりませんでした。</div>';
          } else {
            filtered.forEach(function(s){
              var badge = s.lang ? ' <span class="app-sede-lang-badge ' + _sedeLangClass(s.lang) + '" style="font-size:9px;vertical-align:middle;">' + esc(_sedeLangLabel(s.lang)) + '</span>' : '';
              var titleHtml = q ? highlight(s.title||"無題", q) : esc(s.title||"無題");
              html += '<div class="app-chat-search-item" data-sede-search-action="switch" data-sede-id="' + s.id + '">'
                + '<span class="ms">terminal</span>'
                + '<span class="app-chat-search-item-title">' + titleHtml + badge + '</span></div>';
            });
          }
          body.innerHTML = html;
        }
        overlay.innerHTML = '<div class="app-chat-search-box">'
          + '<div class="app-chat-search-header">'
          + '<span class="ms">search</span>'
          + '<input class="app-chat-search-input" type="text" placeholder="セッション名・言語・内容を検索..." autofocus />'
          + '<div class="app-chat-search-close"><span class="ms">close</span></div>'
          + '</div><div class="app-chat-search-body"></div></div>';
        document.body.appendChild(overlay);
        renderList("");
        var input = overlay.querySelector(".app-chat-search-input");
        input.addEventListener("input", function(){ renderList(input.value); });
        function close(){ overlay.remove(); }
        overlay.addEventListener("click", function(e){
          if (e.target === overlay) return close();
          if (e.target.closest(".app-chat-search-close")) return close();
          var act = e.target.closest("[data-sede-search-action]");
          if (act){
            var id = act.getAttribute("data-sede-id");
            close();
            if (id) _sedeSwitchSession(id);
          }
        });
        overlay.addEventListener("keydown", function(e){ if (e.key==="Escape") close(); });
        if (input) input.focus();
      }

      /* ── Sede Files Modal ── */
      function _sedeOpenFiles(){
        var sid = _sedeState.activeId;
        if (!sid){ uiAlert("セッションを選択してください。", { title:"Files" }); return; }
        var ses = _sedeState.sessions.find(function(x){ return x.id === sid; });
        var existing = document.querySelector(".app-chat-project-overlay.is-sede-files");
        if (existing) existing.remove();
        var overlay = document.createElement("div");
        overlay.className = "app-chat-project-overlay is-sede-files";
        function esc(s){ var d=document.createElement("div"); d.textContent=s; return d.innerHTML; }
        function render(){
          var files = _sedeGetFiles(sid);
          var body = overlay.querySelector(".app-chat-project-body");
          if (!body) return;
          var html = '<div class="app-chat-project-new" data-sede-file-action="add"><span class="ms">upload_file</span>ファイルを追加</div>';
          if (!files.length){
            html += '<div class="app-chat-search-empty">ファイルがまだありません。</div>';
          } else {
            files.forEach(function(f, i){
              html += '<div class="app-chat-project-item">'
                + '<span class="ms">description</span>'
                + '<div class="app-chat-project-item-info"><div class="app-chat-project-item-name">' + esc(f.name||"file") + '</div>'
                + '<div class="app-chat-project-item-meta">' + (f.size ? Math.round(f.size/1024) + ' KB' : '') + '</div></div>'
                + '<div class="app-chat-project-item-actions" style="opacity:1;">'
                + '<div class="app-chat-project-action-btn" data-sede-file-action="delete" data-file-idx="' + i + '"><span class="ms">delete</span></div>'
                + '</div></div>';
            });
          }
          body.innerHTML = html;
        }
        overlay.innerHTML = '<div class="app-chat-project-panel">'
          + '<div class="app-chat-project-header">'
          + '<span class="app-chat-project-header-title">Files — ' + esc((ses?.title)||"セッション") + '</span>'
          + '<div class="app-chat-project-close"><span class="ms">close</span></div>'
          + '</div><div class="app-chat-project-body"></div></div>';
        document.body.appendChild(overlay);
        render();
        function close(){ overlay.remove(); }
        overlay.addEventListener("click", function(e){
          if (e.target === overlay) return close();
          if (e.target.closest(".app-chat-project-close")) return close();
          var act = e.target.closest("[data-sede-file-action]");
          if (!act) return;
          var action = act.getAttribute("data-sede-file-action");
          if (action === "add"){
            var inp = document.createElement("input");
            inp.type = "file"; inp.multiple = true;
            inp.addEventListener("change", function(){
              var files = _sedeGetFiles(sid);
              Array.from(inp.files||[]).forEach(function(file){
                var reader = new FileReader();
                reader.onload = function(){
                  files.push({ name:file.name, size:file.size, type:file.type, content:reader.result, addedAt:Date.now() });
                  _sedeSaveFiles(sid, files);
                  render();
                };
                reader.readAsText(file);
              });
            });
            inp.click();
          } else if (action === "delete"){
            var idx = parseInt(act.getAttribute("data-file-idx"), 10);
            var files = _sedeGetFiles(sid);
            files.splice(idx, 1);
            _sedeSaveFiles(sid, files);
            render();
          }
        });
        overlay.addEventListener("keydown", function(e){ if (e.key==="Escape") close(); });
      }

      /* ── Terminal Confirm Dialog ── */
      function _sedeConfirmCommand(command){
        return uiConfirm("以下のコマンドを実行しますか？\n\n" + String(command||""), {
          title: "コマンド実行確認",
          okText: "✅ 実行",
          cancelText: "❌ キャンセル",
          danger: false
        });
      }

      /* ── Sede session options dropdown ── */
      function _sedeOpenSessionOptions(targetId, anchorEl){
        _chatCloseSessionOptions();
        var dropdown = document.createElement("div");
        dropdown.className = "xselect-menu app-chat-session-dropdown";
        dropdown.id = "appChatSessionDropdown";
        dropdown.style.cssText = "position:fixed;z-index:9999;min-width:180px;";
        dropdown.innerHTML =
          '<div class="xselect-option" role="button" data-sede-action="renameSession" data-sede-id="' + targetId + '"><span class="ms" style="font-size:18px;margin-right:6px;">edit</span>名前を変更</div>'
          + '<div class="xselect-option" role="button" data-sede-action="setLang" data-sede-id="' + targetId + '"><span class="ms" style="font-size:18px;margin-right:6px;">code</span>言語を設定</div>'
          + '<div class="xselect-option" role="button" data-sede-action="deleteSession" data-sede-id="' + targetId + '" style="color:var(--melta-danger, #ef4444);"><span class="ms" style="font-size:18px;margin-right:6px;color:var(--melta-danger, #ef4444);">delete</span>削除</div>';
        document.body.appendChild(dropdown);
        var rect = anchorEl.getBoundingClientRect();
        dropdown.style.left = Math.max(4, rect.right - 200) + "px";
        var top = rect.bottom + 4;
        if (top + 140 > window.innerHeight) top = rect.top - 140;
        dropdown.style.top = top + "px";
        setTimeout(function(){ document.addEventListener("click", _chatSessionDropdownOutside, true); }, 0);
      }

      /* FIX: Expose Sede session functions to window so the inline IIFE (sendMessage) can access them */
      window._sedeCreateSession = _sedeCreateSession;
      window._sedeSaveSessions = _sedeSaveSessions;
      window._sedeLoadSessions = _sedeLoadSessions;
      window._sedeRenderSidebar = _sedeRenderSidebar;
      window._sedeDeleteSession = _sedeDeleteSession;
      window._sedeRenameSession = _sedeRenameSession;
      window._sedeSwitchSession = _sedeSwitchSession;

      /* ── Sede action handler ── */
      function _sedeHandleAction(type, idRaw, e){
        var id = String(idRaw||"").trim();
        if (type === "newSession"){
          _sedeCreateSession("");
          return;
        }
        if (type === "search"){
          _sedeOpenSearch();
          return;
        }
        if (type === "files"){
          _sedeOpenFiles();
          return;
        }
        if (type === "terminal"){
          /* Scroll to terminal and focus it */
          var termEl = document.getElementById("sedeTerminal");
          if (termEl) termEl.scrollIntoView({ behavior: "smooth", block: "end" });
          var sedeIn = document.getElementById("sedeInputInline");
          if (sedeIn) sedeIn.focus();
          return;
        }
        if (type === "newProject"){
          if (typeof _sedeOpenProjectModal === "function") _sedeOpenProjectModal();
          return;
        }
        if (type === "reindex"){
          if (typeof _sedeReindex === "function") _sedeReindex();
          return;
        }
        if (type === "backToChat"){
          _chatSwitchToQuickChat();
          return;
        }
        if (type === "switchSession"){
          if (id) _sedeSwitchSession(id);
          return;
        }
        if (type === "sessionOptions"){
          var anchor = e ? e.target.closest(".app-sede-session-opts-btn") : null;
          if (id && anchor) _sedeOpenSessionOptions(id, anchor);
          return;
        }
        if (type === "renameSession"){
          _chatCloseSessionOptions();
          var newName = prompt("セッション名を入力", "");
          if (newName !== null && newName.trim()){ _sedeRenameSession(id, newName.trim()); _sedeRenderSidebar(); }
          return;
        }
        if (type === "setLang"){
          _chatCloseSessionOptions();
          var lang = prompt("使用言語を入力 (例: js, python, ts, html, go, rust)", "");
          if (lang !== null){
            var s = _sedeState.sessions.find(function(x){ return x.id === id; });
            if (s){ s.lang = lang.trim().toLowerCase(); s.updatedAt = Date.now(); _sedeSaveSessions(); _sedeRenderSidebar(); }
          }
          return;
        }
        if (type === "deleteSession"){
          _chatCloseSessionOptions();
          uiConfirm("このセッションを削除しますか？", { title:"セッションを削除", okText:"削除する", cancelText:"キャンセル", danger:true }).then(function(ok){
            if (ok){ _sedeDeleteSession(id); }
          });
          return;
        }
      }

      /* ══════════════════════════════════
         SETTINGS MODAL
         ══════════════════════════════════ */
      var CHAT_SETTINGS_KEY = "app.chat.settings.v1";
      function _chatGetSettings(){
        try{ var r = localStorage.getItem(CHAT_SETTINGS_KEY); return r ? JSON.parse(r) : {}; }catch{ return {}; }
      }
      function _chatSaveSetting(key, val){
        var s = _chatGetSettings();
        s[key] = val;
        try{ localStorage.setItem(CHAT_SETTINGS_KEY, JSON.stringify(s)); }catch{}
      }
      function _chatOpenSettingsModal(){
        var existing = document.querySelector(".app-chat-settings-overlay");
        if (existing) existing.remove();
        var s = _chatGetSettings();
        var theme = s.theme || "light";
        var fontSize = s.fontSize || "medium";
        var historyDays = s.historyDays || "unlimited";
        var streaming = s.streaming !== false;
        var sound = s.sound !== false;

        var overlay = document.createElement("div");
        overlay.className = "app-chat-settings-overlay";
        function segHtml(name, options, current){
          var h = '<div class="seg" data-settings-seg-group="' + name + '">';
          options.forEach(function(o){
            h += '<button type="button"' + (o.value===current?' class="active"':'') + ' data-settings-seg="' + name + '" data-val="' + o.value + '">' + o.label + '</button>';
          });
          return h + '</div>';
        }
        function toggleHtml(name, label, on){
          return '<div class="app-chat-settings-toggle-row">'
            + '<label class="toggle"><input type="checkbox" data-settings-toggle="' + name + '"' + (on?' checked':'') + ' /><span>' + label + '</span></label>'
            + '</div>';
        }

        overlay.innerHTML = '<div class="app-chat-settings-panel">'
          + '<div class="app-chat-settings-header"><span class="app-chat-settings-header-title">設定</span>'
          + '<div class="app-chat-settings-close"><span class="ms">close</span></div></div>'
          + '<div class="app-chat-settings-body">'
          + '<div class="app-chat-settings-row"><div class="app-chat-settings-label">テーマ</div>'
          + segHtml("theme", [{value:"light",label:"ライト"},{value:"dark",label:"ダーク"},{value:"system",label:"システム"}], theme) + '</div>'
          + '<div class="app-chat-settings-row"><div class="app-chat-settings-label">フォントサイズ</div>'
          + segHtml("fontSize", [{value:"small",label:"小"},{value:"medium",label:"中"},{value:"large",label:"大"}], fontSize) + '</div>'
          + '<div class="app-chat-settings-row"><div class="app-chat-settings-label">チャット履歴の保存期間</div>'
          + '<select data-settings-select="historyDays">'
          + '<option value="7"' + (historyDays==="7"?" selected":"") + '>7日</option>'
          + '<option value="30"' + (historyDays==="30"?" selected":"") + '>30日</option>'
          + '<option value="90"' + (historyDays==="90"?" selected":"") + '>90日</option>'
          + '<option value="unlimited"' + (historyDays==="unlimited"?" selected":"") + '>無制限</option>'
          + '</select></div>'
          + '<div class="app-chat-settings-row">' + toggleHtml("streaming", "ストリーミング", streaming) + '</div>'
          + '<div class="app-chat-settings-row">' + toggleHtml("sound", "サウンド", sound) + '</div>'
          + '</div></div>';

        document.body.appendChild(overlay);
        function close(){ overlay.remove(); }
        overlay.addEventListener("click", function(e){
          if (e.target === overlay) return close();
          if (e.target.closest(".app-chat-settings-close")) return close();
          var seg = e.target.closest("[data-settings-seg]");
          if (seg){
            var name = seg.getAttribute("data-settings-seg");
            var val = seg.getAttribute("data-val");
            _chatSaveSetting(name, val);
            var group = seg.closest(".seg");
            if (group) group.querySelectorAll("button").forEach(function(b){ b.classList.toggle("active", b.getAttribute("data-val")===val); });
            return;
          }
        });
        overlay.addEventListener("change", function(e){
          var tog = e.target.closest("[data-settings-toggle]");
          if (tog){
            _chatSaveSetting(tog.getAttribute("data-settings-toggle"), tog.checked);
            return;
          }
          var sel = e.target.closest("[data-settings-select]");
          if (sel) _chatSaveSetting(sel.getAttribute("data-settings-select"), sel.value);
        });
        overlay.addEventListener("keydown", function(e){ if (e.key==="Escape") close(); });
      }

      /* ══════════════════════════════════
         APP SYSTEM
         ══════════════════════════════════ */
      var CHAT_APPS_KEY = "app.chat.apps.v1";
      var _chatAppWindows = [];
      var _chatAppRegistry = [
        { id:"calendar", icon:"event", iconBg:"#ede9fe", iconColor:"#7c3aed", name:"カレンダー・リマインダー",
          desc:"学習スケジュールとリマインダーを管理",
          perms:["📅 カレンダーの読み取り・書き込み","🔔 リマインダーの作成・削除","📆 学習スケジュールの管理"] },
        { id:"voice", icon:"mic", iconBg:"#fce7f3", iconColor:"#db2777", name:"音声会話練習",
          desc:"AIと音声で会話練習",
          perms:["🎤 マイクへのアクセス","🔊 音声読み上げ機能","🗣 会話練習モードの有効化"] },
        { id:"webclip", icon:"content_cut", iconBg:"#f0fdf4", iconColor:"#16a34a", name:"Webクリップ",
          desc:"ブラウザからテキスト・URLをAIに送信",
          perms:["✂️ ブラウザからのテキスト・URL受信","📨 クリップ内容をチャットに自動送信","🔗 Chrome拡張機能との連携"] },
        { id:"texttranslate", icon:"translate", iconBg:"#dbeafe", iconColor:"#2563eb", name:"選択テキスト即翻訳",
          desc:"選択テキストを即翻訳・AI質問",
          perms:["🔍 選択テキストの受信","🌐 即時翻訳・解説","❓ AIへの即時質問送信"] },
        { id:"gdrive", icon:"cloud", iconBg:"#fef3c7", iconColor:"#d97706", name:"Google Drive連携",
          desc:"DriveのファイルをAIが解析・要約",
          perms:["📁 Google Driveファイルの読み取り","📄 ドキュメントのAI解析・要約","🔒 書き込み権限は不要（読み取りのみ）"] }
      ];
      function _chatGetSetupApps(){
        try{ var r = localStorage.getItem(CHAT_APPS_KEY); return r ? JSON.parse(r) : []; }catch{ return []; }
      }
      function _chatSaveSetupApps(list){
        try{ localStorage.setItem(CHAT_APPS_KEY, JSON.stringify(list||[])); }catch{}
      }

      /* ── Consent / Setup Popup ── */
      function _chatShowAppConsent(appId, onDone){
        var app = _chatAppRegistry.find(function(a){ return a.id === appId; });
        if (!app) return;
        var existing = document.querySelector(".app-consent-overlay");
        if (existing) existing.remove();
        var overlay = document.createElement("div");
        overlay.className = "app-consent-overlay";
        var permsHtml = (app.perms||[]).map(function(p){ return '<div class="app-consent-perm">' + p + '</div>'; }).join("");
        var avatarHtml = '';
        try{
          var prof = (_appSocialState && _appSocialState.profile) || {};
          var url = prof.avatarUrl || "";
          var fallback = (typeof _appAvatarFallbackText === "function") ? _appAvatarFallbackText(prof.displayName||"U", prof.nickname||"") : "U";
          avatarHtml = url
            ? '<div class="app-consent-user-icon"><img src="' + url + '" /></div>'
            : '<div class="app-consent-user-icon">' + fallback + '</div>';
        }catch(e){ avatarHtml = '<div class="app-consent-user-icon">U</div>'; }

        overlay.innerHTML = '<div class="app-consent-panel">'
          + '<div class="app-consent-icons">'
          + avatarHtml
          + '<span class="ms app-consent-arrow">sync_alt</span>'
          + '<div class="app-consent-app-icon" style="background:' + app.iconBg + ';color:' + app.iconColor + ';"><span class="ms">' + app.icon + '</span></div>'
          + '</div>'
          + '<div class="app-consent-title">' + app.name + '</div>'
          + '<div class="app-consent-subtitle">VocabuQuiz が以下の権限をリクエストしています</div>'
          + '<div class="app-consent-perms">' + permsHtml + '</div>'
          + '<div class="app-consent-actions">'
          + '<div class="app-consent-btn is-cancel" data-consent="cancel">拒否</div>'
          + '<div class="app-consent-btn is-accept" data-consent="accept">同意して連携</div>'
          + '</div></div>';
        document.body.appendChild(overlay);
        function close(){ overlay.remove(); }
        overlay.addEventListener("click", function(e){
          if (e.target === overlay) return close();
          var btn = e.target.closest("[data-consent]");
          if (!btn) return;
          var act = btn.getAttribute("data-consent");
          close();
          if (act === "accept"){
            var list = _chatGetSetupApps();
            if (list.indexOf(appId) === -1){ list.push(appId); _chatSaveSetupApps(list); }
            if (typeof onDone === "function") onDone(true);
          } else {
            if (typeof onDone === "function") onDone(false);
          }
        });
        overlay.addEventListener("keydown", function(e){ if (e.key==="Escape") close(); });
      }

      /* ── App List Modal ── */
      function _chatOpenAppList(){
        var existing = document.querySelector(".app-chat-app-overlay");
        if (existing) existing.remove();
        var overlay = document.createElement("div");
        overlay.className = "app-chat-app-overlay";
        function render(){
          var setupApps = _chatGetSetupApps();
          var body = overlay.querySelector(".app-chat-app-body");
          if (!body) return;
          var html = '';
          _chatAppRegistry.forEach(function(app){
            var done = setupApps.indexOf(app.id) !== -1;
            html += '<div class="app-chat-app-item" data-app-id="' + app.id + '">'
              + '<div class="app-chat-app-icon" style="background:' + app.iconBg + ';color:' + app.iconColor + ';"><span class="ms">' + app.icon + '</span></div>'
              + '<div class="app-chat-app-info"><div class="app-chat-app-name">' + app.name + '</div>'
              + '<div class="app-chat-app-desc">' + app.desc + '</div></div>'
              + (done
                ? '<span class="app-chat-app-setup-btn is-done">連携済み</span>'
                : '<span class="app-chat-app-setup-btn" data-app-action="setup" data-app-id="' + app.id + '">セットアップ</span>')
              + '</div>';
          });
          body.innerHTML = html;
        }
        overlay.innerHTML = '<div class="app-chat-app-panel">'
          + '<div class="app-chat-app-header"><span class="ms">grid_view</span>'
          + '<span class="app-chat-app-header-title">App</span>'
          + '<div class="app-chat-settings-close"><span class="ms">close</span></div></div>'
          + '<div class="app-chat-app-body"></div></div>';
        document.body.appendChild(overlay);
        render();
        function close(){ overlay.remove(); }
        overlay.addEventListener("click", function(e){
          if (e.target === overlay) return close();
          if (e.target.closest(".app-chat-settings-close")) return close();
          var setupBtn = e.target.closest("[data-app-action='setup']");
          if (setupBtn){
            var appId = setupBtn.getAttribute("data-app-id");
            _chatShowAppConsent(appId, function(ok){ if (ok) render(); });
            return;
          }
          var item = e.target.closest("[data-app-id]");
          if (item && !item.querySelector("[data-app-action]")){
            var id = item.getAttribute("data-app-id");
            if (_chatGetSetupApps().indexOf(id) !== -1){ close(); _chatOpenAppWindow(id); }
          }
        });
        overlay.addEventListener("keydown", function(e){ if (e.key==="Escape") close(); });
      }

      /* ── App Window Bodies ── */
