              switchTokens: Array.isArray(item?.switch?.tokens) ? item.switch.tokens : [],
              switchTokensText: Array.isArray(item?.switch?.tokens) ? item.switch.tokens.join(" / ") : String(item?.switchTokensText || "").trim(),
              selectedAiImage: String(item?.selectedAiImage || "").trim(),
