        _presetEngineState.editingPresetId = pid;
        _presetEngineState.savedPresetId = pid;
        _presetEngineState.savedPresetName = String(preset.name || "My Preset").trim() || "My Preset";
        _presetEngineState.selectedQuestionIndex = 0;
        _presetEngineState.pendingImageIndex = -1;
        _presetEngineState.pendingAssetIndex = -1;
        _presetEngineState.pendingChoiceImageChoiceIndex = -1;
