            _menuState.memoCheck.selectedBlock = txt;
            document.querySelectorAll("#menuPanel [data-memo-block], #appRightDrawer [data-memo-block]").forEach(x => x.classList.toggle("is-selected", x === memoBlock));
            _memoAddPickedBlock(txt);
