        load.stage = String(stage || "boot");
        load.context = String(options?.context || load.context || "");
        if (typeof options?.mapId !== "undefined") load.mapId = String(options.mapId || "").toLowerCase();
        if (typeof options?.modeLabel !== "undefined") load.modeLabel = String(options.modeLabel || "");
        if (typeof options?.presetLabel !== "undefined") load.presetLabel = String(options.presetLabel || "");
        load.title = String(options?.title || "VocabuSurvival");
        load.subtitle = String(options?.subtitle || meta.subtitle || "Loading arena...");
        load.stageText = String(options?.stageText || meta.subtitle || "Preparing match...");
        load.metaText = String(options?.metaText || "");
        load.progress = Math.max(Number(load.progress || 0), Number(options?.progress ?? meta.progress ?? 0));
        load.hintRotatedAt = now;
        _rtBattle3dRenderLoading();
