          if (_rtBattle3dIsOpen()) _rtBattle3dSetLoadingStage("match", { context: "match_start", progress: 58 });
          b.countdownStartAtMs = Math.max(0, Number(msg?.startAtMs || 0));
          b.countdownEndsAtMs = Math.max(0, Number(msg?.endsAtMs || 0));
          b.quizOpen = false;
