      async function _rtBattle3dV9InviteUser(targetUserId){
        const uid = Math.max(0, Number(targetUserId || 0));
        if (!uid) return;
        const b = _rtBattle3dV9State();
        const p9 = b.p9 || {};
        if (!(p9.inviteBusyUsers instanceof Set)) p9.inviteBusyUsers = new Set();
        const key = String(uid);
        if (p9.inviteBusyUsers.has(key)) return;
        const st = _rtBattleState();
        const roomCode = String(st?.room?.roomId || st?.roomId || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 16);
        if (!roomCode){
          try{ uiToast("ルームコードが取得できません。"); }catch(_){}
          return;
        }
        p9.inviteBusyUsers.add(key);
        _rtBattle3dRenderLobbyPanel();
        try{
          const body = await _appApiJson("/api/survival/invite", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ targetUserId: uid, roomId: roomCode })
          });
          if (!body?.ok) throw new Error(String(body?.message || "招待に失敗しました。"));
          p9.inviteSentAtByUser[key] = Date.now();
          if (body?.throttled){
            try{ uiToast("このユーザーへの招待通知は本日の上限に達しています。"); }catch(_){}
          } else {
            const name = String(asArray(p9.inviteFollowers).find((row) => Math.max(0, Number(row?.userId || 0)) === uid)?.displayName || "");
            try{ uiToast(name ? `${name}さんに招待を送信しました。` : "招待を送信しました。"); }catch(_){}
          }
        } catch (err){
          try{ uiToast(String(err?.message || "招待に失敗しました。")); }catch(_){}
        } finally {
          p9.inviteBusyUsers.delete(key);
          _rtBattle3dRenderLobbyPanel();
        }
      }
