      function _rtBattle3dV9EnsureLobbyDecor(){
        const b = _rtBattle3dV9State();
        const rt = b.runtime || {};
        const THREE = window.THREE;
        if (!THREE || !rt.scene) return null;
        if (rt.v9LobbyDecor && rt.v9LobbyDecor.group) return rt.v9LobbyDecor;
        const group = new THREE.Group();
        group.name = "rt3d-v9-lobby-decor";
        const platform = new THREE.Mesh(
          new THREE.CylinderGeometry(4.4, 5.2, 0.3, 24),
          _rtBattle3dV8Mat(THREE, 0x2c3650, 0.56, "metal", 0.22)
        );
        platform.position.set(0, -0.08, 0.2);
        group.add(platform);
        const ring = new THREE.Mesh(
          new THREE.TorusGeometry(3.4, 0.08, 10, 32),
          _rtBattle3dV8Mat(THREE, 0x67a8ff, 0.35, "panel", 0.2)
        );
        ring.rotation.x = Math.PI * 0.5;
        ring.position.set(0, 0.02, 0.2);
        group.add(ring);
        const padGroup = new THREE.Group();
        const pads = [];
        for (let i = 0; i < 8; i += 1){
          const pad = new THREE.Mesh(
            new THREE.CylinderGeometry(0.34, 0.42, 0.06, 18),
            _rtBattle3dV8Mat(THREE, 0x5f8be0, 0.36, "panel", 0.12)
          );
          pad.rotation.x = Math.PI * 0.5;
          pad.position.set(0, 0.03, 0);
          padGroup.add(pad);
          pads.push(pad);
        }
        group.add(padGroup);
        const backWall = new THREE.Mesh(
          new THREE.BoxGeometry(10.2, 0.46, 0.18),
          _rtBattle3dV8Mat(THREE, 0x1d2638, 0.82, "panel", 0.08)
        );
        backWall.position.set(0, 0.2, -3.9);
        backWall.userData.noCamBlock = true;
        group.add(backWall);
        const lightBars = [];
        for (let i = 0; i < 4; i += 1){
          const bar = new THREE.Mesh(
            new THREE.BoxGeometry(0.18, 3.0, 0.06),
            _rtBattle3dV8Mat(THREE, 0x6cb4ff, 0.28, "solid", 0.0)
          );
          bar.position.set(-2.4 + (i * 1.6), 2.0, -3.76);
          if (bar.material && bar.material.emissive) {
            bar.material.emissive = new THREE.Color(0x2e77d8);
            bar.material.emissiveIntensity = 0.42;
          }
          group.add(bar);
          lightBars.push(bar);
        }
        rt.scene.add(group);
        rt.v9LobbyDecor = { group, pads, lightBars, ring };
        return rt.v9LobbyDecor;
      }
      function _rtBattle3dV9RenderLobbyTags(tsNow){
        const st = _rtBattleState();
        const phase = String(st.phase || "lobby");
        const tags = document.getElementById("rt3dLobbyTags");
        const b = _rtBattle3dV9State();
        const rt = b.runtime || {};
        const THREE = window.THREE;
        if (!(tags instanceof HTMLElement) || !THREE || !rt.camera || !rt.wrap){
          return;
        }
        if (phase === "lobby" || (phase !== "countdown" && phase !== "playing" && phase !== "result")){
          tags.innerHTML = "";
          return;
        }
        const items = [];
        const me = _rtBattleMePlayer();
        if (rt.localMesh && me){
          items.push({
            nick: String(me.nick || st.nickname || "You"),
            handle: String(me.handle || ""),
            ready: !!me.ready,
            pos: rt.localMesh.position
          });
        }
        const others = asArray(st.players).filter((p) => !!p && !!p.connected && !_rtBattlePlayerMatchesMe(p)).slice(0, 7);
        others.forEach((p) => {
          const key = _rtBattle3dV9PlayerKey(p);
          const mesh = key ? (b.remoteMeshes && b.remoteMeshes[key]) : null;
          if (!mesh) return;
          items.push({
            nick: String(p.nick || "Guest"),
            handle: String(p.handle || ""),
            ready: !!p.ready,
            pos: mesh.position
          });
        });
        const w = Math.max(1, Number(rt.wrap.clientWidth || 1));
        const h = Math.max(1, Number(rt.wrap.clientHeight || 1));
        const rows = [];
        for (const item of items){
          const world = new THREE.Vector3(Number(item.pos.x || 0), Number(item.pos.y || 0) + 1.6, Number(item.pos.z || 0));
          world.project(rt.camera);
          if (world.z < -1 || world.z > 1) continue;
          const x = (world.x * 0.5 + 0.5) * w;
          const y = (-world.y * 0.5 + 0.5) * h;
          if (!(x >= -120 && x <= w + 120 && y >= -120 && y <= h + 120)) continue;
          const handle = item.handle ? `@${item.handle.replace(/^@+/, "")}` : "@guest";
          rows.push(`<div class="b3d-lobby-tag${item.ready ? " is-ready" : ""}" style="left:${Math.round(x)}px;top:${Math.round(y)}px;">
            <strong>${_escapeHtml(item.nick)}</strong><span>${_escapeHtml(handle)}</span>
          </div>`);
        }
        const html = rows.join("");
        if (tags.dataset.hash !== html){
          tags.dataset.hash = html;
          tags.innerHTML = html;
        }
      }
      function _rtBattle3dV9UpdateLobbyPresentation(tsNow){
        const st = _rtBattleState();
        const phase = String(st.phase || "lobby");
        const b = _rtBattle3dV9State();
        const rt = b.runtime || {};
        const THREE = window.THREE;
        if (!THREE || !rt.scene) return;
        const decor = _rtBattle3dV9EnsureLobbyDecor();
        if (decor && decor.group){
          decor.group.visible = (phase === "lobby");
          if (phase === "lobby"){
            const t = Number(tsNow || performance.now()) * 0.001;
            if (decor.ring) decor.ring.rotation.z += 0.0035;
            asArray(decor.lightBars).forEach((bar, idx) => {
              const pulse = 0.25 + Math.max(0, Math.sin(t * 1.7 + idx * 0.9)) * 0.32;
              if (bar && bar.material && "emissiveIntensity" in bar.material) bar.material.emissiveIntensity = pulse;
            });
          }
        }
        if (phase !== "lobby") return;
        const others = asArray(st.players).filter((p) => !!p && !!p.connected && !_rtBattlePlayerMatchesMe(p)).slice(0, 7);
        others.forEach((p, idx) => {
          const key = _rtBattle3dV9PlayerKey(p);
          const mesh = key ? (b.remoteMeshes && b.remoteMeshes[key]) : null;
          if (!mesh) return;
          const slot = _rtBattle3dV9MapSlot(idx);
          const k = 0.12;
          mesh.position.x += (slot.x - mesh.position.x) * k;
          mesh.position.y += (0 - mesh.position.y) * k;
          mesh.position.z += (slot.z - mesh.position.z) * k;
          mesh.rotation.y += (Math.PI - mesh.rotation.y) * 0.12;
          if (mesh.scale && typeof mesh.scale.set === "function"){
            mesh.scale.set(0.94, 0.94, 0.94);
          }
        });
        if (decor && Array.isArray(decor.pads)){
          const meReady = !!_rtBattleMePlayer()?.ready;
          const mePad = decor.pads[0];
          if (mePad){
            mePad.visible = true;
            mePad.position.set(0, 0.04, 1.55);
            if (mePad.material?.color){
              mePad.material.color.setHex(meReady ? 0x52d792 : 0x5f8be0);
            }
            if ("emissiveIntensity" in (mePad.material || {})){
              const pulse = 0.16 + Math.max(0, Math.sin((Number(tsNow || performance.now()) * 0.0048))) * (meReady ? 0.4 : 0.18);
              mePad.material.emissiveIntensity = pulse;
            }
          }
          others.forEach((p, idx) => {
            const pad = decor.pads[idx + 1];
            if (!pad) return;
            const slot = _rtBattle3dV9MapSlot(idx);
            pad.visible = true;
            pad.position.set(slot.x, 0.04, slot.z + 0.22);
          });
          for (let i = others.length + 1; i < decor.pads.length; i += 1){
            if (decor.pads[i]) decor.pads[i].visible = false;
          }
        }
      }
      async function _rtBattle3dV9TryLandscapeLock(requestFullscreen = false){
        if (!_rtBattle3dV9NeedsLandscape()) return false;
        let ok = false;
        const root = document.getElementById("rt3dOverlay");
        const shell = root ? root.querySelector(".b3d-shell") : null;
        if (requestFullscreen){
          try{
            if (!document.fullscreenElement && shell && typeof shell.requestFullscreen === "function"){
              await shell.requestFullscreen({ navigationUI: "hide" });
            }
          }catch(_){}
        }
        try{
          if (screen?.orientation && typeof screen.orientation.lock === "function"){
            await screen.orientation.lock("landscape");
            ok = true;
          }
        }catch(_){}
        _rtBattle3dV9UpdateRotateOverlay();
        return ok;
      }
      function _rtBattle3dV9UpdateRotateOverlay(){
        _rtBattle3dV9EnsureAuxDom();
        const root = document.getElementById("rt3dOverlay");
        const overlay = document.getElementById("rt3dRotateOverlay");
        if (!(root instanceof HTMLElement) || !(overlay instanceof HTMLElement)) return;
        const mode = _rtBattle3dV9RotateMode();
        const p9 = _rtBattle3dV9State().p9 || {};
        p9.rotateMode = mode;
        const show = (mode === "guide" || mode === "block");
        overlay.classList.toggle("is-open", show);
        overlay.setAttribute("aria-hidden", show ? "false" : "true");
        root.classList.toggle("is-rotate-block", mode === "block");
        overlay.dataset.mode = mode;
        const title = document.getElementById("rt3dRotateTitle");
        const text = document.getElementById("rt3dRotateText");
        if (title) title.textContent = mode === "block" ? "横向きにしないとプレイできません" : "端末を横向きにしてください";
        if (text) {
          text.textContent = mode === "block"
            ? "ゲーム中はランドスケープ必須です。横向きにすると自動で再開します。"
            : "ロビーは横画面推奨です。対応ブラウザでは全画面+向き固定を試せます。";
        }
      }
